import * as React from 'react';
import useEmblaCarousel from 'embla-carousel-react';
import { ArrowLeft, ArrowRight } from 'lucide-react';
import styled from 'styled-components';

/**
 * shadcn-style carousel for the extension.
 * Same component API/behaviour as the frontend shadcn carousel (embla engine:
 * swipe / drag / loop / snap), but styled with styled-components since the
 * extension does not use Tailwind.
 */

const CarouselContext = React.createContext(null);

function useCarousel() {
  const context = React.useContext(CarouselContext);

  if (!context) {
    throw new Error('useCarousel must be used within a <Carousel />');
  }

  return context;
}

const Root = styled.div`
  position: relative;
`;

const Viewport = styled.div`
  overflow: hidden;
  height: 100%;
  width: 100%;
`;

const Track = styled.div`
  display: flex;
  height: 100%;
  flex-direction: ${({ $orientation }) =>
    $orientation === 'vertical' ? 'column' : 'row'};
`;

const Slide = styled.div`
  min-width: 0;
  flex: 0 0 100%;
`;

const NavButton = styled.button`
  all: unset;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 9999px;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  cursor: pointer;
  box-shadow: 0px 1px 2px rgba(0, 0, 0, 0.3);
  z-index: 2;

  svg {
    width: 12px;
    height: 12px;
  }

  &:disabled {
    opacity: 0.4;
    cursor: default;
  }
`;

function Carousel({
  orientation = 'horizontal',
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}) {
  const [carouselRef, api] = useEmblaCarousel(
    {
      ...opts,
      axis: orientation === 'horizontal' ? 'x' : 'y',
    },
    plugins,
  );
  const [canScrollPrev, setCanScrollPrev] = React.useState(false);
  const [canScrollNext, setCanScrollNext] = React.useState(false);

  const onSelect = React.useCallback((api) => {
    if (!api) return;
    setCanScrollPrev(api.canScrollPrev());
    setCanScrollNext(api.canScrollNext());
  }, []);

  const scrollPrev = React.useCallback(() => {
    api?.scrollPrev();
  }, [api]);

  const scrollNext = React.useCallback(() => {
    api?.scrollNext();
  }, [api]);

  const handleKeyDown = React.useCallback(
    (event) => {
      if (event.key === 'ArrowLeft') {
        event.preventDefault();
        scrollPrev();
      } else if (event.key === 'ArrowRight') {
        event.preventDefault();
        scrollNext();
      }
    },
    [scrollPrev, scrollNext],
  );

  React.useEffect(() => {
    if (!api || !setApi) return;
    setApi(api);
  }, [api, setApi]);

  React.useEffect(() => {
    if (!api) return;
    onSelect(api);
    api.on('reInit', onSelect);
    api.on('select', onSelect);

    return () => {
      api?.off('select', onSelect);
    };
  }, [api, onSelect]);

  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api: api,
        opts,
        orientation:
          orientation || (opts?.axis === 'y' ? 'vertical' : 'horizontal'),
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
      }}
    >
      <Root
        onKeyDownCapture={handleKeyDown}
        className={className}
        role="region"
        aria-roledescription="carousel"
        {...props}
      >
        {children}
      </Root>
    </CarouselContext.Provider>
  );
}

function CarouselContent({ className, style, ...props }) {
  const { carouselRef, orientation } = useCarousel();

  return (
    <Viewport ref={carouselRef}>
      <Track
        $orientation={orientation}
        className={className}
        style={style}
        {...props}
      />
    </Viewport>
  );
}

function CarouselItem({ className, style, ...props }) {
  return (
    <Slide
      role="group"
      aria-roledescription="slide"
      className={className}
      style={style}
      {...props}
    />
  );
}

function CarouselPrevious({ className, style, ...props }) {
  const { scrollPrev, canScrollPrev } = useCarousel();

  return (
    <NavButton
      className={className}
      style={style}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      aria-label="Previous slide"
      {...props}
    >
      <ArrowLeft />
    </NavButton>
  );
}

function CarouselNext({ className, style, ...props }) {
  const { scrollNext, canScrollNext } = useCarousel();

  return (
    <NavButton
      className={className}
      style={style}
      disabled={!canScrollNext}
      onClick={scrollNext}
      aria-label="Next slide"
      {...props}
    >
      <ArrowRight />
    </NavButton>
  );
}

export {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
  useCarousel,
};
