      abortControllerRef.current = new AbortController();
      // const controller = new AbortController();
      const { signal } = abortControllerRef.current;
      pollListingDetails(true, currentIaId, timeRange, signal);

      return () => {
        console.log('Aborting previous poll due to timeRange change');
        abortControllerRef.current.abort(); // Abort previous request when dependencies change
      };
