import React from 'react';
import { Skeleton } from '@mui/material';
import { BorderWrapper, StyledWrapper } from './StyledWrapper';
import RightSidePaneTooltip from '@components/CustomToolTip/RightSidePaneTooltip';
import LockIconDark from '@components/LockIconDark';

const DetailsTable = ({
  activeButton,
  details,
  conversionGrid,
  reviewRatio,
  loading,
}) => {
  const addPercentage = (child) => {
    if (child.heading === 'Conversion rate')
      return `${child.value > 0 ? child.value : '0'}%`;
    if (child.heading === 'Visibility score')
      return `${child.value === null ? 0 : child.value}%`;

    return child.value;
  };

  const addDollar = (child) => {
    if (child.heading === 'Mo. Revenue')
      return `${
        child.currencySymbol && child.currencySymbol
      }${child.value?.toLocaleString('en-US')}`;
    if (child.heading === 'Listing age' || child.heading === 'Shop Age') {
      return `${child.value} months`;
    }

    return child.value?.toLocaleString('en-US');
  };
  return (
    <StyledWrapper $conversionGrid={conversionGrid}>
      {!conversionGrid &&
        details.map((child) => (
          <div
            key={child.heading}
            className={
              activeButton === 'Listing Details'
                ? 'box-wrap box-wrap-listing-details'
                : 'box-wrap'
            }
          >
            <BorderWrapper>
              {loading ? (
                <Skeleton
                  variant="rectangular"
                  width={activeButton === 'Shop Details' ? 100 : 60}
                  height={50}
                  animation="wave"
                  sx={{ marginLeft: '1.05rem' }}
                />
              ) : (
                <>
                  <RightSidePaneTooltip
                    PopperProps={{
                      style: {
                        zIndex: 9999999,
                      },
                    }}
                    title={child.tooltip}
                    placement="top"
                    arrow
                  >
                    <p className="heading">{child.heading}</p>
                  </RightSidePaneTooltip>
                  <p className="value">
                    {child.value === 'Please upgrade' ? (
                      <LockIconDark />
                    ) : (
                      addDollar(child)
                    )}
                  </p>
                </>
              )}
            </BorderWrapper>
          </div>
        ))}

      {activeButton === 'Listing Details' &&
        conversionGrid &&
        details.map((child, index) => (
          <div key={child.heading} className="box-wrap">
            <BorderWrapper $conversionGrid $index={index}>
              {loading ? (
                <Skeleton
                  variant="rectangular"
                  width={
                    index === 0
                      ? 80
                      : index === 1
                        ? 90
                        : index === 2
                          ? 110
                          : index === 3
                            ? 150
                            : 0
                  }
                  height={50}
                  animation="wave"
                  sx={{ marginLeft: '1.05rem' }}
                />
              ) : (
                <>
                  {index === 0 && (
                    <>
                      <RightSidePaneTooltip
                        PopperProps={{
                          style: {
                            zIndex: 9999999,
                          },
                        }}
                        title={child.tooltip}
                        placement="top"
                        arrow
                      >
                        <p className="heading">{child.heading}</p>
                      </RightSidePaneTooltip>
                      <p className="conversionGridValuesWithMargin">
                        {child.value === 'Please upgrade' ? (
                          <LockIconDark />
                        ) : (
                          addPercentage(child)
                        )}
                      </p>
                    </>
                  )}
                  {index === 1 && (
                    <>
                      <RightSidePaneTooltip
                        PopperProps={{
                          style: {
                            zIndex: 9999999,
                          },
                        }}
                        title={child.tooltip}
                        placement="top"
                        arrow
                      >
                        <p className="heading">{child.heading}</p>
                      </RightSidePaneTooltip>
                      <p className="conversionGridValuesWithMargin">
                        {child.value}
                      </p>
                    </>
                  )}
                  {index === 2 && (
                    <>
                      <RightSidePaneTooltip
                        PopperProps={{
                          style: {
                            zIndex: 9999999,
                          },
                        }}
                        title={child.tooltip}
                        placement="top"
                        arrow
                      >
                        <p className="heading">{child.heading}</p>
                      </RightSidePaneTooltip>
                      <div style={{ display: 'flex', alignItems: 'center' }}>
                        {child.value === 'Please upgrade' ? (
                          <p className="conversionGridValuesWithMargin">
                            <LockIconDark />
                          </p>
                        ) : (
                          <>
                            {child.value !== 0 && (
                              <div
                                style={{
                                  width: '50%',
                                  height: '0.375rem',
                                  backgroundColor: '#F2F2F2',
                                  borderRadius: '100px',
                                }}
                                className="linerProgressbar"
                                role="progressbar"
                              >
                                <div
                                  style={{
                                    height: '100%',
                                    borderRadius: '100px',
                                    backgroundColor: '#3D98F2',
                                    width: `${child.value > 100 ? 100 : child.value}%`,
                                  }}
                                ></div>
                              </div>
                            )}
                            <p
                              className={
                                child.value !== 0
                                  ? 'conversionGridValues'
                                  : 'conversionGridValuesWithMargin'
                              }
                            >
                              {addPercentage(child)}
                            </p>
                          </>
                        )}
                      </div>
                    </>
                  )}
                  {index === 3 && (
                    <>
                      <RightSidePaneTooltip
                        PopperProps={{
                          style: {
                            zIndex: 9999999,
                          },
                        }}
                        title={child.tooltip}
                        placement="top"
                        arrow
                      >
                        <p className="heading">{child.heading}</p>
                      </RightSidePaneTooltip>
                      <p className="conversionGridValuesWithMargin">
                        {reviewRatio()}
                      </p>
                    </>
                  )}
                </>
              )}
            </BorderWrapper>
          </div>
        ))}
    </StyledWrapper>
  );
};

export default DetailsTable;
