/*global chrome*/
import { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import SlideTabs from '../../components/SlideTabs';
import EtsyCalForm from '../../components/EtsyCalForm';
import EtsyCalDisplay from '../../components/EtsyCalDisplay';
import {
  changeActiveMainMenu,
  changeActiveSubMenu,
  removeFeaturePage,
} from '../../store/slices/sidebarSlice';
import {
  changeActiveDiscountUnit,
  setActivePage,
} from '../../store/slices/utilitySlice';
import { StyledWrapper } from './StyledWrapper';
import { MAIN_MENU, SUB_MENU } from '../../constants/menuList';
import SimpleModal from '../../components/SimpleModal/SimpleModal';
import { openCalculator } from '../../helper/openCalculator';

const EtsyCalculator = () => {
  const dispatch = useDispatch();

  const crossCircleLg = chrome.runtime.getURL('svg/cross-circle-lg.svg');

  const [etsyCalState, setEtsyCalState] = useState({
    salesPrice: 0,
    shippingPrice: 0,
    discounts: 0,
    costOfItem: 0,
    shippingCost: 0,
    materialCostItem1: 0,
    materialCostItem2: 0,
    labourCost: 0,
    packagingCost: 0,
    advertising: 'None', // Other possible values - 'Etsy Ads' | 'Offsite Ads'!
    etsyAds: 0,
    offSiteAdCost: '12%', // Other possible value is 15%
    paymentMethod: 'Paypal', // Other possible value - 'Etsy Payment'
  });

  const activeCalculatorType = useSelector(
    (state) => state.utilities.etsyCalculatorType,
  );

  const handleClose = () => {
    dispatch(removeFeaturePage('etsyCalculator'));
  };

  useEffect(() => {
    dispatch(setActivePage('/etsy-calculator'));
    dispatch(
      changeActiveSubMenu({
        value: SUB_MENU.ETSY_CALCULATOR,
        subMenuIndex: 3,
      }),
    );
    dispatch(changeActiveMainMenu(MAIN_MENU.RESEARCH_TOOLS));

    //eslint-disable-next-line
  }, []);

  useEffect(() => {
    let urlLink = window.location.href;
    if (urlLink.includes('/listing/')) {
      const calculatorResult = openCalculator();
      if (calculatorResult) {
        setEtsyCalState((prevState) => {
          return {
            ...prevState,
            salesPrice: Number(calculatorResult.salesPrice),
            costOfItem: Number(calculatorResult.itemCost),
            shippingPrice: Number(calculatorResult.shippingPrice),
            shippingCost: Number(calculatorResult.shippingCostOfOrder),
            discounts: isNaN(calculatorResult.discountPercentage)
              ? Number(calculatorResult.discountInAmt)
              : Number(calculatorResult.discountPercentage),
          };
        });
        if (isNaN(calculatorResult.discountPercentage)) {
          dispatch(changeActiveDiscountUnit('dollar'));
        } else {
          dispatch(changeActiveDiscountUnit('percent'));
        }
      }
    }
  }, []);

  return (
    <SimpleModal open={true} handleClose={handleClose}>
      <StyledWrapper>
        <div className="etsy-cal-main-title">
          <div className="title">Profit Calculator</div>
          <img
            src={crossCircleLg}
            alt="Cross Icon"
            className="cross-circle"
            onClick={handleClose}
          />
        </div>
        <div className="etsy-calculator-header">
          <div className="ec-header-text">Profit Calculator</div>
          <div className="ec-header-tab-switch">
            <SlideTabs tabsType="etsyCalculator" />
          </div>
        </div>
        <div className="etsy-calculator-main">
          <EtsyCalForm
            activeCalculatorType={activeCalculatorType}
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
          />
          <EtsyCalDisplay
            activeCalculatorType={activeCalculatorType}
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
          />
        </div>
      </StyledWrapper>
    </SimpleModal>
  );
};

export default EtsyCalculator;
