/*global chrome*/
import React, { useState, useRef, useEffect } from 'react';
import { Divider, Popover } from '@mui/material';
import { useSelector, useDispatch } from 'react-redux';
import * as amplitude from '@amplitude/analytics-browser';
import {
  getSingleListingDetails,
  toggleSidebarTrendsModal,
  updatePASingleListingTimeRange,
} from '../../../store/slices/utilitySlice';
import { StyledWrapper, StyledDatePicker } from './StyledWrapper';
import { getEventData } from '../../../utils/eventData';
import { isContentLocked } from '../../../utils/isContentLocked';
import LockIconDark from '../../../components/LockIconDark/LockIconDark';
import { changeIframeUrl, toggleRightPane } from '../../../store/slices/sidebarSlice';
import LockIconTooltip from '../../CustomToolTip/LockIconTooltip';

const DateRangePicker = ({ datePickerExplicitWidth }) => {
  const dispatch = useDispatch();
  const calendarIcon = chrome.runtime.getURL('svg/calender-icon.svg');
  const downIcon = chrome.runtime.getURL('svg/arrow-down-new.svg');
  const time_range = useSelector((state) => state.utilities.timeRange);
  const { userData} = useSelector((state) => state.user);
  const { listingDetailsData, isSidebarTrendsModal } = useSelector((state) => state.utilities);
  let UrlLink = window.location.href;

  const DateRanges = [
    { label: 'Last month', slug: 'last_1_month', minAge: 1 },
    { label: 'Last 3 months', slug: 'last_3_months', minAge: 3 },
    { label: 'Last 6 months', slug: 'last_6_months', minAge: 6 },
    { label: 'Last 12 months', slug: 'last_12_months', minAge: 12 },
    { label: 'Last 24 months', slug: 'last_24_months', minAge: 24 },
    { label: 'All time', slug: 'all_time', minAge: 0 },
  ];

  const getDateRange = (range) => {
    const dateOptions = { month: 'short', day: 'numeric', year: 'numeric' };
    const today = new Date();
    let endDate = new Date();
    endDate.setDate(today.getDate() - 7); // End date is always 7 days back
    let startDate = new Date();
    switch (range) {
      case 'last_30_days':
        startDate.setDate(today.getDate() - 37); // 37 days ago
        break;
      case 'last_1_month':
        // Get the first day of the current month
        let firstDayOfCurrentMonth = new Date(
          today.getFullYear(),
          today.getMonth(),
          1,
        );
        // Get the last day of the previous month
        endDate = new Date(firstDayOfCurrentMonth - 1);
        // Get the first day of the previous month
        startDate = new Date(endDate.getFullYear(), endDate.getMonth(), 1);
        break;
      case 'last_3_months':
        startDate = new Date(today);
        startDate.setMonth(today.getMonth() - 3);
        startDate.setDate(startDate.getDate() - 6);
        break;
      case 'last_6_months':
        startDate = new Date(today);
        startDate.setMonth(today.getMonth() - 6); // Start from the 1st of 6 months ago
        startDate.setDate(startDate.getDate() - 6);
        break;
      case 'last_12_months':
        startDate = new Date(today);
        startDate.setFullYear(today.getFullYear() - 1); // Start from 12 months ago
        startDate.setDate(startDate.getDate() - 6);
        break;

      case 'last_24_months':
        startDate = new Date(today);
        startDate.setFullYear(today.getFullYear() - 2); // Start from 24 months ago
        startDate.setDate(startDate.getDate() - 6);
        break;

      case 'all_time': {
        const creationEpoch = listingDetailsData?.originalCreationEpoch;
        if (creationEpoch) {
          startDate = new Date(creationEpoch * 1000); // Convert seconds to milliseconds
        }
        break;
      }
      default:
        return range; // Return the original value if not found
    }
    const formattedStart = startDate.toLocaleDateString('en-US', dateOptions);
    const formattedEnd = endDate.toLocaleDateString('en-US', dateOptions);
    return `${formattedStart} - ${formattedEnd}`;
  };
  const datePickerRef = useRef(null);

  const [selectedDateRange, setSelectedDateRange] = useState(
    getDateRange(
      DateRanges.find((range) => range.slug === time_range) || {
        label: 'Last month',
        slug: 'last_1_month',
      },
    ),
  );
  const [anchorEl, setAnchorEl] = useState(null);
  const isDatePickerOpen = Boolean(anchorEl);
  const [hoveredLockIcon, setHoveredLockIcon] = useState(null);

  const handleDatePickerClick = () => {
    setAnchorEl(datePickerRef.current);
    const eventDataClick = getEventData({
      UrlLink,
      datePickerExplicitWidth,
      listingName: listingDetailsData?.title,
      extraProps: {},
    });
    amplitude.track('Date_Range_Click', eventDataClick);
  };

  const handleDateClick = (date) => {
    if(isContentLocked(userData.current_plan, date.slug, 'listing')) {
      dispatch(toggleRightPane(false));
      if(isSidebarTrendsModal) {
        dispatch(toggleSidebarTrendsModal(false));
      }
      setTimeout(() => {
        dispatch(changeIframeUrl('pricing'));
      }, 200);
      return;
    }
    setSelectedDateRange(date);
    const eventData = getEventData({
      UrlLink,
      datePickerExplicitWidth,
      listingName: listingDetailsData?.title,
      extraProps: { selection_type: date?.slug },
    });
    amplitude.track('Date_Range_Selection', eventData);
    setAnchorEl(null);
  };

  useEffect(() => {
    dispatch(
      updatePASingleListingTimeRange(selectedDateRange.slug || 'last_30_days'),
    );
  }, [selectedDateRange]);

  useEffect(() => {
    const selectedRange = DateRanges.find((range) => range.slug === time_range);
    if (selectedRange) {
      setSelectedDateRange(selectedRange);
    }
  }, [time_range]); // Depend on Redux state

  return (
    <>
      <StyledWrapper
        onClick={handleDatePickerClick}
        ref={datePickerRef}
        $isDatePickerOpen={isDatePickerOpen}
        $datePickerExplicitWidth={datePickerExplicitWidth}
      >
        <div className="date_picker_wrapper">
          <div className="date_picker_left">
            <img src={calendarIcon} alt="calendar icon" height={20} />
            {selectedDateRange.label}
          </div>
          <img src={downIcon} alt="down_icon" />
        </div>
      </StyledWrapper>
      <Popover
        sx={{ marginTop: '0.3rem', zIndex: '999999' }}
        open={isDatePickerOpen}
        anchorEl={anchorEl}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'left',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'left',
        }}
        onClose={() => setAnchorEl(null)}
      >
        <StyledDatePicker>
          <div className="dates_list">
            {DateRanges.map((range) => {
              // <div
              //   key={range.slug}
              //   className={`date_item ${
              //     selectedDateRange.slug === range.slug ? 'active_range' : ''
              //   }`}
              //   onClick={() => handleDateClick(range)}
              //   style={{
              //     pointerEvents:
              //       listingDetailsData?.listingAge < range.minAge
              //         ? 'none'
              //         : 'auto',
              //     opacity:
              //       listingDetailsData?.listingAge < range.minAge ? 0.5 : 1,
              //   }}
              // >
              //   <span className="date_string">{range.label}</span>
              //   {isContentLocked(userData.current_plan, range.slug) && <LockIconDark />}
              // </div>

              const isLocked = isContentLocked(userData.current_plan, range.slug, 'listing');
              const isHoveringDateArea = hoveredLockIcon === 'date_area_' + range.slug;
              const dateItem = (
                <div
                  key={range.slug}
                  className={`date_item ${
                    selectedDateRange.slug === range.slug ? 'active_range' : ''
                  }`}
                  onClick={() => handleDateClick(range)}
                  style={{
                    pointerEvents:
                      isLocked ? 'auto' :
                      listingDetailsData?.listingAge < range.minAge
                        ? 'none'
                        : 'auto',
                    opacity: isLocked ? 1 :
                      listingDetailsData?.listingAge < range.minAge ? 0.5 : 1,
                  }}
                >
                  <div
                    style={{
                      width: isLocked ? '90%' : '100%',
                      display: 'flex',
                      alignItems: 'center',
                    }}
                    onMouseEnter={() => {
                      setHoveredLockIcon('date_area_' + range.slug);
                    }}
                    onMouseLeave={() => {
                      setHoveredLockIcon(null);
                    }}
                    
                  >
                    <span className="date_string">{range.label}</span>
                  </div>
                  {isLocked && (
                    <div 
                      style={{ width: '10%', display: 'flex', justifyContent: 'flex-end' }} 
                      onMouseEnter={(e) => {
                        e.stopPropagation();
                        setHoveredLockIcon(range.slug);
                      }}
                      onMouseLeave={(e) => {
                        e.stopPropagation();
                        setHoveredLockIcon(null);
                      }}
                    >

                      <LockIconDark placement="left" />

                    </div>
                  )}
                </div>
              );

              if (isLocked && isHoveringDateArea) {
                return (
                  <LockIconTooltip
                    key={range.slug}
                    PopperProps={{
                      style: {
                        zIndex: 9999999,
                      },
                      modifiers: [
                        {
                          name: 'offset',
                          options: {
                            offset: [0, -18], // [horizontal, vertical] - negative moves up
                          },
                        },
                      ],
                    }}
                    title={
                      <span
                        style={{
                          fontSize: '10px',
                          color: 'inherit',
                          cursor: 'pointer',
                        }}
                        // onClick={handleLockIconClick}
                      >
                        <em>Click to upgrade</em>
                      </span>
                    }
                    placement="bottom"
                    arrow
                    disableHoverListener={hoveredLockIcon === range.slug}
                    disableInteractive={true} // Prevent interaction with tooltip content
                    leaveDelay={0}
                  >
                    {dateItem}
                  </LockIconTooltip>
                );
              }

              return dateItem;
          })}
          </div>
          <Divider flexItem />
          {/* <div className="custom_date_access">
            <img src={calendarIcon} alt="calendar icon" height={20} />
            <span>Custom date - Aug 11 - Aug 26, 2024</span>
          </div> */}
        </StyledDatePicker>
      </Popover>
    </>
  );
};

export default DateRangePicker;
