/*global chrome*/
import axios from 'axios';

const handleRequest = async (config) => {
  // Create a promise to handle the async nature of chrome.storage.local.get
  const tokenPromise = new Promise((resolve, reject) => {
    chrome.storage.local.get(
      `${process.env.REACT_APP_AUTH_COOKIE_NAME}`,
      (result) => {
        if (result[process.env.REACT_APP_AUTH_COOKIE_NAME]) {
          config.headers['X-Access-Token'] = `${
            result[process.env.REACT_APP_AUTH_COOKIE_NAME]
          }`;
          resolve(config); // Resolve the promise with the modified config
        } else {
          resolve(config); // Reject the promise if no token is found
        }
      },
    );
  });

  // Await the promise to ensure the token is retrieved before returning the config
  return tokenPromise;
};

axios.defaults.headers = {
  Accept: 'application/json',
  'Content-Type': 'application/json',
};

export const registerRequestIntercept = () => {
  // axios.interceptors.request.use(handleRequest);
  axios.interceptors.request.use(handleRequest, (error) =>
    Promise.reject(error),
  );
};
