import React, { useEffect, useState, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import StyledWrapper from './StyledWrapper';
import MainExtScreen from '../../components/MainExtScreen';
import {
  getSalesChannels,
  getUserData,
  updateUserData,
} from '../../store/slices/userSlice';
import {
  changeActiveSubMenu,
  changeIframeUrl,
} from '../../store/slices/sidebarSlice';
import { SUB_MENU_LIST } from '../../constants/menuList';
import { compareArray } from '../../helper/compareArray';

const IFrameFeaturePage = ({
  keyword,
  handleStoreSelectLoading,
  setIsMainLoader,
}) => {
  const iframeRef = useRef(null);
  const [iFrameLoaded, setIFrameLoaded] = useState(false);
  const previousListingIds = useRef([]);
  const { listingIdsForPA } = useSelector((state) => state.utilities);
  const iframeUrl = useSelector((state) => state.sidebar.iframeUrl);
  const sso_auth_token = useSelector(
    (state) => state.user.userData.new_sso_auth_token,
  );
  const { userData } = useSelector((state) => state.user);

  // Lock the iframe URL to the FIRST token seen this session. The `src` must not
  // be re-bound to `new_sso_auth_token`: the SSO backend rotates that token when
  // the user row changes (e.g. a new user's first purchase bumps token_version),
  // and re-binding `src` forces a full iframe reload -> white/blank screen
  // mid-flow. Later rotations are delivered to the iframe via the userData
  // postMessage below, letting the frontend swap its token live without reload.
  const [iframeToken, setIframeToken] = useState(sso_auth_token);
  useEffect(() => {
    if (!iframeToken && sso_auth_token) {
      setIframeToken(sso_auth_token);
    }
  }, [sso_auth_token, iframeToken]);

  const queryString = window.location.search;
  const params = new URLSearchParams(queryString);
  let searchTerm = params.get('q');
  const dispatch = useDispatch();
  useEffect(() => {
    // Add a message event listener to receive messages from the iframe
    window.addEventListener('message', handleIframeMessage);
    return () => {
      // Remove the event listener when the component unmounts
      window.removeEventListener('message', handleIframeMessage);
    };
  }, []);

  const handleIframeMessage = (event) => {
    if (event.origin === `${process.env.REACT_APP_FRONTEND_URL}`) {
      const {
        reload,
        reloadUserData,
        redirectUrl,
        newIframeUrl,
        updateOnboarding,
        updateSidebar,
      } = event.data;
      if (reload) {
        window.location.reload();
      }
      if (reloadUserData) {
        setIsMainLoader(true);
        setTimeout(() => {
          dispatch(getSalesChannels(handleStoreSelectLoading));
          dispatch(getUserData());
          setIsMainLoader(false);
        }, 2000);
      }
      if (redirectUrl) {
        window.open(redirectUrl, '_blank');
      }
      if (newIframeUrl) {
        dispatch(changeIframeUrl(newIframeUrl));
        dispatch(
          changeActiveSubMenu({
            value: SUB_MENU_LIST.RESEARCH_TOOLS[1].slug,
            subMenuIndex: 1,
          }),
        );
      }
      if (updateOnboarding) {
        dispatch(updateUserData({ ...userData, onboarding_flow: true }));
      }
      if (updateSidebar) {
        dispatch(getUserData());
      }
    }
  };

  useEffect(() => {
    if (
      iFrameLoaded &&
      listingIdsForPA &&
      iframeUrl.includes('/ext/product-analytics')
    ) {
      setTimeout(() => {
        let iframe = iframeRef.current;
        if (
          iframe &&
          iframe.contentWindow &&
          !compareArray(previousListingIds.current, listingIdsForPA)
        ) {
          iframe.contentWindow.postMessage(
            { listingIds: listingIdsForPA, searchTerm: searchTerm },
            '*',
          );
          if (listingIdsForPA?.length > 0) {
            previousListingIds.current = listingIdsForPA;
          }
        }
      }, [1000]);
    }
  }, [iFrameLoaded, listingIdsForPA, iframeUrl]);

  useEffect(() => {
    if (iframeUrl === '/ext') {
      document.body.style.overflowY = 'scroll';
    } else {
      document.body.style.overflowY = 'hidden';
    }
    let iframe = iframeRef.current;
    if (iframe && iframe.contentWindow && !queryString?.includes('keyword')) {
      iframe.contentWindow.postMessage({ iframeurl: iframeUrl }, '*');
    }
    if (iframe && iframe.contentWindow && queryString?.includes('keyword')) {
      const updatedKeyword = keyword?.replace(/_/g, ' ');
      const updatedIframeUrl =
        iframeUrl + `?keyword=${updatedKeyword}&order_by=new_volume`;
      iframe.contentWindow.postMessage({ iframeurl: updatedIframeUrl }, '*');
    }
  }, [iframeUrl, iFrameLoaded]);

  useEffect(() => {
    let iframe = iframeRef.current;
    if (iframe && iframe.contentWindow && userData)
      iframe.contentWindow.postMessage({ userData: userData }, '*');
  }, [userData]);

  return (
    <MainExtScreen>
      <StyledWrapper>
        <iframe
          ref={iframeRef}
          onLoad={() => {
            setIFrameLoaded(true);
          }}
          // allow-popups-to-escape-sandbox is required, not cosmetic: without it
          // every `target="_blank"` the frontend renders opens a tab that
          // INHERITS this sandbox (opaque origin, sandboxed document), and any
          // destination that ships X-Frame-Options / COEP — claude.ai, for one —
          // is then rejected with ERR_BLOCKED_BY_RESPONSE. The same links work in
          // everbee-frontend because there they open from an unsandboxed page.
          sandbox="allow-top-navigation allow-same-origin allow-scripts allow-popups allow-popups-to-escape-sandbox allow-forms"
          src={`${process.env.REACT_APP_FRONTEND_URL}/ext?token=${iframeToken}`}
          width="100%"
          height="100%"
          allow="clipboard-read; clipboard-write"
          style={{
            backgroundColor: '#ffffff',
            border: 'none',
          }}
        ></iframe>
      </StyledWrapper>
    </MainExtScreen>
  );
};

export default IFrameFeaturePage;
