export function seperatedCamelCase(str) {
    const words = str.split("-");
    let result = "";
    if (words.length === 1) {
        // If there's only one word, capitalize the first letter only
        return result = words[0].charAt(0).toUpperCase() + words[0].slice(1);
    } else {
        // If there are multiple words, capitalize the first letter of each word
        const capitalizedWords = words.map(word => word.charAt(0).toUpperCase() + word.slice(1));
        return result = capitalizedWords.join(" ");
    }
}