import { KEYWORD_LIMITS, SHOP_LIMITS } from '../constants/favoriteLimits';
import { PLANS } from '../constants/pricingPage';
import favKeywordPopup from '../components/FavUpdateToast/Keywords/FavKeywordPopup';

const extractFavoriteErrorBody = (action) => {
  const payload = action?.payload;
  if (!payload) return null;
  if (payload.success === false) return payload;
  if (payload?.data?.success === false) return payload.data;
  return null;
};

/**
 * Extract first BE error message from a manageFavItemsInFolders thunk action.
 * Handles both fulfilled-with-success:false and rejected payload shapes.
 * @param {Object} action - Result of `await dispatch(manageFavItemsInFolders(...))`
 * @returns {string|null}
 */
export const getFavoriteLimitErrorMessage = (action) => {
  const body = extractFavoriteErrorBody(action);
  if (!body) return null;
  const errors = Array.isArray(body.errors) ? body.errors : [];
  return (
    errors.find((e) => e && typeof e === 'object' && e.message)?.message || null
  );
};

/**
 * If the thunk action contains a BE favorite-limit error, show a sonner toast
 * using the FavKeywordUpdateToast error variant.
 * @param {Object} action - Result of `await dispatch(manageFavItemsInFolders(...))`
 * @returns {boolean} - True if an error toast was shown
 */
export const showFavoriteLimitErrorToast = (action) => {
  const message = getFavoriteLimitErrorMessage(action);
  if (!message) return false;
  favKeywordPopup(null, [], null, message);
  return true;
};

/**
 * Check if keyword favorite limit is reached based on user's plan
 * @param {Object} userData - User data containing current_plan
 * @param {Object} favoriteLimits - Object containing keywordCount
 * @returns {boolean} - True if limit is reached, false otherwise
 */
export const shouldShowKeywordLimitTooltip = (userData, favoriteLimits) => {
  if (!userData || !favoriteLimits) return false;

  const isHobbyPlan = userData?.current_plan === PLANS.HOBBY;
  const isGrowthPlan =
    userData?.current_plan === PLANS.GROWTH_MONTHLY ||
    userData?.current_plan === PLANS.GROWTH_ANUALLY;

  const keywordCount = favoriteLimits?.keywordCount || 0;

  if (isHobbyPlan && keywordCount >= KEYWORD_LIMITS.HOBBY.favoriteCount) {
    return true;
  }

  if (isGrowthPlan && keywordCount >= KEYWORD_LIMITS.GROWTH.favoriteCount) {
    return true;
  }

  return false;
};

/**
 * Check if shop favorite limit is reached based on user's plan
 * @param {Object} userData - User data containing current_plan
 * @param {Object} favoriteLimits - Object containing shopCount
 * @returns {boolean} - True if limit is reached, false otherwise
 */
export const shouldShowShopLimitTooltip = (userData, favoriteLimits) => {
  if (!userData || !favoriteLimits) return false;

  const isHobbyPlan = userData?.current_plan === PLANS.HOBBY;
  const isGrowthPlan =
    userData?.current_plan === PLANS.GROWTH_MONTHLY ||
    userData?.current_plan === PLANS.GROWTH_ANUALLY;

  const shopCount = favoriteLimits?.shopCount || 0;

  if (isHobbyPlan && shopCount >= SHOP_LIMITS.HOBBY.favoriteCount) {
    return true;
  }

  if (isGrowthPlan && shopCount >= SHOP_LIMITS.GROWTH.favoriteCount) {
    return true;
  }

  return false;
};
