export const mapshopDetails = (item) => {
  return {
    id: item?.id,
    shopId: item?.shop_id,
    name: item?.shop_name,
    title: item?.title,
    isFav: item?.is_fav,
    totalReviews: item?.review_count,
    reviews: item?.review_average,
    shopAge: item?.shop_age_month,
    location: item?.shop_location_country_iso,
    url: `https://www.etsy.com/shop/${item?.shop_name}`,
    // GET /listing/:id?listingShop=true returns the shop icon as
    // icon_url_fullxfull and leaves shop_logo null — that endpoint builds its
    // Shop hash straight from ES and never runs the backend's
    // `shop_logo ||= icon_url_fullxfull` normalization. shop_logo stays first so
    // the endpoints that DO populate it are unaffected; without the fallback the
    // carousel drops to its bundled test-avatar.jpg placeholder.
    image: item?.shop_logo || item?.icon_url_fullxfull,
    totalListings: item?.listing_active_count,
    totalSales: item?.transaction_sold_count,
  };
};

