/*global chrome*/

import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { ResearchSidebar } from 'everbee-research-sidebar';
import * as amplitude from '@amplitude/analytics-browser';
import {
  AppWindow,
  BookOpen,
  Calculator,
  CircleHelp,
  Code,
  Gift,
  GraduationCap,
  Layers,
  Lightbulb,
  Megaphone,
  MessageCircle,
  PackageSearch,
  ScanSearch,
  Search,
  Sparkles,
  Star,
  Store,
  UserRound,
  Users,
  Youtube,
} from 'lucide-react';
import {
  changeFeaturePage,
  changeIframeUrl,
  removeFeaturePage,
  toggleRightPane,
} from '../../store/slices/sidebarSlice';
import {
  sidebarOnboardingShown,
  updateHideDetails,
  updateSubscriptionsData,
  updateUserData,
} from '../../store/slices/userSlice';
import { MAIN_MENU } from '../../constants/menuList';
import {
  getSingleListingDetails,
  setLearnModuleActive,
} from '../../store/slices/utilitySlice';
import {
  addToStoreWaitlist,
  updateDefaultSalesChannelAPI,
} from '../../services/account';
import { getEmailAppActivatedAPI } from '../../services/email';
import ConnectShopModal from '../ConnectShopModal/ConnectShopModal';
import axios from 'axios';
import {
  buildOposhopRedirectUrl,
  getAuthTokenFromChromeStorage,
  getOposhopAppUrl,
} from '../../utils/oposhopRedirect';
import lightTheme from '../../themes/light';
import { resolvePlan } from './resolvePlan';

// Same assets the old sidebar's productSwitcher pointed at.
const BEE_LOGO = 'https://db2l6eppot2a3.cloudfront.net/bee-logo.png';
const RESEARCH_WORDMARK =
  'https://db2l6eppot2a3.cloudfront.net/research-logo.svg';

// The account menu's outbound links, all taking the web app's destinations so
// the same row goes to the same place in both hosts. The extension used to
// carry its own set here — an older Facebook group and YouTube channel, and a
// Support entry pointing at the help centre, which put it on the same page as
// Help Center directly above it.
const HELP_CENTER_URL = 'https://help.everbee.io/en/';
const SUPPORT_URL = 'https://www.everbee.io/contact';
const FEATURE_REQUEST_URL = 'https://everbee.canny.io/feature-requests';
const AFFILIATES_URL = 'https://www.everbee.io/affiliates';
const YOUTUBE_URL = 'https://www.youtube.com/@helloeverbee';
const COMMUNITY_URL = 'https://www.facebook.com/groups/everbeemembers';
const RELEASE_NOTES_URL = 'https://www.everbee.io/changelog';
const API_DOCS_URL =
  process.env.REACT_APP_DEV_PORTAL_FRONTEND_APP || 'https://dev.everbee.io';
const OPOSHOP_LOGO =
  'https://db2l6eppot2a3.cloudfront.net/research-assets/icons/Light+Theme+Gradient+Logo+-+Symbol+Only.png';
const OHONEY_LOGO =
  'https://d3rjz9fmsdcq0v.cloudfront.net/logos/63035738-3835-4535-a644-71bde5ff9934.png';

const SidebarN = ({ isStoreSelectLoading, isAuth, authChecked }) => {
  const dispatch = useDispatch();
  var manifestData = chrome.runtime.getManifest();

  const [storeList, setStoreList] = useState([]);
  const [isConnectShopModal, setIsConnectShopModal] = useState(false);
  const [showSidebarOnboarding, setShowSidebarOnboarding] = useState(false);
  const [isStoreLabelShown, setStoreLabelShown] = useState(false);
  const [oposhopUrl, setOposhopUrl] = useState(
    `${getOposhopAppUrl()}?from_research=true`,
  );
  const [ohoneyUrl, setOhoneyUrl] = useState('');
  const [isEmailAppActivated, setIsEmailAppActivated] = useState(false);

  const { userData, salesChannels } = useSelector((state) => state.user);
  const { shopNameInPage, listingDetailsData } = useSelector(
    (state) => state.utilities,
  );
  const { isExpanded, iframeUrl, featurePage } = useSelector(
    (state) => state.sidebar,
  );
  const default_sales_channel_ids = useSelector(
    (state) =>
      state.user.userData && state.user.userData.default_sales_channel_ids,
  );

  const handleLogout = () => {
    dispatch(toggleRightPane(false));
    //Need to remove in 9.0.5
    localStorage.removeItem('everbeeAuthToken');
    localStorage.removeItem('everbeeEmail');
    localStorage.removeItem('everbeeUserId');
    //
    dispatch(updateUserData([]));
    dispatch(updateSubscriptionsData({}));
    window.location.href = `${process.env.REACT_APP_AUTH_FRONTEND_APP}/logout?redirect_to=https://etsy.com`;
    //TODO: Logout of webapp as well
  };

  const handleProfileClick = () => {
    dispatch(changeIframeUrl('account?tab_name=profile'));
    // handleClickAway();
  };

  // Verbatim from the old rail's `footer.handleLoginClick`. /logout, not
  // /login: it clears any stale session on the way out before bouncing the
  // user back to Etsy.
  const handleLoginClick = () => {
    window.open(
      `${process.env.REACT_APP_AUTH_FRONTEND_APP}/logout?redirect_to=https://etsy.com`,
    );
  };

  const handleWebappClick = () => {
    isAuth
      ? window.open(`${process.env.REACT_APP_FRONTEND_URL}`)
      : window.open(
          `${process.env.REACT_APP_AUTH_FRONTEND_APP}/login?redirect_to=https://etsy.com`,
        );
  };

  const handleHelpClick = () => {
    window.open(HELP_CENTER_URL, '_blank');
  };

  const checkAuthenticated = () => {
    if (isAuth) {
      return true;
    } else {
      window.location.href = `${process.env.REACT_APP_AUTH_FRONTEND_APP}/login?redirect_to=https://etsy.com`;
      return false;
    }
  };

  const handleChangeMenu = (featurePage, iframeUrl) => {
    if (checkAuthenticated()) {
      dispatch(changeFeaturePage(featurePage));
      dispatch(changeIframeUrl(iframeUrl));
    }
  };

  const handleClose = () => {
    setIsConnectShopModal(false);
    dispatch(removeFeaturePage('connectShop'));
  };

  const getCleanData = () => {
    const result =
      salesChannels &&
      salesChannels.map((item) => {
        return {
          id: item.sales_channel_id,
          name: item?.sales_channel_shop_name
            ? item?.sales_channel_shop_name
            : item?.sales_channel_owner_name,
          isChecked:
            default_sales_channel_ids &&
            default_sales_channel_ids.includes(item?.sales_channel_id)
              ? true
              : false,
          salesCount: item.sales_channel_shop_sales,
          salesChannelLogo: item.sales_channel_shop_image_url || undefined,
        };
      });
    return result.filter((value) => {
      return value !== undefined;
    });
  };

  const updateDefaultSalesChannel = async (salesChannelId) => {
    const updatedUserData = {
      ...userData,
      default_sales_channel_ids: [salesChannelId],
    };
    if (
      default_sales_channel_ids &&
      !default_sales_channel_ids.includes(salesChannelId)
    ) {
      await updateDefaultSalesChannelAPI(salesChannelId)
        .then(dispatch(updateUserData(updatedUserData)))
        .catch(() => {});
    }
  };

  const handleStoreClicked = async (child) => {
    storeList.map((storeChild) => {
      if (storeChild.name === child.name) {
        //update in store
        storeChild.isChecked = true;
      } else {
        storeChild.isChecked = false;
      }
    });
    await updateDefaultSalesChannel(child.id);
    window.location.reload();
  };

  // Built with the URL API so a missing REACT_APP_OHONEY_FRONTEND_APP can't
  // produce a relative link that leaks the auth token to the current origin.
  const buildOhoneyRedirectUrl = async () => {
    const appUrl = process.env.REACT_APP_OHONEY_FRONTEND_APP;
    if (!appUrl) return '';

    const url = new URL(appUrl);
    url.searchParams.set('from_research', 'true');

    const token = await getAuthTokenFromChromeStorage();
    if (token) url.searchParams.set('token', token);

    return url.toString();
  };

  const handleAddToStoreWaitlist = async () => {
    const result = await chrome.storage.local.get(
      process.env.REACT_APP_AUTH_COOKIE_NAME,
    );

    const token = result[process.env.REACT_APP_AUTH_COOKIE_NAME];
    const headers = {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    };

    return axios
      .post(
        `${process.env.REACT_APP_SSO_BACKEND_APP}/add_to_store_waitlist`,
        {},
        { headers },
      )
      .then(() => {
        setStoreLabelShown(true);
        setTimeout(() => {
          setStoreLabelShown(false);
        }, 3000);
      })
      .catch((err) => {
        console.log('Error - ', err);
      });
  };

  useEffect(() => {
    const cleanData = getCleanData();
    //set the store
    setStoreList(cleanData);
    if (cleanData?.length === 1 && default_sales_channel_ids?.length === 0) {
      updateDefaultSalesChannel(cleanData[0].id);
    }
  }, [default_sales_channel_ids, salesChannels]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const url = await buildOposhopRedirectUrl();
      if (!cancelled) setOposhopUrl(url);
    })();
    return () => {
      cancelled = true;
    };
  }, [userData?.id]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const url = await buildOhoneyRedirectUrl();
      if (!cancelled) setOhoneyUrl(url);
    })();
    return () => {
      cancelled = true;
    };
  }, [userData?.id]);

  // EverBee Email only belongs in the product switcher for users the email app
  // has actually been activated for. Anything other than an explicit `true`
  // (error, no access, missing token) keeps the entry hidden.
  useEffect(() => {
    if (!userData?.id) return;

    let isCurrent = true;

    getEmailAppActivatedAPI()
      .then(({ data }) => {
        const activated = typeof data === 'boolean' ? data : data?.activated;
        if (isCurrent) setIsEmailAppActivated(activated === true);
      })
      .catch(() => {
        if (isCurrent) setIsEmailAppActivated(false);
      });

    return () => {
      isCurrent = false;
    };
  }, [userData?.id]);

  useEffect(() => {
    if (userData?.id) {
      if (!userData?.onboarding_flow) setShowSidebarOnboarding(false);
      else {
        if (!userData?.sidebar_onboarding_shown) setShowSidebarOnboarding(true);
        else setShowSidebarOnboarding(false);
      }
    }
  }, [userData.onboarding_flow, userData.sidebar_onboarding_shown, isExpanded]);

  // One handler per nav id. These bodies are unchanged from the old sidebar's
  // per-item `handleMenuClick` callbacks — the new API routes every click
  // through a single onNavigate, so they are keyed by id rather than inlined
  // on each item. Product Analytics in particular stays page-dependent.
  const navHandlers = {
    'my-shop': () => {
      handleChangeMenu(MAIN_MENU.DASHBOARD, 'my-shop');

      // For closing Right Side pane
      dispatch(toggleRightPane(false));
      dispatch(setLearnModuleActive(false));
    },
    'product-analytics': () => {
      if (window.location.href.includes('/listing')) {
        const parts = window.location.href.split('/');
        const listingIndex = parts.indexOf('listing');
        // Extract the listing ID which is next to 'listing' in the parts array
        const listingId = parts[listingIndex + 1];
        dispatch(toggleRightPane(true));
        dispatch(
          getSingleListingDetails({
            listingId: listingId,
            listingDetails: true,
            listingAnalytics: true,
            listingTagAnalytics: true,
            listingShop: true,
          }),
        );

        amplitude.track('Listing_Details_View', {
          product_type: 'extension',
          feature_type: 'etsy',
          etsy_type: 'listing_page',
          // listing_id: listingId,
          listing_name: listingDetailsData?.title,
          source_type: 'sidebar',
          listing_details_tab_type: 'listing_details_tab',
        });
      } else if (window.location.href.includes('/shop/')) {
        amplitude.track('Analyze_Shop_Click', {
          product_type: 'extension',
          feature_type: 'etsy',
          etsy_type: 'shop_page',
          shop_name: shopNameInPage,
          source_type: 'sidebar',
        });
        dispatch(
          changeIframeUrl(`shop-analyzer/${shopNameInPage}?tabName=listings`),
        );

        // For closing Right Side pane
        dispatch(toggleRightPane(false));
        dispatch(setLearnModuleActive(false));
      } else {
        handleChangeMenu(
          MAIN_MENU.PRODUCT_ANALYTICS,
          MAIN_MENU.PRODUCT_ANALYTICS,
        );

        // For closing Right Side pane
        dispatch(toggleRightPane(false));
        dispatch(setLearnModuleActive(false));
      }
    },
    'shop-analyzer': () => {
      handleChangeMenu(MAIN_MENU.SHOP_ANALYZER, MAIN_MENU.SHOP_ANALYZER);

      // For closing Right Side pane
      dispatch(toggleRightPane(false));
      dispatch(setLearnModuleActive(false));
    },
    'keyword-research': () => {
      handleChangeMenu(MAIN_MENU.KEYWORD_RESEARCH, MAIN_MENU.KEYWORD_RESEARCH);

      // For closing Right Side pane
      dispatch(toggleRightPane(false));
      dispatch(setLearnModuleActive(false));
    },
    'profit-calculator': () => {
      dispatch(changeFeaturePage(MAIN_MENU.ETSY_CALCULATOR));

      amplitude.track('Calculator_View', {
        product_type: 'extension',
        feature_type: 'etsy',
        etsy_type:
          window.location.pathname === '/'
            ? 'home_page'
            : window.location.href.includes('/shop/')
              ? 'shop_page'
              : window.location.href.includes('/listing/')
                ? 'listing_page'
                : window.location.href.includes('/search?q=')
                  ? 'search_results'
                  : 'other_page',
        source_type: 'sidebar',
      });

      // For closing Right Side pane
      dispatch(toggleRightPane(false));
      dispatch(setLearnModuleActive(false));
    },
    favorites: () => {
      handleChangeMenu(MAIN_MENU.FAVORITES, MAIN_MENU.FAVORITES);

      // For closing Right Side pane
      dispatch(toggleRightPane(false));
      dispatch(setLearnModuleActive(false));
    },
  };

  // The same lucide icons the web app's rail uses, rather than the bundled
  // svg/ assets the old extension sidebar pointed at, so the two match.
  const navItems = [
    { id: 'my-shop', label: 'My Shop', icon: Store },
    {
      id: 'product-analytics',
      label: 'Product Analytics',
      icon: PackageSearch,
    },
    {
      id: 'shop-analyzer',
      label: 'Shop Analyzer',
      icon: ScanSearch,
    },
    {
      id: 'keyword-research',
      label: 'Keyword Research',
      icon: Search,
    },
    {
      id: 'profit-calculator',
      label: 'Profit Calculator',
      icon: Calculator,
    },
    {
      id: 'favorites',
      label: 'Favorites',
      icon: Star,
      // badge: 'new',
    },
  ];

  // The same conditions the old sidebar evaluated as each item's `isActive`.
  // Profit Calculator and Learn were hardcoded false there, so neither can
  // become the active id here.
  const activeId =
    iframeUrl === '/ext/my-shop'
      ? 'my-shop'
      : iframeUrl === `/ext/${MAIN_MENU.PRODUCT_ANALYTICS}`
        ? 'product-analytics'
        : iframeUrl === `/ext/${MAIN_MENU.SHOP_ANALYZER}`
          ? 'shop-analyzer'
          : iframeUrl === `/ext/${MAIN_MENU.KEYWORD_RESEARCH}`
            ? 'keyword-research'
            : iframeUrl === `/ext/${MAIN_MENU.FAVORITES}`
              ? 'favorites'
              : null;

  const apps = [
    {
      id: 'research',
      name: 'EverBee Research',
      description: 'Find the best products to sell',
      url: process.env.REACT_APP_EVERBEE_FRONTEND_HOST,
      logo: { src: BEE_LOGO },
      color: '#1F76CC',
      current: true,
    },
    ...(isEmailAppActivated
      ? [
          {
            id: 'email',
            name: 'EverBee Email',
            description: 'Get more sales on autopilot',
            url: process.env.REACT_APP_EMAIL_FRONTEND_APP,
            logo: { src: BEE_LOGO },
            color: '#1F76CC',
          },
        ]
      : []),
    ...(userData?.is_print_beta
      ? [
          {
            id: 'print',
            name: 'EverBee Print',
            description: 'Sell print-on-demand products on your shop',
            url: process.env.REACT_APP_PRINT_FRONTEND_APP,
            logo: { src: BEE_LOGO },
            color: '#1F76CC',
            beta: true,
          },
        ]
      : []),
    {
      id: 'oposhop',
      name: 'OpoShop',
      description: 'Make your own website and sell, sell, sell!',
      url: oposhopUrl,
      logo: { src: OPOSHOP_LOGO },
      color: lightTheme.colors.purple.purple700,
      waitlist: userData.is_store_beta
        ? undefined
        : { joined: isStoreLabelShown, onJoin: handleAddToStoreWaitlist },
    },
    {
      id: 'ohoney',
      name: 'Ohoney',
      description:
        'Create on-brand designs, apply them to mockups, publish to your store',
      url: ohoneyUrl,
      logo: { src: OHONEY_LOGO },
      color: lightTheme.colors.ohoneyLogo,
    },
  ];

  const plan = resolvePlan(userData?.current_plan, {
    onUpgrade: () => {
      dispatch(changeIframeUrl('pricing'));
    },
  });

  const selectedShop = storeList.find((shop) => shop.isChecked);

  // Mirrors the web app's account menu: same entries, order and grouping. Every
  // handler is still the extension's own, kept from the old rail's
  // `optionsMenuItems` / `footer.profileMenuItems` — they drive the iframe and
  // its store rather than routing a Next.js page.
  const profileMenu = [
    {
      kind: 'item',
      id: 'account',
      label: 'Account',
      icon: UserRound,
      onSelect: () => {
        handleChangeMenu(MAIN_MENU.ACCOUNT, 'account?tab_name=profile');

        // For closing Right Side pane
        dispatch(toggleRightPane(false));
        dispatch(setLearnModuleActive(false));
      },
    },
    {
      kind: 'item',
      id: 'plans',
      label: 'Plans',
      icon: Layers,
      onSelect: () => {
        handleChangeMenu(MAIN_MENU.PRICING, 'pricing');

        // For closing Right Side pane
        dispatch(toggleRightPane(false));
        dispatch(setLearnModuleActive(false));
      },
    },
    {
      kind: 'item',
      id: 'mcp',
      label: 'MCP',
      icon: Sparkles,
      onSelect: () => {
        handleChangeMenu(MAIN_MENU.AI_CONNECTORS, MAIN_MENU.AI_CONNECTORS);
        amplitude.track('AI Connectors - click - extension');

        // For closing Right Side pane
        dispatch(toggleRightPane(false));
        dispatch(setLearnModuleActive(false));
      },
    },
    {
      kind: 'submenu',
      id: 'help',
      label: 'Help',
      icon: CircleHelp,
      items: [
        {
          kind: 'item',
          id: 'help-center',
          label: 'Help Center',
          icon: CircleHelp,
          onSelect: () => {
            handleHelpClick();
          },
        },
        {
          kind: 'item',
          id: 'courses',
          label: 'Courses',
          icon: GraduationCap,
          onSelect: () => {
            dispatch(changeIframeUrl('close'));
            dispatch(changeFeaturePage(MAIN_MENU.COURSES));

            // For closing Right Side pane
            dispatch(toggleRightPane(false));
            dispatch(setLearnModuleActive(false));
          },
        },
        {
          kind: 'item',
          id: 'learn',
          label: 'Learn',
          icon: BookOpen,
          onSelect: () => {
            dispatch(toggleRightPane(true));
            dispatch(setLearnModuleActive(true));
            amplitude.track('Learn - click - extension');
          },
        },
        {
          kind: 'item',
          id: 'support',
          label: 'Support',
          icon: MessageCircle,
          onSelect: () => {
            window.open(SUPPORT_URL, '_blank');

            // For closing Right Side pane
            dispatch(toggleRightPane(false));
            dispatch(setLearnModuleActive(false));
          },
        },
        {
          kind: 'item',
          id: 'feature-request',
          label: 'Feature Request',
          icon: Lightbulb,
          onSelect: () => {
            window.open(FEATURE_REQUEST_URL, '_blank');

            // For closing Right Side pane
            dispatch(toggleRightPane(false));
            dispatch(setLearnModuleActive(false));
          },
        },
        {
          kind: 'item',
          id: 'release-notes',
          label: 'Release notes',
          icon: Megaphone,
          href: RELEASE_NOTES_URL,
          external: true,
        },
      ],
    },
    {
      kind: 'submenu',
      id: 'resources',
      label: 'Resources',
      icon: Gift,
      items: [
        {
          kind: 'item',
          id: 'affiliate',
          label: 'Affiliate Program',
          icon: Gift,
          onSelect: () => {
            window.open(AFFILIATES_URL, '_blank');

            // For closing Right Side pane
            dispatch(toggleRightPane(false));
            dispatch(setLearnModuleActive(false));
          },
        },
        {
          kind: 'item',
          id: 'youtube',
          label: 'YouTube',
          icon: Youtube,
          onSelect: () => {
            window.open(YOUTUBE_URL, '_blank');

            // For closing Right Side pane
            dispatch(toggleRightPane(false));
            dispatch(setLearnModuleActive(false));
          },
        },
        {
          kind: 'item',
          id: 'community',
          label: 'Community',
          icon: Users,
          onSelect: () => {
            window.open(COMMUNITY_URL, '_blank');

            // For closing Right Side pane
            dispatch(toggleRightPane(false));
            dispatch(setLearnModuleActive(false));
          },
        },
        {
          kind: 'item',
          id: 'api-docs',
          label: 'API Documentation',
          icon: Code,
          href: API_DOCS_URL,
          external: true,
        },
      ],
    },
    {
      // Extension only, and last: the web app has no counterpart because it is
      // the destination. Sits after Resources the way the old rail had it.
      kind: 'item',
      id: 'visit-webapp',
      label: 'Visit Webapp',
      icon: AppWindow,
      onSelect: () => {
        handleWebappClick();
      },
    },
  ];

  return (
    <div style={{ marginLeft: '-73px' }}>
      <ResearchSidebar
        collapseBehavior="hover"
        // Which rc a tester is on, without opening chrome://extensions.
        // Staging and development only — production ships no marker.
        versionTag={
          process.env.REACT_APP_ENV !== 'production'
            ? manifestData.version_name
            : undefined
        }
        // Normally undefined, so the rail is left to its own hover behaviour.
        // The onboarding tour dispatches toggleSidebar(true) before it starts
        // and false when it ends, which pins the rail open while the tour is
        // pointing at the Product Analytics row — the same thing the old rail
        // did with this flag.
        expanded={isExpanded ? true : undefined}
        header={{
          productName: 'Research',
          logoExpanded: { src: RESEARCH_WORDMARK, alt: 'EverBee Research' },
          logoCollapsed: { src: BEE_LOGO, alt: 'EverBee' },
          onLogoClick: () => {
            window.open(process.env.REACT_APP_EVERBEE_FRONTEND_HOST, '_blank');
          },
        }}
        apps={apps}
        items={navItems}
        activeId={activeId}
        onNavigate={(item) => navHandlers[item.id]?.()}
        shops={{
          shops: storeList.map((shop) => ({
            id: shop.id,
            name: shop.name,
            salesCount: shop.salesCount,
            avatarUrl: shop.salesChannelLogo,
          })),
          selectedId: selectedShop ? selectedShop.id : null,
          isMasked: userData?.hide_details ? userData?.hide_details : false,
          loading: isStoreSelectLoading,
          onSelect: (id) => {
            const shop = storeList.find((item) => item.id === id);
            if (shop) handleStoreClicked(shop);
          },
          onToggleMask: () => {
            dispatch(updateHideDetails({ hide: !userData?.hide_details }));
            dispatch(
              updateUserData({
                ...userData,
                hide_details: !userData?.hide_details,
              }),
            );
          },
          onConnectShop: () => {
            isAuth
              ? setIsConnectShopModal(true)
              : window.open(
                  `${process.env.REACT_APP_AUTH_FRONTEND_APP}/logout?redirect_to=https://etsy.com`,
                );
          },
          onManageShops: () => {
            dispatch(changeIframeUrl('account?tab_name=salesChannels'));
          },
        }}
        plan={plan}
        user={{
          loading: !userData?.name,
          name: userData?.name ? userData?.name : '',
          email: userData?.email,
          avatarUrl: userData?.image || undefined,
        }}
        profileMenu={profileMenu}
        onLogout={() => {
          handleLogout();
        }}
        // Signed out, the footer shows a Log In button in place of the account
        // row, in both the collapsed and expanded rail — the same swap the old
        // common-components sidebar made.
        //
        // Only once the token has actually been read, though. `login` outranks
        // the loading state in the footer, so offering it before then put a Log
        // In button under a user who turns out to be signed in, where the web
        // app shows the account skeleton. Until authChecked lands, this stays
        // null and `user.loading` drives the footer exactly as it does there.
        login={authChecked && !isAuth ? { onLogin: handleLoginClick } : null}
      />
      <ConnectShopModal
        isConnectShopModal={isConnectShopModal}
        handleClose={handleClose}
      />
    </div>
  );
};

export default SidebarN;
