import React, { useState } from 'react';
import { nanoid } from '@reduxjs/toolkit';
import styled, { css } from 'styled-components';
import { Skeleton } from '@mui/material';
import { StyledWrapper } from './StyledWrapper';
import FramerMotion from '../../utils/FramerMotion/FramerMotion';
import * as amplitude from '@amplitude/analytics-browser';

const ImageSpan = styled.span`
  margin-left: 7px;
  transition: 1s ease 0s;
  cursor: pointer;
  ${(props) => {
    if (props.$collapse) {
      return css`
        transform: rotate(180deg);
        transition: transform 1s ease 0s;
      `;
    }
  }}
`;

const MoreDetails = ({ details, loading }) => {
  const ChevronDownSvg = chrome.runtime.getURL('svg/chevron-down.svg');
  const even = [1, 3, 5, 7, 9];
  const [collapse, setCollapse] = useState(true);
  return (
    <StyledWrapper>
      <div className="MoreDetailsHeadingWrapper">
        <h5 className="Heading main-heading">More Details</h5>
        <ImageSpan $collapse={collapse} onClick={() => {
          setCollapse(!collapse);

          amplitude.track('More_Details_Toggle', {
            product_type: 'extension',
            feature_type: 'etsy',
            etsy_type: window.location.pathname === '/' ? 'home_page' : 
                        window.location.href.includes('/shop/') ? 'shop_page' : 
                        window.location.href.includes('/listing/') ? 'listing_page' : 
                        window.location.href.includes('/search?q=') ? 'search_results' : 
                        'other_page',
            toggle_type: collapse ? 'off' : 'on',
          });

          }}
        >
          <img src={ChevronDownSvg} alt="ChevronDownIcon" />
        </ImageSpan>
      </div>

      {collapse && (
        <FramerMotion delay={0.3}>
          {' '}
          {loading ? (
            <>
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  marginTop: '1rem',
                }}
              >
                <Skeleton
                  variant="rectangular"
                  animation="wave"
                  width={90}
                  height={20}
                  sx={{ marginLeft: '2rem' }}
                />
                <Skeleton
                  variant="rectangular"
                  animation="wave"
                  width={50}
                  height={20}
                  sx={{ marginRight: '2rem' }}
                />
              </div>
              <div style={{ paddingBottom: '15rem', margin: '1rem 2rem' }}>
                <div
                  className="MoreDetailsWrapperWithColor"
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    marginLeft: '-0.5rem',
                    marginRight: '-0.5rem',
                    padding: '0.5rem 0.5rem',
                  }}
                >
                  <Skeleton
                    variant="rectangular"
                    animation="wave"
                    width={80}
                    height={20}
                  />
                  <Skeleton
                    variant="rectangular"
                    animation="wave"
                    width={70}
                    height={20}
                  />
                </div>
              </div>
            </>
          ) : (
            details.map((child, index) => (
              <div
                key={nanoid()}
                className={
                  even.includes(index)
                    ? 'MoreDetailsWrapper MoreDetailsWrapperWithColor'
                    : 'MoreDetailsWrapper'
                }
              >
                <p className="Heading MoreDetailsSubHeading">
                  {child.subHeading}
                </p>
                <p className="Heading MoreDetailsSubHeading MoreDetailsSubHeadingValue">
                  {child.value === true
                    ? 'Yes'
                    : child.value === false
                      ? 'No'
                      : child.value?.toLocaleString('en-US')}
                </p>
              </div>
            ))
          )}
        </FramerMotion>
      )}
    </StyledWrapper>
  );
};

export default MoreDetails;
