/*global chrome*/
import { useDispatch } from 'react-redux';
import VideoCard from './VideoCard';
import { setLearnModuleActive } from '../../store/slices/utilitySlice';
import { StyledWrapper } from './StyledWrapper';
import { toggleRightPane } from '../../store/slices/sidebarSlice';
import { LEARN_CONTENT } from '../../constants/learnContent';

const LearnRightSidebar = () => {
  const closeIcon = chrome.runtime.getURL('svg/close-button.svg');
  const dispatch = useDispatch();

  const handleClose = () => {
    dispatch(toggleRightPane(false));
    dispatch(setLearnModuleActive(false));
  };
  return (
    <StyledWrapper>
      <div className="header">
        <div className="header-content">
          <div className="learn">Learn</div>
          <div className="title">
            Unleash your potential by learning with EverBee
          </div>
        </div>
        <img
          className="btn-close"
          src={closeIcon}
          alt="close button"
          onClick={handleClose}
        />
      </div>
      {/* <div className="videos-heading">Videos</div> */}

      {/* Video List */}
      <div className="video-list">
        {LEARN_CONTENT.map(({ heading, subHeading, videoSrc, helpLink }) => (
          <VideoCard
            key={heading}
            heading={heading}
            subHeading={subHeading}
            videoSrc={videoSrc}
            helpLink={helpLink}
          />
        ))}
      </div>
    </StyledWrapper>
  );
};

export default LearnRightSidebar;
