export const getEventData = ({
  UrlLink,
  datePickerExplicitWidth,
  listingName,
  extraProps = {},
}) => {
  const eventData = {
    daily_trends_type: datePickerExplicitWidth ? 'expand' : 'listing_details',
    product_type: 'extension',
    feature_type: 'etsy',
    listing_name: listingName,
    ...extraProps, // Spread any additional properties
  };
  if (UrlLink.includes('/search')) {
    eventData.etsy_type = 'search_results';
  } else if (
    UrlLink.includes('/listing') ||
    UrlLink.includes('/c') ||
    UrlLink.includes('/gift-mode') ||
    UrlLink.includes('/featured')
  ) {
    eventData.etsy_type = 'listing_page';
  } else if (UrlLink.includes('/shop')) {
    eventData.etsy_type = 'shop_page';
  } else if (
    UrlLink === 'https://www.etsy.com/' ||
    UrlLink === 'https://www.etsy.com/in-en/?ref=lgo'
  ) {
    eventData.etsy_type = 'home_page';
  }
  return eventData;
};
