import introJs from 'intro.js';
import * as amplitude from '@amplitude/analytics-browser';

//remove onboarding flow
export const removeOnboarding = async (updateOnboardingFlow) => {
  try {
    updateOnboardingFlow();
  } catch (error) {
    console.log(error);
  }
};

// The rail this points at is the research-sidebar package, whose class names
// are content-hashed per build. `data-ebsb-nav` is the stable hook it exposes
// for exactly this; the old `.menu-container` belonged to the previous
// common-components rail and stopped existing when that was swapped out, which
// left intro.js with an undefined element and the highlight landing on
// whatever the page happened to have.
const PRODUCT_ANALYTICS_ROW = '[data-ebsb-nav="product-analytics"]';

const RAIL_EXPANDED = 'aside[data-expanded="true"]';

/**
 * Runs `cb` once the row has stopped moving.
 *
 * The tour is kicked off right after the rail is told to open, and the rail
 * opens on a spring while the shop section is still swapping its loading state
 * out — so measuring straight away pins the highlight to wherever the row was
 * mid-animation, a little above where it lands. Waits for the rail to report
 * itself expanded and for the row's box to repeat three frames running, with a
 * ceiling so a rail that never settles still gets its tour.
 */
function whenRowSettles(selector, cb) {
  const DEADLINE = 120; // frames (~2s at 60fps)
  let previous = null;
  let steady = 0;
  let frames = 0;

  const tick = () => {
    const row = document.querySelector(selector);
    if (!row) {
      if (frames++ > DEADLINE) return;
      return requestAnimationFrame(tick);
    }

    const { top, left, width, height } = row.getBoundingClientRect();
    const box = [top, left, width, height].map(Math.round).join();
    const expanded = Boolean(document.querySelector(RAIL_EXPANDED));

    steady = box === previous && expanded ? steady + 1 : 0;
    previous = box;

    if (steady >= 3 || frames++ > DEADLINE) cb();
    else requestAnimationFrame(tick);
  };

  requestAnimationFrame(tick);
}

export function threeStepOnboarding(updateOnboardingFlow, callback, onFinish) {
  // Without the row intro.js floats the tooltip against the page instead of the
  // rail, which is worse than not running at all — the tour would point at
  // something arbitrary and still burn the user's one-time onboarding flag.
  if (!document.querySelector(PRODUCT_ANALYTICS_ROW)) {
    if (typeof onFinish === 'function') onFinish();
    return null;
  }

  var options = {
    hidePrev: true,
    showBullets: false,
    showBackButtons: false,
    exitOnEsc: false,
    exitOnOverlayClick: false,
    showStepNumbers: false,
    keyboardNavigation: false,
    // The rail is position:fixed and always on screen. Left on, intro.js
    // scrolls the page to "reveal" it, which moves every page offset out from
    // under the highlight it just measured.
    scrollToElement: false,
    stepNumbersOfLabel: '/',
    steps: [
      {
        title: 'Start here 🚀',
        // The selector, not a captured node: intro.js re-resolves it on every
        // refresh(), so a row React has since re-rendered can't leave the
        // highlight measuring a node that is no longer in the document.
        element: PRODUCT_ANALYTICS_ROW,
        intro: 'Click here to <b>Analyze</b> all the products on the page 👀',
        position: 'right',
        tooltipClass: 'product-analytics-tooltip',
      },
    ],
  };

  var intro = introJs();
  intro.setOptions(options);

  let skipOnboardingRemoval = false;
  let exited = false;

  intro.onexit(function () {
    exited = true;
    if (!skipOnboardingRemoval) {
      removeOnboarding(updateOnboardingFlow);
      amplitude.track('Onboarding Step Closed - Extension', {});
    }
    // Releases the rail that was pinned open for the tour.
    if (typeof onFinish === 'function') onFinish();
  });

  whenRowSettles(PRODUCT_ANALYTICS_ROW, () => {
    intro.start();

    // One more pass after the rail's transition would have ended, in case the
    // row moved between settling and painting.
    setTimeout(() => {
      if (!exited) intro.refresh();
    }, 400);

    // The layer is created by start(), but retry a frame later rather than
    // assume it — losing this listener means the highlight stops being
    // clickable, which is the whole point of the step.
    const attach = (attempt) => {
      const layer = document.querySelector('.introjs-helperLayer');
      if (!layer) {
        if (attempt < 10) requestAnimationFrame(() => attach(attempt + 1));
        return;
      }
      layer.addEventListener('click', function () {
        skipOnboardingRemoval = true;
        callback();
        intro.exit();
      });
    };
    attach(0);
  });

  return intro;
}
