import React from 'react';
import { useSelector } from 'react-redux';
import { Box, Drawer } from '@mui/material';
import styled from 'styled-components';
import RightPane from '../RightPane/RightPane';
import LearnRightSidebar from '../LearnRightSidebar/LearnRightSidebar';

const StyledWrapper = styled.div``;

const ToggleBox = ({ toggleBoxSide, open, closeDrawer, isAuth }) => {
  const { isLearnModuleActive } = useSelector((state) => state.utilities);
  const { isRightPaneOpen } = useSelector((state) => state.sidebar);

  return (
    <StyledWrapper>
      <Drawer
        anchor={toggleBoxSide}
        open={open}
        onClose={closeDrawer}
        sx={{ position: 'fixed', zIndex: '2100' }}
      >
        <Box
          sx={{ width: 615, height: 150, overflowX: 'clip' }}
          role="presentation"
        >
          {/* Enter the rest of components */}
          {isLearnModuleActive && isRightPaneOpen && <LearnRightSidebar />}
          {!isLearnModuleActive && isRightPaneOpen && (
            <RightPane closeDrawer={closeDrawer} isAuth={isAuth} />
          )}
        </Box>
      </Drawer>
    </StyledWrapper>
  );
};

export default ToggleBox;
