import { isDataString } from './columns/columnNamesMap';

export const clientSideSort = (data, fieldName, sortOrder) => {
  const sortedData = [...data];

  const checkFieldName = (name) => {
    if (name === 'product') {
      return 'productName';
    }
    return name;
  };

  const customSort = (a, b) => {
    const fieldA = a[checkFieldName(fieldName)];
    const fieldB = b[checkFieldName(fieldName)];

    const parseWhenMade = (value) => {
      if (value === 'made_to_order') return Number.MAX_SAFE_INTEGER;
      const [start, end] = value.split('_').map(Number);
      return (start + end) / 2;
    };

    const parseFieldValue = (value) => {
      if (value === null || value === undefined) return '';
      return value;
    };

    const valueA =
      fieldName === 'whenMade'
        ? parseWhenMade(fieldA)
        : isDataString(fieldName)
          ? parseFieldValue(a[checkFieldName(fieldName)])
              .toString()
              .toLowerCase()
          : Number(parseFieldValue(a[checkFieldName(fieldName)]));
    const valueB =
      fieldName === 'whenMade'
        ? parseWhenMade(fieldB)
        : isDataString(fieldName)
          ? parseFieldValue(b[checkFieldName(fieldName)])
              .toString()
              .toLowerCase()
          : Number(parseFieldValue(b[checkFieldName(fieldName)]));

    if (sortOrder === 'asc') {
      if (valueA < valueB) return -1;
      if (valueA > valueB) return 1;
      return 0;
    } else if (sortOrder === 'desc') {
      if (valueA > valueB) return -1;
      if (valueA < valueB) return 1;
      return 0;
    }
  };

  sortedData.sort(customSort);

  return sortedData;
};
