'use client';

import React, { useEffect, useRef } from 'react';
import { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import * as amplitude from '@amplitude/analytics-browser';
import { X, ArrowRight } from 'lucide-react';
import {
  closeBannerTouchpoint,
  dismissBannerTouchpoint,
} from '../../store/slices/userSlice';
import {
  CompactBannerWrapper,
  DefaultBannerWrapper,
  ShineOverlay,
} from './StyledWrapper';
import {
  buildOhoneyRedirectUrl,
  getOhoneyAppUrl,
} from '../../utils/ohoneyRedirect';

const OHONEY_LOGO_URL =
  'https://d3rjz9fmsdcq0v.cloudfront.net/logos/63035738-3835-4535-a644-71bde5ff9934.png';

const HEADLINE = 'Create. Mock up. Publish. All in one place.';
const SUBTEXT =
  'Winning sellers aren’t designing more. They’re publishing faster - Ohoney lets you process mockups and publish listings in bulk to Etsy in a few clicks.';
const CTA_LABEL = 'Start now';

// Which Etsy surface the extension is injected into, mirroring the OpoShop
// banner so the two campaigns stay comparable in Amplitude.
const getEtsyType = () => {
  if (window.location.pathname === '/') return 'home_page';
  if (window.location.href.includes('/shop/')) return 'shop_page';
  if (window.location.href.includes('/listing/')) return 'listing_page';
  if (window.location.href.includes('/search?q=')) return 'search_results';
  return 'other_page';
};

// Read fresh on each event: the extension is a long-lived injection and the
// user can navigate between Etsy pages without the banner remounting.
const buildEventProps = () => ({
  product_type: 'extension',
  feature_type: 'etsy',
  etsy_type: getEtsyType(),
  source_type: 'listing_details_sidebar',
});

const OhoneyPromoBanner = ({ variant = 'default', touchpoint }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [ohoneyUrl, setOhoneyUrl] = useState(getOhoneyAppUrl());
  const dispatch = useDispatch();

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const url = await buildOhoneyRedirectUrl();
      if (!cancelled && url) setOhoneyUrl(url);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const isDismissed = useSelector(
    (state) =>
      state.user.userData?.ui_flags?.ohoney_banners?.dismissed?.[touchpoint] ??
      true,
  );

  // Users who already claimed their Ohoney store are past the cross-sell, so
  // the banner is suppressed at every touchpoint — the same gate
  // `is_everbee_store_claimed` provides for the OpoShop banner.
  const isOhoneyClaimed = useSelector(
    (state) => state.user.userData?.is_ohoney_claimed ?? false,
  );

  const isVisible = touchpoint && !isDismissed && !isOhoneyClaimed;

  // Impression fires once per placement per Etsy page (RESEARCH-3196). The ref
  // holds the last-tracked placement+page pair so re-renders, and `isVisible`
  // flapping as `ui_flags` arrives, can't re-fire it.
  const lastImpressionKey = useRef(null);

  useEffect(() => {
    if (!isVisible) return;

    const impressionKey = `listing_details_sidebar|${getEtsyType()}`;
    if (lastImpressionKey.current === impressionKey) return;
    lastImpressionKey.current = impressionKey;

    amplitude.track('Ohoney_Banner_Impression', buildEventProps());
  }, [isVisible]);

  if (!isVisible) return null;

  const trackEvent = (eventName) => {
    amplitude.track(eventName, buildEventProps());
  };

  const handleDismiss = (e) => {
    e.stopPropagation();
    trackEvent('Ohoney_Banner_Dismiss');
    dispatch(dismissBannerTouchpoint({ touchpoint, product: 'ohoney' }));
    dispatch(closeBannerTouchpoint({ touchpoint, product: 'ohoney' }));
  };

  const handleCTAClick = (e) => {
    e.stopPropagation();
    trackEvent('Ohoney_Banner_CTA_Click');
    window.open(ohoneyUrl, '_blank');
  };

  // Compact variant for sidebar placement
  if (variant === 'compact') {
    return (
      <CompactBannerWrapper
        $isHovered={isHovered}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <ShineOverlay />

        <button
          className="dismiss-btn"
          onClick={handleDismiss}
          aria-label="Dismiss banner"
        >
          <span className="dismiss-icon">
            <X size={14} color="currentColor" />
          </span>
        </button>

        <div className="compact-content">
          <div className="compact-header">
            <div className="compact-logo-box">
              <img src={OHONEY_LOGO_URL} alt="Ohoney" />
            </div>
            <h3 className="banner-headline">{HEADLINE}</h3>
          </div>

          <p className="banner-subtext">{SUBTEXT}</p>

          <div className="compact-cta-wrapper">
            <button className="compact-cta-btn" onClick={handleCTAClick}>
              {CTA_LABEL}
              <ArrowRight size={14} color="currentColor" />
            </button>
          </div>
        </div>
      </CompactBannerWrapper>
    );
  }

  // Default full-width variant
  return (
    <DefaultBannerWrapper
      $isHovered={isHovered}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <ShineOverlay />

      <button
        className="dismiss-btn"
        onClick={handleDismiss}
        aria-label="Dismiss banner"
      >
        <span className="dismiss-icon">
          <X size={14} color="currentColor" />
        </span>
      </button>

      <div className="default-content">
        <div className="default-left-group">
          <div className="default-logo-box">
            <img src={OHONEY_LOGO_URL} alt="Ohoney" />
          </div>

          <div className="default-text-group">
            <h3 className="banner-headline">{HEADLINE}</h3>
            <p className="banner-subtext">{SUBTEXT}</p>
          </div>
        </div>

        <div className="default-cta-wrapper">
          <button className="default-cta-btn" onClick={handleCTAClick}>
            {CTA_LABEL}
            <ArrowRight size={16} color="currentColor" />
          </button>
        </div>
      </div>
    </DefaultBannerWrapper>
  );
};

export default OhoneyPromoBanner;
