/*global chrome*/
import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { CoursesContainer } from 'everbee-common-pages';
import {
  changeActiveMainMenu,
  changeActiveSubMenu,
  changeFeaturePage,
  changeIframeUrl,
  removeFeaturePage,
} from '../../store/slices/sidebarSlice';
import { setActivePage } from '../../store/slices/utilitySlice';
import { MAIN_MENU, SUB_MENU } from '../../constants/menuList';
import { StyledWrapper } from './StyledWrapper';

const CoursesPage = () => {
  const closeIcon = chrome.runtime.getURL('svg/cross.svg');
  const dispatch = useDispatch();

  const handleUrlCleanup = () => {
    const URL = new URLSearchParams(window.location.search);
    if (URL.get('openFeaturePage')) {
      URL.delete('openFeaturePage');
      URL.delete('keyword');
      const newUrl = `${window.location.origin}${window.location.pathname}?${URL.toString()}`;
      window.history.replaceState({}, '', newUrl);
    }
  };

  const handleClose = () => {
    dispatch(removeFeaturePage('courses'));
    handleUrlCleanup();
    dispatch(changeFeaturePage());
    dispatch(changeIframeUrl('close'));
  };

  useEffect(() => {
    dispatch(setActivePage('/courses'));
    dispatch(
      changeActiveSubMenu({
        value: SUB_MENU.COURSES,
        subMenuIndex: 3,
      }),
    );
    dispatch(changeActiveMainMenu(MAIN_MENU.COURSES));

    //eslint-disable-next-line
  }, []);

  return (
    <StyledWrapper>
      <div className="close-header">
        <div className="btn-close" onClick={handleClose}>
          <img src={closeIcon} alt="Close button" />
        </div>
      </div>
      <div className="main-area">
        <div className="header">
          <div className="main-heading">Discover our courses</div>
          <div className="sub-heading">
            Enjoy EverBee&apos;s selection of Free Courses for E-commerce and
            Etsy Success
          </div>
        </div>
        <CoursesContainer />
      </div>
    </StyledWrapper>
  );
};

export default CoursesPage;
