import { useEffect } from "react";
import * as amplitude from '@amplitude/analytics-browser';

function useHoverTrack(listingDetailsData) {
  useEffect(() => {
    if (!listingDetailsData) return; // Exit early if there's no data
    let hoverTimeout;
    // Function to handle the hover event
    const handleMouseOver = (e) => {
      const targetDiv = e.currentTarget;
      hoverTimeout = setTimeout(() => {
        const divName = targetDiv.querySelector(".eb-label")?.innerText;
        // Track metrics using amplitude
        amplitude.track("Hover On Page Metrics", {
          metrics: divName,
          product_name: listingDetailsData?.title,
          product_url: `https://www.etsy.com/listing/${listingDetailsData?.listingId}`,
        });
      }, 2000); // 2 seconds
    };
    // Function to handle the mouseout event
    const handleMouseOut = () => {
      clearTimeout(hoverTimeout);
    };
    // List of div IDs to track hover events on
    const divIds = [
      "eb-conversionRateDiv",
      "eb-reviewsDiv",
      "eb-moSalesDiv",
      "eb-viewsDiv",
      "eb-favoritesDiv",
      "eb-totalSalesDiv",
      "eb-listingAgeDiv",
    ];
    // Attach event listeners to each div
    divIds.forEach((id) => {
      const divElement = document?.getElementById(id);
      divElement?.addEventListener("mouseover", handleMouseOver);
      divElement?.addEventListener("mouseout", handleMouseOut);
    });
    // Cleanup function to remove the event listeners
    return () => {
      divIds.forEach((id) => {
        const divElement = document?.getElementById(id);
        divElement?.removeEventListener("mouseover", handleMouseOver);
        divElement?.removeEventListener("mouseout", handleMouseOut);
      });
    };
  }, [listingDetailsData]);
}

export default useHoverTrack;
