/*global chrome*/
import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';
import { AnimatePresence, motion } from 'framer-motion';
import { Star, Download, X, Copy } from 'lucide-react';
import * as amplitude from '@amplitude/analytics-browser';
import HeaderTooltip from '../../CustomToolTip/HeaderTooltip';
import RemoveFromFavConfirmModal from '../../RemoveFromFavConfirmModal';
import favKeywordPopup from '../../FavUpdateToast/Keywords/FavKeywordPopup';
import {
  clearSidePanTagsCheckedRows,
  clearModalTagsCheckedRows,
  toggleRemoveFromFavConfirmModal,
  updateSidePaneTagsIsFavBulk,
  setBulkKeywordRowsForChange,
  setIsNewFavFolderModal,
  exportKeywordsByIds,
} from '../../../store/slices/utilitySlice';
import {
  manageFavItemsInFolders,
  setKeywordFolderMgmtModalStatus,
  setManagementModalStatus,
  toggleKeywordsWatchlistModal,
  setCurrentKeywordRowData,
} from '../../../store/slices/favoritesSlice';
import { updateFavoriteCount } from '../../../store/slices/userSlice';
import {
  getFavoriteLimitErrorMessage,
  showFavoriteLimitErrorToast,
} from '../../../utils/favoriteLimitHelpers';

const StyledWrapper = styled.div`
  background: #313233;
  box-shadow:
    0 10px 15px -3px rgba(0, 0, 0, 0.1),
    0 4px 6px -4px rgba(0, 0, 0, 0.1);
  border-radius: 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7.5px 9px 7.5px 12px;
  font-family: 'Satoshi', sans-serif;

  ${({ $inline, $inlineTop }) =>
    $inline
      ? `
    position: absolute;
    z-index: 30;
    left: 50%;
    top: ${$inlineTop ?? '50%'};
    transform: translate(-50%, -50%);
    width: fit-content;
  `
      : `
    position: absolute;
    z-index: 30;
    left: 50%;
    bottom: 16px;
    transform: translateX(-50%);
    width: fit-content;
  `}

  .selected-rows {
    font-weight: 500;
    font-size: 12px;
    line-height: 17px;
    color: #ffffff;
    white-space: nowrap;
  }

  .divider {
    width: 1px;
    height: 17px;
    background: rgba(255, 255, 255, 0.2);
    flex-shrink: 0;
  }

  .actions {
    display: flex;
    align-items: center;
    gap: 3px;
  }

  .action-btn {
    background: transparent;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 7px;
    border-radius: 5px;
    transition: background 0.2s;
    color: #fafafa;

    &:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    &:disabled {
      cursor: not-allowed;
      opacity: 0.5;

      &:hover {
        background: transparent;
      }
    }
  }

  .close-btn {
    background: transparent;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 5px;
    border-radius: 5px;
    transition: background 0.2s;
    color: rgba(255, 255, 255, 0.6);

    &:hover {
      background: rgba(255, 255, 255, 0.1);
      color: #ffffff;
    }
  }
`;

const ICON_SIZE = 14;

const tickAnimation = {
  initialOptions: { opacity: 0 },
  animateOptions: { opacity: 1 },
  exitOptions: { opacity: 0 },
};

const getEtsyType = () => {
  if (typeof window === 'undefined') return 'other_page';
  if (window.location.pathname === '/') return 'home_page';
  if (window.location.href.includes('/shop/')) return 'shop_page';
  if (window.location.href.includes('/listing/')) return 'listing_page';
  if (window.location.href.includes('/search?q=')) return 'search_results';
  return 'other_page';
};

const KeywordSelectedRow = ({
  noOfCheckedRows,
  sourceProp = 'sp-ta',
  sourceContext = 'listing_details',
  onFavSuccess,
  onFavError,
  onAfterAction,
  inline = false,
  inlineTop,
  stateSource = 'sidepane',
}) => {
  const dispatch = useDispatch();
  const Tick = chrome.runtime.getURL('svg/green-tick.svg');
  const [isFavLoading, setIsFavLoading] = useState(false);
  const [keywordsCopied, setKeywordsCopied] = useState(false);

  const { isInIframe, isRemoveFromFavConfirmModal } = useSelector(
    (state) => state.utilities,
  );
  const checkedRowsData = useSelector((state) =>
    stateSource === 'modal'
      ? state.utilities.modalTagsCheckedRowsData
      : state.utilities.sidePanTagsCheckedRowsData,
  );
  const { keywordsFolderData, keywordsDefaultFolderData } = useSelector(
    (state) => state.watchlist,
  );

  const isKeywordFolderManagement = useSelector(
    (state) => state.watchlist.folderManagementModalStatus.keyword,
  );

  const allFavorited =
    checkedRowsData?.length > 0 &&
    checkedRowsData.every((row) => row.isFav === true);

  const defaultFolderIds = keywordsDefaultFolderData.map((f) => f.id);
  const defaultFolderDetails = keywordsDefaultFolderData.map((f) => ({
    name: f.name,
    id: f.id,
  }));

  const trackBulkEvent = (eventName, extra = {}) => {
    amplitude.track(eventName, {
      product_type: isInIframe ? 'extension' : 'research',
      feature_type: 'etsy',
      etsy_type: getEtsyType(),
      source_type: sourceContext,
      item_type: 'keyword_analytic',
      is_bulk: true,
      ...extra,
    });
  };

  const handleCloseButton = () => {
    dispatch(
      stateSource === 'modal'
        ? clearModalTagsCheckedRows()
        : clearSidePanTagsCheckedRows(),
    );
    onAfterAction?.();
  };

  const handleBulkFavorite = async () => {
    if (isFavLoading) return;

    if (keywordsFolderData.length === 0) {
      trackBulkEvent('Add_To_Favorites_Click', {
        is_first_favorites_action_of_day: true,
      });
      if (checkedRowsData?.length > 0) {
        dispatch(
          setBulkKeywordRowsForChange({
            rows: checkedRowsData,
            source: stateSource,
          }),
        );
        dispatch(setCurrentKeywordRowData(checkedRowsData[0]));
      }
      dispatch(setIsNewFavFolderModal(true));
      return;
    }

    if (isKeywordFolderManagement || defaultFolderIds.length === 0) {
      dispatch(toggleKeywordsWatchlistModal(true));
      if (isKeywordFolderManagement) {
        trackBulkEvent('Add_To_Favorites_Click', {
          is_first_favorites_action_of_day: true,
        });
        dispatch(setManagementModalStatus({ itemType: 'keyword_analytic' }));
        dispatch(setKeywordFolderMgmtModalStatus(false));
      }
      return;
    }

    const toFavorite = checkedRowsData.filter((row) => !row.isFav);
    if (toFavorite.length === 0) return;

    const toFavoriteIds = toFavorite.map((row) => row.keywordId);

    setIsFavLoading(true);
    try {
      const action = await dispatch(
        manageFavItemsInFolders({
          itemIdsArray: toFavoriteIds,
          type: 'keyword_analytic',
          folderIdsArray: defaultFolderIds,
          idType: 'database',
        }),
      );

      const limitMessage = getFavoriteLimitErrorMessage(action);
      if (limitMessage) {
        if (onFavError) {
          onFavError(limitMessage);
        } else {
          showFavoriteLimitErrorToast(action);
        }
        dispatch(
          stateSource === 'modal'
            ? clearModalTagsCheckedRows()
            : clearSidePanTagsCheckedRows(),
        );
        onAfterAction?.();
        return;
      }
      if (action.meta.requestStatus !== 'fulfilled') return;

      dispatch(
        updateSidePaneTagsIsFavBulk({
          keywordIds: toFavoriteIds,
          isFavBool: true,
        }),
      );
      dispatch(
        updateFavoriteCount({
          type: 'keywordCount',
          amount: toFavorite.length,
        }),
      );

      trackBulkEvent('Add_To_Favorites_Click', {
        target_folders_count: defaultFolderIds.length,
        selected_count: toFavorite.length,
        is_first_favorites_action_of_day: false,
      });

      dispatch(
        setBulkKeywordRowsForChange({ rows: toFavorite, source: stateSource }),
      );

      setTimeout(() => {
        if (onFavSuccess) {
          onFavSuccess(toFavorite, defaultFolderDetails, 'add');
        } else {
          favKeywordPopup(toFavorite[0], defaultFolderDetails, 'add');
        }
      }, 300);

      onAfterAction?.();
    } finally {
      setIsFavLoading(false);
    }
  };

  const handleBulkUnfavoriteClick = () => {
    const toUnfav = checkedRowsData.filter((row) => row.isFav);
    if (toUnfav.length === 0) return;
    dispatch(toggleRemoveFromFavConfirmModal(true));
  };

  const handleKeywordsCopy = () => {
    if (!checkedRowsData || checkedRowsData.length === 0 || keywordsCopied) {
      return;
    }

    setKeywordsCopied(true);

    const keywords = checkedRowsData.map((item) => item.keywords).join(', ');
    navigator.clipboard.writeText(keywords);

    trackBulkEvent('Keyword_Copied', {
      selected_count: checkedRowsData.length,
    });

    setTimeout(() => {
      setKeywordsCopied(false);
    }, 2000);
  };

  const handleBulkExport = () => {
    if (!checkedRowsData?.length) return;
    const keywordIds = checkedRowsData.map((r) => r.keywordId);
    amplitude.track('Export_Click', {
      product_type: isInIframe ? 'extension' : 'research',
      feature_type: 'etsy',
      etsy_type: getEtsyType(),
    });
    dispatch(exportKeywordsByIds({ keywordIds })).then((result) => {
      if (result.meta.requestStatus === 'fulfilled') {
        dispatch(
          stateSource === 'modal'
            ? clearModalTagsCheckedRows()
            : clearSidePanTagsCheckedRows(),
        );
        onAfterAction?.();
      }
    });
  };

  return (
    <>
      <StyledWrapper $inline={inline} $inlineTop={inlineTop}>
        <span className="selected-rows">
          {noOfCheckedRows} item{noOfCheckedRows !== 1 ? 's' : ''} selected
        </span>
        <div className="divider" />
        <div className="actions">
          {allFavorited ? (
            <HeaderTooltip title="Remove from favorites" placement="top" arrow>
              <button
                className="action-btn"
                onClick={handleBulkUnfavoriteClick}
                aria-label="Unfavorite selected"
              >
                <Star size={ICON_SIZE} fill="#FAFAFA" color="#FAFAFA" />
              </button>
            </HeaderTooltip>
          ) : (
            <HeaderTooltip title="Add to favorites" placement="top" arrow>
              <button
                className="action-btn"
                onClick={handleBulkFavorite}
                aria-label="Favorite selected"
                disabled={isFavLoading}
              >
                <Star size={ICON_SIZE} color="#FAFAFA" />
              </button>
            </HeaderTooltip>
          )}
          <HeaderTooltip
            title={keywordsCopied ? 'Copied' : 'Copy keywords'}
            placement="top"
            arrow
          >
            <button
              className="action-btn"
              onClick={handleKeywordsCopy}
              aria-label="Copy selected keywords"
            >
              {keywordsCopied ? (
                <AnimatePresence>
                  <motion.div
                    variants={tickAnimation}
                    initial="initialOptions"
                    animate="animateOptions"
                    exit="exitOptions"
                    transition={{ duration: 0.3 }}
                    style={{ display: 'flex' }}
                  >
                    <img
                      src={Tick}
                      alt="copied"
                      height={ICON_SIZE}
                      width={ICON_SIZE}
                    />
                  </motion.div>
                </AnimatePresence>
              ) : (
                <Copy size={ICON_SIZE} color="#FAFAFA" />
              )}
            </button>
          </HeaderTooltip>
          <HeaderTooltip title="Export" placement="top" arrow>
            <button
              className="action-btn"
              onClick={handleBulkExport}
              aria-label="Export selected"
            >
              <Download size={ICON_SIZE} color="#FAFAFA" />
            </button>
          </HeaderTooltip>
        </div>
        {/* <div className="divider" /> */}
        <button
          className="close-btn"
          onClick={handleCloseButton}
          aria-label="Clear selection"
        >
          <X size={ICON_SIZE} />
        </button>
      </StyledWrapper>

      <RemoveFromFavConfirmModal
        open={isRemoveFromFavConfirmModal}
        onAfterAction={onAfterAction}
        stateSource={stateSource}
      />
    </>
  );
};

export default KeywordSelectedRow;
