export function getTrueKey(obj) {
    for (const key in obj) {
        if (obj[key] === true) {
            if (key !== key.toLowerCase()) {
                // Convert each word to capitalized format
                return key.split(/(?=[A-Z])/).map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
            } else {
                // Convert the first letter to uppercase
                return key.charAt(0).toUpperCase() + key.slice(1);
            }
        }
    }
    return null; // Return null if no key with value true is found
}