import { useSelector } from 'react-redux';
import styled from 'styled-components';

const StyledWrapper = styled.div`
  height: 150px;
  width: 33%;
  padding-left: 24px;
  padding-right: 24px;

  &:not(:last-child) {
    border-right: 1px solid #f0f0f0;
  }

  .heading {
    font-size: 14px;
    font-weight: 600;
  }

  .detail-items {
    height: 88px;
    border-bottom: 1px dashed #e6e6e6;
  }

  .item {
    font-size: 12px;
    // Margin values were 8px
    margin-top: 4.5px;
    margin-bottom: 4.5px;
    display: flex;
    justify-content: space-between;
  }

  .name {
    color: #505152;
  }

  .price {
    color: #19191a;
  }

  .total {
    font-size: 12px;
    font-weight: 600;
    margin-top: 12px;
    display: flex;
    justify-content: space-between;
  }
`;

const CalculatorDetailTile = ({ tileValues }) => {
  const { heading: mainTileHeading, total: mainTileTotal } = tileValues;
  const activeDiscountUnit = useSelector(
    (state) => state.utilities.activeDiscountUnit,
  );
  return (
    <StyledWrapper>
      <div className="heading">{mainTileHeading}</div>
      <div className="detail-items">
        {tileValues.tilesData.map((item) => {
          let itemValue = item.value;
          if (item.heading === 'Discount' && activeDiscountUnit === 'percent') {
            itemValue = Number(
              ((itemValue / 100) * tileValues.tilesData[0]?.value).toFixed(2),
            );
          }
          if (mainTileHeading === 'Fees' || mainTileHeading === 'Costs') {
            itemValue = -1 * item.value;
          }
          return (
            <div className="item" key={item.heading}>
              <div className="name">{item.heading}</div>
              <div className="price">
                {itemValue < 0 ? '-' : null}$
                {itemValue < 0
                  ? (-1 * itemValue).toFixed(2)
                  : itemValue == 0
                    ? itemValue
                    : Number(itemValue).toFixed(2)}
              </div>
            </div>
          );
        })}
      </div>
      <div className="total">
        <div className="total-tag">Total</div>
        <div className="total-value">
          {(mainTileHeading === 'Fees' || mainTileHeading === 'Costs') &&
            mainTileTotal != 0 &&
            '-'}
          ${mainTileTotal === 0 ? mainTileTotal : mainTileTotal.toFixed(2)}
        </div>
      </div>
    </StyledWrapper>
  );
};

export default CalculatorDetailTile;
