/*global chrome*/
import * as amplitude from '@amplitude/analytics-browser';
import { extensionAttributes } from '../services/account';

export async function isExtActive() {
  let active = await storageGet('activeExt');
  turnOnAmpFun(active);
  extensionProperties(active);
}
function turnOnAmpFun(active) {
  if (`${active}` != localStorage.getItem('turn-on')) {
    if (active) {
      amplitude.track(`Turn on - extension`);
      localStorage.setItem('turn-on', true);
    } else {
      amplitude.track(`Turn off - extension`);
      localStorage.setItem('turn-on', false);
    }
  }
}

function storageGet(key) {
  return new Promise((resolve) => {
    chrome.storage?.local.get([key], function (result) {
      resolve(result[key]);
    });
  });
}

async function extensionProperties(active) {
  if (await storageGet('extInfo')) {
    let { isOnToolbar } = await storageGet('extInfo');
    try {
      await extensionAttributes({
        installed: true,
        active: active,
        pinned: isOnToolbar,
      });
    } catch (err) {}
    const identify = new amplitude.Identify();
    identify.set('pin', isOnToolbar).set('extension_turned_on', active);
    amplitude.identify(identify);
    if (`${isOnToolbar}` != localStorage.getItem('pin')) {
      localStorage.setItem('pin', isOnToolbar);
      if (isOnToolbar) {
        amplitude.track(`pin - extension`);
      } else {
        amplitude.track(`unpin - extension`);
      }
    }
  }
}
