'use client';

import React, { useEffect, useMemo } from 'react';
import { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import * as amplitude from '@amplitude/analytics-browser';
import { Rocket, X, ArrowRight } from 'lucide-react';
import {
  closeBannerTouchpoint,
  dismissBannerTouchpoint,
} from '../../store/slices/userSlice';
import {
  CompactBannerWrapper,
  DefaultBannerWrapper,
  ShineOverlay,
} from './StyledWrapper';
import {
  buildOposhopRedirectUrl,
  getOposhopAppUrl,
} from '../../utils/oposhopRedirect';

const StorePromoBanner = ({ variant = 'default', touchpoint }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [oposhopUrl, setOposhopUrl] = useState(
    `${getOposhopAppUrl()}?from_research=true`,
  );
  const dispatch = useDispatch();

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const url = await buildOposhopRedirectUrl();
      if (!cancelled) setOposhopUrl(url);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const isDismissed = useSelector(
    (state) =>
      state.user.userData?.ui_flags?.banners?.dismissed?.[touchpoint] ?? true,
  );

  const isStoreClaimed = useSelector(
    (state) => state.user.userData?.is_everbee_store_claimed ?? false,
  );

  const isVisible = touchpoint && !isDismissed && !isStoreClaimed;

  useEffect(() => {
    if (isVisible) {
      amplitude.track('Store_Promo_Banner_Impression', {
        product_type: 'extension',
        feature_type: 'etsy',
        etsy_type:
          window.location.pathname === '/'
            ? 'home_page'
            : window.location.href.includes('/shop/')
              ? 'shop_page'
              : window.location.href.includes('/listing/')
                ? 'listing_page'
                : window.location.href.includes('/search?q=')
                  ? 'search_results'
                  : 'other_page',
        source_type: 'listing_details_sidebar',
      });
    }
  }, [isVisible]);

  if (!isVisible) return null;

  const trackEvent = (eventName) => {
    amplitude.track(eventName, {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      source_type: 'listing_details_sidebar',
    });
  };

  const handleDismiss = (e) => {
    e.stopPropagation();
    trackEvent('Store_Promo_Banner_Dismiss');
    dispatch(dismissBannerTouchpoint({ touchpoint, product: 'oposhop' }));
    dispatch(closeBannerTouchpoint({ touchpoint, product: 'oposhop' }));
  };

  const handleCTAClick = (e) => {
    e.stopPropagation();
    trackEvent('Store_Promo_Banner_CTA_Click');
    window.open(oposhopUrl, '_blank');
  };

  // Compact variant for sidebar placement
  if (variant === 'compact') {
    return (
      <CompactBannerWrapper
        $isHovered={isHovered}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        <ShineOverlay />

        <button
          className="dismiss-btn"
          onClick={handleDismiss}
          aria-label="Dismiss banner"
        >
          <span className="dismiss-icon">
            <X size={14} color="currentColor" />
          </span>
        </button>

        <div className="compact-content">
          <div className="compact-header">
            <div className="compact-icon-box">
              <Rocket size={16} color="#fff" />
            </div>
            <h3 className="banner-headline">
              Turn your Etsy Shop Into a Scalable Brand
            </h3>
          </div>

          <p className="banner-subtext">
            Launch a standalone online store you fully own, control, and can
            scale.
          </p>

          <div className="compact-cta-wrapper">
            <button className="compact-cta-btn" onClick={handleCTAClick}>
              Build My OpoShop
              <ArrowRight size={14} color="currentColor" />
            </button>
          </div>
        </div>
      </CompactBannerWrapper>
    );
  }

  // Default full-width variant
  return (
    <DefaultBannerWrapper
      $isHovered={isHovered}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <ShineOverlay />

      <button
        className="dismiss-btn"
        onClick={handleDismiss}
        aria-label="Dismiss banner"
      >
        <span className="dismiss-icon">
          <X size={14} color="currentColor" />
        </span>
      </button>

      <div className="default-content">
        <div className="default-left-group">
          <div className="default-icon-box">
            <Rocket size={24} color="#fff" />
          </div>

          <div className="default-text-group">
            <h3 className="banner-headline">
              Turn your Etsy Shop Into a Scalable Brand
            </h3>
            <p className="banner-subtext">
              Launch a standalone online store you fully own, control, and can
              scale.
            </p>
          </div>
        </div>

        <div className="default-cta-wrapper">
          <button className="default-cta-btn" onClick={handleCTAClick}>
            Build My OpoShop
            <ArrowRight size={16} color="currentColor" />
          </button>
        </div>
      </div>
    </DefaultBannerWrapper>
  );
};

export default StorePromoBanner;
