import { nanoid } from "@reduxjs/toolkit";

export const COLUMN_NAMES_MAP = {
  // Keyword table constants
  keywords: { headerName: 'Keywords', backendName: 'keyword' },
  volume: { headerName: 'Volume', backendName: 'vol' },
  competition: { headerName: 'Competition', backendName: 'competition' },
  keywordScore: { headerName: 'Keyword Score', backendName: 'score' },
  trend: { headerName: 'Trend', backendName: 'trend' },
};

export const isDataString = (headerFieldName) => {
  if (
    headerFieldName === 'product' ||
    headerFieldName === 'shopName' ||
    headerFieldName === 'category' ||
    headerFieldName === 'shippedFrom' ||
    headerFieldName === 'whoMade' ||
    headerFieldName === 'keywords' ||
    headerFieldName === 'slListings' ||
    headerFieldName === 'shopNameSA' ||
    headerFieldName === 'currencyCode' ||
    headerFieldName === 'shopLocationCountryIso'
  ) {
    return true;
  } else return false;
};

export const mapTags = (item) => {
  return {
    id: nanoid(),
    keywordId: item.id,
    keywords: item.keyword,
    volume: item.new_volume,
    competition: item.competition,
    keywordScore: item.score,
    trend: item.trend,
    isFav: item.is_fav || false,
  };
};
