import { createSlice } from '@reduxjs/toolkit';
import { MAIN_MENU } from '../../constants/menuList';
import { toCamelCase } from '../../helper/convertToCamelCase';
// import { getSingleListingDetailsAPI } from '../../services/listing';

const initialState = {
  isExpanded: false,
  activeMainMenu: MAIN_MENU.RESEARCH_TOOLS,
  activeSubMenu: {
    value: null,
    subMenuIndex: null,
  },
  featurePage: {
    productAnalytics: false,
    keywordResearch: false,
    etsyCalculator: false,
    favorites: false,
    ambassadors: false,
    loginPage: false,
    account: false,
    pricing: false,
    evermail: false,
    everprint: false,
    shopAnalyzer: false,
    dashboard: false,
    connectShop: false,
    aiConnectors: false,
  },
  iframeUrl: '/ext',
  isRightPaneOpen: false,
  isProfilePopover: false,
};

export const sidebarSlice = createSlice({
  name: 'sidebar',
  initialState,
  reducers: {
    // Explicit boolean sets; only a bare toggleSidebar() flips. `if (payload)`
    // sent `toggleSidebar(false)` down the flip branch, so onboarding's two
    // closes (highlight click + intro.js onexit) re-opened the rail.
    toggleSidebar: (state, { payload }) => {
      state.isExpanded = payload === undefined ? !state.isExpanded : Boolean(payload);
    },
    changeActiveMainMenu: (state, { payload }) => {
      state.activeMainMenu = payload;
    },
    changeActiveSubMenu: (state, { payload }) => {
      state.activeSubMenu = payload;
    },
    changeFeaturePage: (state, { payload }) => {
      state.featurePage = Object.keys(state.featurePage).reduce((acc, key) => {
        acc[key] = false;
        return acc;
      }, {});
      if (payload) {
        state.featurePage[toCamelCase(payload)] = true;
      }
    },
    removeFeaturePage: (state, { payload }) => {
      state.featurePage[toCamelCase(payload)] = false;
    },
    openFeaturePage: (state, { payload }) => {
      state.featurePage = {
        ...state.featurePage,
        [toCamelCase(payload)]: true,
      };
    },
    toggleRightPane: (state, { payload }) => {
      state.isRightPaneOpen = payload;
    },
    setProfilePopover: (state, { payload }) => {
      state.isProfilePopover = payload;
    },
    toggleProfilePopover: (state) => {
      state.isProfilePopover = !state.isProfilePopover;
    },
    changeIframeUrl: (state, { payload }) => {
      if (payload === 'close') {
        state.iframeUrl = `/ext`;
      } else {
        state.iframeUrl = `/ext/${payload}`;
      }
    },
  },
});

export const {
  toggleSidebar,
  changeActiveMainMenu,
  changeActiveSubMenu,
  changeActiveFeaturePage,
  changeFeaturePage,
  openFeaturePage,
  removeFeaturePage,
  toggleRightPane,
  setProfilePopover,
  toggleProfilePopover,
  changeIframeUrl,
} = sidebarSlice.actions;

export default sidebarSlice.reducer;
