/*global chrome*/
import { useState, useEffect } from 'react';
import { debounce } from '../helper/getDebounce';
import { keywordSuggestion } from '../services/listing';
// import LockedIconComponent from "../components/LockedIconComponent";
import { getNumberWithCommas } from '../helper/getNumberWithCommas';

export default function SearchBarKeywordSuggestion() {
  const [searchValue, setSearchValue] = useState(null);
  const [suggestionLoading, setSuggestionLoading] = useState(false);
  const [suggestionsVolume, setSuggestionsVolume] = useState({});

  const searchbarImg = chrome.runtime.getURL('images/lock-icon.svg');
  const loadingImg = chrome.runtime.getURL('images/loadingT.gif');
  const keywordSuggestionImg = chrome.runtime.getURL(
    'images/EverBee-logo-suggestion.png',
  );

  const getdebouncedData = debounce(setSearchValue);

  function focusHandler() {
    const searchInput_ = document
      .getElementById('global-enhancements-search-query')
      .value?.trim();
    const saved_suggestions = JSON.parse(
      localStorage.getItem('everbee-keyword-suggestions'),
    );
    if (saved_suggestions && saved_suggestions[searchInput_]) {
      setTimeout(() => {
        setSuggestionsVolume(saved_suggestions[searchInput_]);
      }, 1000);
    } else {
      setSearchValue(searchInput_);
    }
  }

  function changeHandler(event) {
    const { value } = event.target;
    if (localStorage.getItem('everbee-keyword-suggestions'))
      localStorage.removeItem('everbee-keyword-suggestions');
    getdebouncedData(value.trim());
  }

  // lock-icon onsearchbar (start)
  function linkHandler(e) {
    e.stopPropagation();

    window.open(`${process.env.REACT_APP_FRONTEND_URL}/pricing`);
  }

  //get all suggestions
  function getSearchSuggestion() {
    let suggestionsArray = [];
    const child = document.querySelectorAll('.as-suggestion > strong');
    child.forEach((item, index) => {
      if (index < child.length) {
        if (!item?.textContent?.includes('find shop names containing')) {
          suggestionsArray.push(item?.textContent);
        }
      }
    });
    if (suggestionsArray.length > 0) {
      getKeywordSuggestions(suggestionsArray);
    }
  }

  function addVolumeToUI() {
    const loaders = document.querySelectorAll('#loader');
    const child = document.querySelectorAll('.as-entry');
    if (suggestionLoading) {
      child.forEach((element, index) => {
        element.style.display = 'flex';
        console.log('element.innerText - ', element.innerText);
        if (
          index < child.length &&
          !element.innerText?.includes('see more') &&
          !element.innerText?.includes('find shop names containing') &&
          !element.innerText?.includes('N/A')
        ) {
          element.innerHTML += `<img class="keyword-marginleft"  id="loader" src=${loadingImg} alt="logo" />`;
        }
      });
    } else {
      loaders.forEach((element) => element.remove());
      const suggestion_divs = document.querySelectorAll('.keyword-suggestion');

      suggestion_divs.forEach((box) => {
        box.remove();
      });
      child.forEach((element, index) => {
        element.style.display = 'flex';
        console.log('element.innerText - ', element.innerText);

        if (
          index < child.length &&
          !element.innerText?.includes('see more') &&
          !element.innerText?.includes('find shop names containing') &&
          !element.innerText?.includes('N/A')
        ) {
          if (
            suggestionsVolume[element.innerText.replaceAll(' ', '_')] ==
            'Please upgrade'
          ) {
            element.innerHTML += `<img src=${searchbarImg} width="20px" alt="img" class="searchbar-lockicon" style="margin-left:20px;"/>`;
          } else if (
            suggestionsVolume[element.innerText.replaceAll(' ', '_')] ===
            undefined
          ) {
            element.innerHTML += `<div class="suggestion-box">
            <img src=${keywordSuggestionImg} alt="logo" class ="keyword-icon" />
            <span class="keyword-vol keyword-vol-NA">N/A</span>
             </div>`;
          } else {
            element.innerHTML += `<div class="suggestion-box">
          <img src=${keywordSuggestionImg} alt="logo" class ="keyword-icon" />
          <span class="keyword-vol">${getNumberWithCommas(
            suggestionsVolume[element.innerText.replaceAll(' ', '_')],
          )}</span>
          <span class="keyword-text">monthly searches </span> 
          <span class="keyword-text"> <a class="see-more" onclick="event.stopPropagation(); window.location.href = 'https://www.etsy.com/search?q=${encodeURIComponent(element.innerText)}&openFeaturePage=keywordResearch&keyword=${element.innerText.replaceAll(
            ' ',
            '_',
          )}'">see more </a> </span>
           </div>`;
          }
        }
      });
    }
  }

  //api call
  const getKeywordSuggestions = async (keywords) => {
    let keywordVolumePair = {};
    try {
      const {
        data: { results },
      } = await keywordSuggestion(keywords);
      for (let i = 0; i < results.length; i++) {
        keywordVolumePair = {
          ...keywordVolumePair,
          [`${results[i].keyword}`.replaceAll(' ', '_')]: results[i].vol,
        };
      }
      localStorage.setItem(
        'everbee-keyword-suggestions',
        JSON.stringify({ [searchValue]: keywordVolumePair }),
      );
      setSuggestionsVolume(keywordVolumePair);
      setSuggestionLoading(false);
    } catch (error) {
      // Nothing
    }
  };

  useEffect(() => {
    const searchField = document.getElementById(
      'global-enhancements-search-query',
    );
    if (searchField) {
      searchField.addEventListener('input', (e) => {
        changeHandler(e);
      });

      searchField.addEventListener('focus', () => {
        focusHandler();
      });
      searchField?.addEventListener('input', () => {
        var currentValue = searchField.value;
        if (currentValue.includes('monthly searches')) {
          // Nothing
        }
      });
    }
  }, []);

  useEffect(() => {
    if (searchValue?.length > 2) {
      setSuggestionLoading(true);
      setTimeout(() => {
        getSearchSuggestion();
      }, 500);
    }
  }, [searchValue]);

  useEffect(() => {
    addVolumeToUI();
  }, [suggestionLoading, suggestionsVolume]);

  const listItem = document.querySelectorAll('.wt-menu__item');
  listItem.forEach((item) => {
    if (item) {
      item.addEventListener('click', () => {
        const removeKeyword = document.querySelectorAll('.keyword-suggestion');
        if (removeKeyword.length !== 0) {
          removeKeyword?.forEach((keyword) => keyword?.remove());
        }
      });
    }
  });

  setTimeout(() => {
    const icons = document.querySelectorAll('.searchbar-lockicon');
    icons.forEach((item) => {
      if (item) {
        item.addEventListener('click', linkHandler);
      }
    });
  }, 2000);
  // lock-icon onsearchbar (end)

  return null;
}
