const getStylesForConversionRate = (conversionRate) => {
  let backgroundColor = '';
  let color = '';
  if (conversionRate < 0.1) {
    backgroundColor = '#F1706C33';
    color = '#DC3C36';
  } else if (conversionRate >= 0.1 && conversionRate < 5) {
    backgroundColor = '#6FB4F733';
    color = '#1F76CC';
  } else if (conversionRate >= 5) {
    backgroundColor = '#4AA65933';
    color = '#4AA659';
  }
  return { backgroundColor, color };
};
