
import { getExtListingDetailsAPI } from '../services/listing';

export async function getExtPaRowData(
  listingIdsArray,
  extSearchTerm,
  curr,
  type,
) {
  try {
    const res = await getExtListingDetailsAPI(
      listingIdsArray,
      extSearchTerm,
      curr,
      type,
    );
    var rowDataArray = [];
    var failedListingIdsArray = [];
    const apiResult = res.data?.results;
    if (apiResult) {
      for (var i = 0; i < apiResult.length; i++) {
        if (apiResult[i].message !== 'Error') {
          rowDataArray.push(apiResult[i]);
        } else {
          failedListingIdsArray.push(apiResult[i].listing_id);
        }
      }
      return {
        rowDataArrays: rowDataArray,
        failedListingIdsArray: failedListingIdsArray,
      };
    } else {
      return { error: true };
    }
  } catch (err) {
    return { error: true, errorDetails: err?.response?.data };
  }
}
