/*global chrome*/
import React, { useEffect, useMemo, useState } from 'react';
import { Skeleton } from '@mui/material';
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
} from '../ui/carousel';
import { StyledImageCarousel } from './StyledWrapper';

const getSlides = (details, fallbackAvatar) => {
  const list = Array.isArray(details?.listingImages)
    ? details.listingImages
    : [];
  const urls = [...list]
    .sort((a, b) => (a?.rank ?? 0) - (b?.rank ?? 0))
    .map((img) => img?.url)
    .filter(Boolean);

  if (urls.length) return urls;

  const img = details?.image;
  return [img ? (typeof img === 'string' ? img : img.src) : fallbackAvatar];
};

const ImageCarousel = ({ details }) => {
  const testAvatar = chrome.runtime.getURL('images/test-avatar.jpg');

  const slides = useMemo(
    () => getSlides(details, testAvatar),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [details?.listingImages, details?.image],
  );
  const hasMultiple = slides.length > 1;

  const [api, setApi] = useState(null);
  const [current, setCurrent] = useState(0);
  const [loaded, setLoaded] = useState({});

  useEffect(() => {
    if (!api) return;
    const onSelect = () => setCurrent(api.selectedScrollSnap());
    onSelect();
    api.on('select', onSelect);
    return () => api.off('select', onSelect);
  }, [api]);

  // Reset to first slide + re-show skeletons when the listing/images change
  useEffect(() => {
    setCurrent(0);
    setLoaded({});
    if (api) api.scrollTo(0, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slides]);

  return (
    <StyledImageCarousel>
      <Carousel
        setApi={setApi}
        opts={{ loop: true }}
        style={{ height: '100%', width: '100%' }}
      >
        <CarouselContent>
          {slides.map((url, i) => (
            <CarouselItem key={`${url}-${i}`}>
              <div className="slide">
                {!loaded[i] && (
                  <Skeleton
                    variant="rounded"
                    animation="wave"
                    width="100%"
                    height="100%"
                    sx={{ position: 'absolute', inset: 0, borderRadius: '6px' }}
                  />
                )}
                <img
                  src={url}
                  alt="N/A"
                  className="slide-img"
                  onLoad={() =>
                    setLoaded((prev) => ({ ...prev, [i]: true }))
                  }
                />
              </div>
            </CarouselItem>
          ))}
        </CarouselContent>

        {hasMultiple && (
          <>
            <CarouselPrevious style={{ left: '4px' }} />
            <CarouselNext style={{ right: '4px' }} />

            <div className="dots">
              {slides.map((url, i) => (
                <span
                  key={`dot-${url}-${i}`}
                  className={`dot ${i === current ? 'active' : ''}`}
                />
              ))}
            </div>
          </>
        )}
      </Carousel>
    </StyledImageCarousel>
  );
};

export default ImageCarousel;
