/*global chrome*/
import { useSelector, useDispatch } from 'react-redux';
import { StyledWrapper } from './StyledWrapper';
import SimpleModal from '../SimpleModal/SimpleModal';
import { Avatar, AvatarGroup } from '@mui/material';
import { shopConnectionConstants } from './constants';
import { getSubdomain } from '../../helper/getSubdomain';

const ConnectShopModal = ({ isConnectShopModal, handleClose }) => {
  const dispatch = useDispatch();
  const link = chrome.runtime.getURL('svg/link.svg');
  const etsyIcon = chrome.runtime.getURL('svg/etsy-icon.svg');
  const id = useSelector((state) => state.user.userData.id);
  const subdomain = getSubdomain();

  const scopes =
    'billing_r email_r favorites_r listings_r profile_r recommend_r shops_r transactions_r listings_w address_w listings_d shops_w transactions_w';

  const handleButtonClick = (e) => {
    if (e.currentTarget.name === 'Connect') {
      var urlState = '';
      urlState = `${id}.${window.location.href}`;
      window.location.href = `https://www.etsy.com/oauth/connect?response_type=code&client_id=uarm508l32t4exk5sjengk1c&redirect_uri=${process.env.REACT_APP_BACKEND_URL_ETSY_REDIRECT_URL}&scope=${scopes}&state=${urlState}&code_challenge=wq9up7xVG7ADNs_yHtTjH2Vm1lL0BU6pVhZpXBeXTpg &code_challenge_method=S256`;
    }
    if (e.currentTarget.name === 'Close') {
      handleClose(false);
    }
  };

  return (
    <SimpleModal
      open={isConnectShopModal}
      handleClose={handleClose}
      connectShop={true}
    >
      <StyledWrapper>
        <div className="inner-wrap">
          <div className="image-wrap">
            <AvatarGroup max={2}>
              <Avatar>
                <img src={link} alt="link" />
              </Avatar>
              <Avatar>
                <img src={etsyIcon} alt="etsy-icon" />
              </Avatar>
            </AvatarGroup>
          </div>
          <div>
            <h5 className="heading">Connect Your Etsy Shop</h5>
            <p className="sub-heading">{shopConnectionConstants.subHeading}</p>
          </div>
          <div className="bottom">
            <button
              className="button-styled"
              name="Connect"
              onClick={handleButtonClick}
            >
              Connect
            </button>
            <button
              className="button-styled close-button-styled"
              name="Close"
              onClick={handleButtonClick}
            >
              Close
            </button>
          </div>
        </div>
      </StyledWrapper>
    </SimpleModal>
  );
};

export default ConnectShopModal;
