export const HeaderTooltipText = (header) => {
  if (header === 'Product') return 'Product Name';
  if (header === 'Shop Name') return 'Shop Name';
  if (header === 'Price') return 'Price';
  if (header === 'Mo. Sales')
    return 'Estimated number of sales in the last month for this listing';
  if (header === 'Mo. Revenue')
    return 'Estimated revenue in the last month for this listing';
  if (header === 'Total Sales') return 'Estimated total sales of this listing';
  if (header === 'Reviews')
    return 'The total number of reviews of this listing';
  if (header === 'Listing Age')
    return 'The number of months since the listing was created';
  if (header === 'Favorites')
    return 'The total number of Favorites this listing has recieved';
  if (header === 'Avg. Reviews')
    return 'The average number of reviews this listing has recieved since being created';
  if (header === 'Views')
    return 'The total number of views in for this listing';
  if (header === 'Category') return 'Category';
  if (header === '# of Tags used')
    return 'The number of tags in the particular listing';
  if (header === 'Auto Renews')
    return 'Whether or not this listing is set to Auto-Renew by the seller';
  if (header === 'Is Customizable')
    return 'Whether or not this listing is set to customizable by the seller';
  if (header === 'Is Personalizable')
    return 'Whether or not this listing is set to personalizable by the seller';
  if (header === 'Description Character Count')
    return 'The amount of characters in the description';
  if (header === 'Has Variations')
    return 'Whether or not this listing has variations';
  if (header === 'Is Supply')
    return 'Whether or not this listing is set as a supply';
  if (header === 'Minimum Processing')
    return 'The minimum processing time for this listing';
  if (header === 'Placement of Listing in Shop')
    return 'This is the placement of the particular listing in a seller shop';
  if (header === 'Shipped From')
    return 'The country of where the listing is shipped from';
  if (header === 'Shop Age')
    return 'The number of months since the shop was created';
  if (header === 'Visibility Score') return 'Visibility score of the product';
  if (header === 'Conversion Rate') return 'Conversion Rate of the product';
  if (header === 'Shop Digital Listings')
    return 'The amount of digital listing this shop has listed';
  if (header === 'Title Character Count')
    return 'The amount of characters in the description';
  if (header === 'When Made')
    return 'When this seller has claimed to make the product listed';
  if (header === 'Who Made')
    return 'Whether the seller claimed to make the product or someone else';
  if (header === 'Total Shop Sales')
    return 'The total number of sales this shop has recieved since being created';
  if (header === 'Keywords') return 'Keyword';
  if (header === 'Volume') return 'Estimated avg. searches per month on Etsy';
  if (header === 'Competition')
    return 'The number of competing listings there are for this keyword';
  // This text of keyword score is not exactly same as the production.
  if (header === 'Keyword Score')
    return 'This score is based on a ratio of estimated search volume vs. the number of competing listings.';
  if (header === 'Trend') return 'Trend';
  return header;
};
