import { PieChart, Pie, Cell, Tooltip } from 'recharts';
import styled from 'styled-components';
import { useSelector } from 'react-redux';
import Decimal from 'decimal.js';
import StyledWrapper from './StyledWrapper';
import ChartDataItem from './ChartDataItem';
import CalculatorDetailTile from './CalculatorDetailTile';
import SmallTileItem from './SmallTileItem';
import { useState } from 'react';

const EtsyCalDisplay = ({ etsyCalState, etsyCalculatorType }) => {
  const [activeIndex, setActiveIndex] = useState(null);
  const [hoverIndex, setHoverIndex] = useState(null);

  const onPieEnter = (_, index) => {
    setHoverIndex(index);
  };

  const onPieLeave = () => {
    setHoverIndex(null);
  };

  const onPieClick = (_, index) => {
    setActiveIndex(index === activeIndex ? null : index); // Toggle selection
  };

  const activeDiscountUnit = useSelector(
    (state) => state.utilities.activeDiscountUnit,
  );
  const activeEtsyAdUnit = useSelector(
    (state) => state.utilities.activeEtsyAdUnit,
  );

  let etsyListingFee = (0.2).toFixed(2);
  let advertisingCost = 0;
  let totalRevenue =
    activeDiscountUnit === 'dollar'
      ? Number(
          (
            etsyCalState.salesPrice +
            etsyCalState.shippingPrice +
            etsyCalState.discounts
          ).toFixed(2),
        )
      : Number(
          (
            etsyCalState.salesPrice +
            etsyCalState.shippingPrice +
            (etsyCalState.discounts / 100) * etsyCalState.salesPrice
          ).toFixed(2),
        );
  totalRevenue = totalRevenue != 0 ? totalRevenue : 0;

  // finalDiscount is a negative number
  const finalDiscount =
    activeDiscountUnit === 'dollar'
      ? Number(etsyCalState.discounts.toFixed(2))
      : Number(
          ((etsyCalState.discounts / 100) * etsyCalState.salesPrice).toFixed(2),
        );

  let totalRev =
    activeDiscountUnit === 'dollar'
      ? etsyCalState.salesPrice +
        etsyCalState.shippingPrice +
        etsyCalState.discounts
      : etsyCalState.salesPrice +
        etsyCalState.shippingPrice +
        0.01 * etsyCalState.discounts * etsyCalState.salesPrice;

  let paymentProcessFee =
    etsyCalState.paymentMethod === 'Paypal' && etsyCalState.salesPrice !== 0
      ? Number(
          (
            0.3 +
            0.029 *
              (etsyCalState.salesPrice +
                etsyCalState.shippingPrice +
                finalDiscount)
          ).toFixed(2),
        )
      : etsyCalState.paymentMethod === 'Etsy Payment' &&
          etsyCalState.salesPrice !== 0
        ? Number(
            (
              0.25 +
              0.03 *
                (etsyCalState.salesPrice +
                  etsyCalState.shippingPrice +
                  finalDiscount)
            ).toFixed(2),
          )
        : 0;
  let transactionFee =
    totalRevenue != 0 ? Number((totalRevenue * 0.065).toFixed(2)) : 0;

  if (etsyCalState.advertising === 'Etsy Ads') {
    advertisingCost =
      activeEtsyAdUnit === 'dollar'
        ? Number(etsyCalState.etsyAds)
        : Number((totalRev * (etsyCalState.etsyAds / 100)).toFixed(2));
  } else if (etsyCalState.advertising === 'Offsite Ads') {
    advertisingCost =
      etsyCalState.offSiteAdCost === '12%'
        ? Number((totalRev * 0.12).toFixed(2))
        : etsyCalState.offSiteAdCost === '15%'
          ? Number((totalRev * 0.15).toFixed(2))
          : 0;
  }

  let totalFees = Number(
    (
      Number(paymentProcessFee) +
      Number(transactionFee) +
      Number(advertisingCost) +
      Number(etsyListingFee)
    ).toFixed(2),
  );

  let costOfGoodsSold = Number(
    (
      parseFloat(etsyCalState.costOfItem) +
      etsyCalState.materialCostItem1 +
      etsyCalState.materialCostItem2 +
      etsyCalState.labourCost +
      etsyCalState.packagingCost
    ).toFixed(2),
  );

  let shippingPlusCogs = Number(costOfGoodsSold) + etsyCalState.shippingCost;
  let totalFeesPlusCost = shippingPlusCogs + totalFees;
  let netProfit = Number((totalRevenue - totalFeesPlusCost).toFixed(2));

  let totalChartValue =
    netProfit + etsyCalState.shippingCost + costOfGoodsSold + totalFees;
  let netProfitPer =
    totalChartValue == 0
      ? 0
      : Number(((netProfit / totalChartValue) * 100).toFixed(2));
  let shippingCostPer =
    totalChartValue == 0
      ? 0
      : Number(
          ((etsyCalState.shippingCost / totalChartValue) * 100).toFixed(2),
        );
  let costOfGoodsSoldPer =
    totalChartValue == 0
      ? 0
      : Number(((costOfGoodsSold / totalChartValue) * 100).toFixed(2));
  let totalFeesPer =
    totalChartValue == 0
      ? 0
      : Number(((totalFees / totalChartValue) * 100).toFixed(2));

  let netProfitMargin =
    totalRevenue == 0
      ? 0
      : Number(((netProfit / totalRevenue) * 100).toFixed(2));

  // Data Object
  const tilesData = {
    revenue: {
      heading: 'Revenue',
      tilesData: [
        { heading: 'Sales', value: etsyCalState.salesPrice },
        { heading: 'Shipping Price', value: etsyCalState.shippingPrice },
        { heading: 'Discount', value: etsyCalState.discounts },
      ],
      total: totalRevenue,
    },
    fees: {
      heading: 'Fees',
      tilesData: [
        { heading: 'Etsy Listing Fees', value: etsyListingFee },
        { heading: 'Transaction Fees', value: transactionFee },
        { heading: 'Payment Process Fee', value: paymentProcessFee },
        { heading: 'Advertising Cost', value: advertisingCost },
      ],
      total: totalFees,
    },
    costs: {
      heading: 'Costs',
      tilesData: [
        { heading: 'Cost of Goods Sold', value: costOfGoodsSold },
        { heading: 'Shipping Cost', value: etsyCalState.shippingCost },
      ],
      total: shippingPlusCogs,
    },
  };

  const noChartData =
    netProfit == -0.2 &&
    etsyCalState.shippingCost == 0 &&
    costOfGoodsSold == 0 &&
    etsyListingFee == 0.2 &&
    totalFees == 0.2
      ? true
      : false;

  const sumTotalOfChartStr = new Decimal(etsyCalState.shippingCost)
    .plus(costOfGoodsSold)
    .plus(totalFees)
    .plus(netProfit)
    .toString();
  const sumTotalOfChart = Number(sumTotalOfChartStr);

  // const donutChartOptions = {
  //   colors:
  //     noChartData || sumTotalOfChart === 0
  //       ? ['#f2f2f2', '#E6E6E6', '#f2f2f2', '#E6E6E6']
  //       : ['#2E8AE5', '#55A4F2', '#89C2FB', '#CCE6FF'],
  //   series:
  //     noChartData || sumTotalOfChart === 0
  //       ? [10, 20, 30, 40]
  //       : [netProfit, etsyCalState.shippingCost, costOfGoodsSold, totalFees],
  //   labels: ['Net Profit', 'Shipping Cost', 'COGS', 'Fees'],
  //   dataLabels: {
  //     enabled: false,
  //   },
  //   legend: {
  //     show: false,
  //   },
  // };
  const chartData =
    noChartData || sumTotalOfChart === 0
      ? [
          { name: 'Net Profit', value: 10, fill: '#f2f2f2' },
          { name: 'Shipping Cost', value: 20, fill: '#E6E6E6' },
          { name: 'COGS', value: 30, fill: '#f2f2f2' },
          { name: 'Fees', value: 40, fill: '#E6E6E6' },
        ]
      : [
          { name: 'Net Profit', value: netProfit, fill: '#2E8AE5' },
          {
            name: 'Shipping Cost',
            value: etsyCalState?.shippingCost,
            fill: '#55A4F2',
          },
          { name: 'COGS', value: costOfGoodsSold, fill: '#89C2FB' },
          { name: 'Fees', value: totalFees, fill: '#CCE6FF' },
        ];

  const filteredData = chartData.filter((item) => item.value > 0);

  const COLORS =
    noChartData || sumTotalOfChart === 0
      ? ['#f2f2f2', '#E6E6E6', '#f2f2f2', '#E6E6E6']
      : ['#2E8AE5', '#55A4F2', '#89C2FB', '#CCE6FF'];

  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      const data = payload[0];
      const name = data.name || data.payload.name;
      const value = data.value || data.payload.value;
      const fill = data.fill || data.payload.fill || data.color;
      return (
        <TooltipContainer
          style={{ backgroundColor: `${fill}`, border: 'none' }}
        >
          <span style={{ color: '#fff' }}>
            {name}: {value}
          </span>
        </TooltipContainer>
      );
    }
    return null;
  };
  const TooltipContainer = styled.div`
    background: white;
    padding: 6px 10px;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    display: flex;
    align-items: center;
    box-shadow: 0px 2px 8px rgba(0, 0, 0, 0.1);
    font-size: 12px;
  `;

  return (
    <StyledWrapper>
      <div className="display-heading">Summary</div>
      <div className="chart-data-container">
        <div className="chart">
          {/* <Chart
            options={donutChartOptions}
            series={donutChartOptions.series}
            type="donut"
            height="140"
            width="140"
          /> */}

          <PieChart width={130} height={130} style={{ outline: 'none' }}>
            <Pie
              data={filteredData}
              dataKey="value"
              nameKey="name"
              cx="50%"
              cy="50%"
              innerRadius={45} // Makes it a donut
              outerRadius={60}
              fill="#8884d8"
              paddingAngle={5}
              data-label
              onMouseEnter={onPieEnter}
              onMouseLeave={onPieLeave}
              onClick={onPieClick}
              tabIndex="-1"
              style={{ outline: 'none' }}
            >
              {filteredData.map((entry, index) => (
                <Cell
                  key={`cell-${index}`}
                  fill={entry.fill}
                  opacity={
                    hoverIndex === index
                      ? 0.7 // Hover effect
                      : activeIndex === index
                        ? 0.7 // Clicked effect (if no hover)
                        : 1
                  }
                  stroke={
                    hoverIndex === index || activeIndex === index
                      ? 'grey'
                      : 'none'
                  }
                  strokeWidth={
                    hoverIndex === index || activeIndex === index ? 2 : 0
                  }
                />
              ))}
            </Pie>
            <Tooltip content={<CustomTooltip />} />
          </PieChart>
        </div>
        <div className="chart-data">
          <ChartDataItem
            displayName="Net Profit"
            displayData={`$${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(netProfit.toFixed(2))
            } (${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(netProfitPer.toFixed(2))
            }%)`}
            dotColor={
              noChartData || sumTotalOfChart === 0 ? '#E6E6E6' : '#2E8AE5'
            }
          />
          <ChartDataItem
            displayName="Shipping Cost"
            displayData={`$${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(etsyCalState.shippingCost.toFixed(2))
            } (${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(shippingCostPer.toFixed(2))
            }%)`}
            dotColor={
              noChartData || sumTotalOfChart === 0 ? '#f2f2f2' : '#55A4F2'
            }
          />
          <ChartDataItem
            displayName="COGS"
            displayData={`$${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(costOfGoodsSold.toFixed(2))
            } (${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(costOfGoodsSoldPer.toFixed(2))
            }%)`}
          />
          <ChartDataItem
            displayName="Fees"
            displayData={`$${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(totalFees.toFixed(2))
            } (${
              noChartData || sumTotalOfChart === 0
                ? 0
                : Number(totalFeesPer.toFixed(2))
            }%)`}
            dotColor={
              noChartData || sumTotalOfChart === 0 ? '#E6E6E6' : '#CCE6FF'
            }
          />
        </div>
      </div>
      <div className="calculator-details">
        <CalculatorDetailTile tileValues={tilesData.revenue} />
        <CalculatorDetailTile tileValues={tilesData.fees} />
        <CalculatorDetailTile tileValues={tilesData.costs} />
      </div>
      <div className="calculator-details-footer">
        <SmallTileItem
          displayName="Total Revenue"
          displayData={totalRevenue != 0 ? totalRevenue.toFixed(2) : 0}
        />
        <SmallTileItem
          displayName="Total Fees + Costs"
          displayData={
            totalFeesPlusCost != 0 ? totalFeesPlusCost.toFixed(2) : 0
          }
        />
        <SmallTileItem
          displayName="Net Profit"
          displayData={netProfit != 0 ? netProfit.toFixed(2) : 0}
        />
        <SmallTileItem
          displayName="Net Profit Margin"
          displayData={netProfitMargin != 0 ? netProfitMargin.toFixed(2) : 0}
        />
      </div>
    </StyledWrapper>
  );
};

export default EtsyCalDisplay;
