import React from 'react';
import Modal from '@mui/material/Modal';
import { Box } from '@mui/material';
// import { useSelector } from 'react-redux';

const SimpleModal = ({
  children,
  open,
  handleClose,
  styleOverridesObj,
  connectShop,
  tagsModal,
  // animateFromTop,
}) => {
  // const isSidebarExpanded = useSelector((state) => state.sidebar.isExpanded);

  let style = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    // left: isSidebarExpanded ? 'calc(50% + 128px)' : 'calc(50% + 38px)',
    width:
      connectShop === true ? '480px' : tagsModal === true ? '990px' : '80%',
    transform: 'translate(-50%, -50%)',
    bgcolor: 'background.paper',
    boxShadow: 24,
    padding: '16px',
    outline: 'none',
    borderRadius: '12px',
    zIndex: '99999999',
    overflowX: 'hidden',
  };

  if (styleOverridesObj) {
    style = { ...style, ...styleOverridesObj };
  }

  return (
    <Modal
      open={open}
      onClose={handleClose}
      sx={{ position: 'fixed', zIndex: '2101' }}
    >
      <Box sx={style}>{children}</Box>
    </Modal>
  );
};

export default SimpleModal;
