import * as amplitude from '@amplitude/analytics-browser';
import InputContainer from './InputContainer';
import StyledWrapper from './StyledWrapper';
import { useRef } from 'react';

const SELECT_AD_OPTIONS = ['None', 'Etsy Ads', 'Offsite Ads'];
const SELECT_PAYMENT_OPTIONS = ['Paypal', 'Etsy Payment'];
const OFFSITE_AD_OPTIONS = ['12%', '15%'];

const EtsyCalForm = ({
  activeCalculatorType,
  etsyCalState,
  setEtsyCalState,
}) => {
  const formRef = useRef();
  const handleCalculateClick = () => {
    amplitude.track('Calculator - extension');
  };

  return (
    <StyledWrapper>
      <div className="form-scroll">
        <div className="form-block">
          <div className="sub-heading">Revenue</div>
          <InputContainer
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
            inputBehaviour="number"
            displayText="Listed Price"
            name="salesPrice"
            value={etsyCalState.salesPrice}
          />
          <InputContainer
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
            inputBehaviour="number"
            displayText="Shipping Price"
            name="shippingPrice"
            value={etsyCalState.shippingPrice}
          />
          <InputContainer
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
            inputBehaviour="number"
            displayText="Discounts"
            name="discounts"
            value={etsyCalState.discounts}
            withPercent={true}
          />
        </div>
        <div className="form-block">
          <div className="sub-heading">Costs</div>
          <InputContainer
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
            inputBehaviour="number"
            displayText="Cost of Item"
            name="costOfItem"
            value={etsyCalState.costOfItem}
          />

          {activeCalculatorType === 'Advanced' && (
            <InputContainer
              etsyCalState={etsyCalState}
              setEtsyCalState={setEtsyCalState}
              inputBehaviour="number"
              displayText="Material Cost of Item 1"
              name="materialCostItem1"
              value={etsyCalState.materialCostItem1}
            />
          )}
          {activeCalculatorType === 'Advanced' && (
            <InputContainer
              etsyCalState={etsyCalState}
              setEtsyCalState={setEtsyCalState}
              inputBehaviour="number"
              displayText="Material Cost of Item 2"
              name="materialCostItem2"
              value={etsyCalState.materialCostItem2}
            />
          )}
          {activeCalculatorType === 'Advanced' && (
            <InputContainer
              etsyCalState={etsyCalState}
              setEtsyCalState={setEtsyCalState}
              inputBehaviour="number"
              displayText="Labor Cost of Item"
              name="labourCost"
              value={etsyCalState.labourCost}
            />
          )}
          {activeCalculatorType === 'Advanced' && (
            <InputContainer
              etsyCalState={etsyCalState}
              setEtsyCalState={setEtsyCalState}
              inputBehaviour="number"
              displayText="Packaging Cost of Order"
              name="packagingCost"
              value={etsyCalState.packagingCost}
            />
          )}

          <InputContainer
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
            inputBehaviour="number"
            displayText="Shipping Cost for Order"
            name="shippingCost"
            value={etsyCalState.shippingCost}
          />
        </div>
        <div className="form-block">
          <div className="sub-heading">Advertising</div>
          <InputContainer
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
            displayText="Advertising"
            inputBehaviour="select"
            selectOptions={SELECT_AD_OPTIONS}
          />

          {etsyCalState.advertising === 'Etsy Ads' ? (
            <InputContainer
              etsyCalState={etsyCalState}
              setEtsyCalState={setEtsyCalState}
              displayText="Etsy Ads-Est. ACoS"
              inputBehaviour="number"
              withPercent={true}
              name="etsyAds"
              value={etsyCalState.etsyAds}
            />
          ) : etsyCalState.advertising === 'Offsite Ads' ? (
            <InputContainer
              etsyCalState={etsyCalState}
              setEtsyCalState={setEtsyCalState}
              displayText="Offsite Ads"
              inputBehaviour="select"
              selectOptions={OFFSITE_AD_OPTIONS}
            />
          ) : null}
        </div>
        <div className="form-block" ref={formRef}>
          <div className="sub-heading">Miscellaneous</div>
          <InputContainer
            formRef={formRef}
            etsyCalState={etsyCalState}
            setEtsyCalState={setEtsyCalState}
            displayText="Payment Method"
            inputBehaviour="select"
            selectOptions={SELECT_PAYMENT_OPTIONS}
          />
        </div>
      </div>
      <button className="ec-calculate-button" onClick={handleCalculateClick}>
        Calculate
      </button>
    </StyledWrapper>
  );
};

export default EtsyCalForm;
