import React from 'react';
import { toast } from 'sonner';
import FavKeywordUpdateToast from './FavKeywordUpdateToast';

const favKeywordPopup = (row, folderDetailsArray, action, errorMessage) => {
  toast.dismiss(); // Dismiss existing toasts before showing a new ones

  toast.custom(
    (id) => (
      <FavKeywordUpdateToast
        row={row}
        folderDetailsArray={folderDetailsArray}
        action={action}
        errorMessage={errorMessage}
        onClose={() => toast.dismiss(id)}
      />
    ),
    { duration: 5000, unstyled: true, position: 'bottom-right' },
  );
};

export default favKeywordPopup;
