import { PLANS } from '../../constants/pricingPage';

// `current_plan` is the Stripe product name verbatim, and the backend appends
// " Trial" while a subscription is trialing — so match on the stripped name.
const stripTrial = (plan) => (plan || '').replace(/\s+Trial$/, '');

const TIERS = {
  [PLANS.HOBBY]: 'hobby',
  [PLANS.GROWTH_MONTHLY]: 'growth_monthly',
  [PLANS.GROWTH_ANUALLY]: 'growth_annual',
  [PLANS.BUSINESS_MONTHLY]: 'business_monthly',
  [PLANS.BUSINESS_ANUALLY]: 'business_annual',
};

/**
 * What the footer prints. The raw `current_plan` is the Stripe product name and
 * carries whatever the environment and subscription state added to it — the
 * " Test" suffix that marks dev and staging, and " Trial" while trialing — so it
 * is shown verbatim rather than normalised to a canonical tier name, which is
 * how the old rail did it and what makes a staging session recognisable.
 *
 * `hobby` is the one exception: it is a sentinel, not a product name, so it gets
 * a display form instead of being printed lowercase.
 */
const planDisplayName = (currentPlan, tier) => {
  if (!currentPlan) return tier === 'hobby' ? 'Hobby' : '';
  return currentPlan === PLANS.HOBBY ? 'Hobby' : currentPlan;
};

/**
 * Maps the raw plan name onto the sidebar's plan model.
 *
 * Two upgrade surfaces: the rail pill (Hobby only) and the profile-menu row,
 * whose copy is plan-specific. An unrecognised plan (legacy Pro, a new Stripe
 * product) shows its raw label and no upgrade CTA — a wrong CTA is worse than
 * none.
 */
export const resolvePlan = (currentPlan, { onUpgrade }) => {
  const tier = TIERS[stripTrial(currentPlan)] || 'unknown';

  const upgrade = {
    hobby: { label: 'Upgrade plan', showPill: true, onUpgrade },
    growth_monthly: { label: 'Upgrade to Business', onUpgrade },
    growth_annual: { label: 'Upgrade to Business', onUpgrade },
    business_monthly: {
      label: 'Upgrade to annual',
      badge: 'Save 33%',
      onUpgrade,
    },
    business_annual: null,
    unknown: null,
  }[tier];

  return {
    tier,
    label: planDisplayName(currentPlan, tier),
    upgrade,
  };
};
