/*global chrome*/
import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Rating, Skeleton } from '@mui/material';
import { StyledWrapper } from './StyledWrapper';
import { decodeHTMLEntities } from '../../utils/decodeHTMLText';
import * as amplitude from '@amplitude/analytics-browser';
import {
  manageFavItemsInFolders,
  fetchFoldersContainingPL,
  setListingFolderMgmtModalStatus,
  setManagementModalStatus,
  setShopFolderMgmtModalStatus,
  toggleListingsWatchlistModal,
  toggleShopsWatchlistModal,
  unfavouritePLFromFav,
} from '../../store/slices/favoritesSlice';
import {
  setIsListingFav,
  setIsShopFav,
  setIsNewFavFolderModal,
  updateExtSearchDataIsfav,
} from '../../store/slices/utilitySlice';
import favPopup from '../FavUpdateToast/Listings/FavPopup';
import favShopPopup from '../FavUpdateToast/Shops/FavShopPopup';
import NewFavFolderModal from '../NewFavFolderModal';
import { ListingsWatchlistModal, ShopsWatchlistModal } from '../WatchlistModal';
import { shouldShowShopLimitTooltip } from '../../utils/favoriteLimitHelpers';
import HeaderTooltip from '../CustomToolTip/HeaderTooltip';
import {
  changeFeaturePage,
  changeIframeUrl,
  toggleRightPane,
} from '../../store/slices/sidebarSlice';
import { MAIN_MENU } from '../../constants/menuList';
import { updateFavoriteCount } from '../../store/slices/userSlice';
import ImageCarousel from '../ImageCarousel';

const ImageAndDetails = ({ activeButton, details, loading }) => {
  const shareIcon = chrome.runtime.getURL('svg/share.svg');
  const etsyLogo = chrome.runtime.getURL('svg/etsy-white.svg');
  const favFilled = chrome.runtime.getURL('svg/fav-filled.svg');
  const favUnfilled = chrome.runtime.getURL('svg/fav-unfilled.svg');

  const dispatch = useDispatch();
  const { listingDetailsData, shopDetailsData } = useSelector(
    (state) => state.utilities,
  );
  const { userData, favoriteLimits } = useSelector((state) => state.user);

  const {
    listingsFolderData,
    shopsFolderData,
    listingsDefaultFolderData,
    shopsDefaultFolderData,
    isListingsWatchlistModal,
    isShopsWatchlistModal,
  } = useSelector((state) => state.watchlist);
  const { isNewFavFolderModal } = useSelector((state) => state.utilities);
  const isListingFolderManagement = useSelector(
    (state) => state.watchlist.folderManagementModalStatus.listing,
  );
  const isShopFolderManagement = useSelector(
    (state) => state.watchlist.folderManagementModalStatus.shop,
  );

  const listingsDefaultFolderIds = useMemo(
    () => listingsDefaultFolderData.map((folder) => folder.id),
    [listingsDefaultFolderData],
  );

  const shopsDefaultFolderIds = useMemo(
    () => shopsDefaultFolderData.map((folder) => folder.id),
    [shopsDefaultFolderData],
  );

  const listingsDefaultFolderDetails = useMemo(
    () =>
      listingsDefaultFolderData.map((folder) => ({
        name: folder.name,
        id: folder.id,
      })),
    [listingsDefaultFolderData],
  );

  const shopsDefaultFolderDetails = useMemo(
    () =>
      shopsDefaultFolderData.map((folder) => ({
        name: folder.name,
        id: folder.id,
      })),
    [shopsDefaultFolderData],
  );

  const shouldShowShopTooltip =
    !shopDetailsData?.isFav &&
    shouldShowShopLimitTooltip(userData, favoriteLimits);

  const trackFavoritesEvent = (
    eventName,
    itemType = 'listing',
    additionalProps = {},
  ) => {
    amplitude.track(eventName, {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      source_type: 'listing_details',
      item_type: itemType,
      ...additionalProps,
    });
  };

  const handleUpgradeClick = () => {
    dispatch(toggleRightPane(false));
    dispatch(changeFeaturePage(MAIN_MENU.PRICING));
    dispatch(changeIframeUrl('pricing'));
  };

  const handleListingClickFavourites = async (e) => {
    e.stopPropagation();

    if (listingDetailsData?.isFav) {
      const response = await dispatch(
        fetchFoldersContainingPL({
          itemIdsArray: [listingDetailsData?.listingId],
          type: 'listing',
        }),
      ).unwrap();

      const folderIdsFromResponse =
        response?.data?.items?.flatMap((item) => item.folder_ids) || [];

      const folderDetails = listingsFolderData
        .filter((folder) => folderIdsFromResponse.includes(folder.id))
        .map((folder) => ({
          name: folder.name,
          id: folder.id,
        }));

      await dispatch(
        unfavouritePLFromFav({
          itemId: listingDetailsData?.listingId,
          type: 'listing',
        }),
      ).unwrap();

      dispatch(setIsListingFav(false));
      dispatch(
        updateExtSearchDataIsfav({
          listingId: listingDetailsData.listingId,
          isFavBool: false,
        }),
      );

      setTimeout(() => {
        favPopup(listingDetailsData, folderDetails, 'undo', 'ImageAndDetails');
      }, 300);

      trackFavoritesEvent('Favorites_Remove_Click');
    } else {
      if (listingsFolderData.length === 0) {
        trackFavoritesEvent('Add_To_Favorites_Click', 'listing', {
          is_first_favorites_action_of_day: true,
        });
        dispatch(setIsNewFavFolderModal(true));
      } else if (
        isListingFolderManagement ||
        listingsDefaultFolderIds.length === 0
      ) {
        dispatch(toggleListingsWatchlistModal(true));
        if (isListingFolderManagement) {
          trackFavoritesEvent('Add_To_Favorites_Click', 'listing', {
            is_first_favorites_action_of_day: true,
          });
          dispatch(setManagementModalStatus({ itemType: 'listing' })); //BE update
          dispatch(setListingFolderMgmtModalStatus(false)); //local update
        }
      } else {
        trackFavoritesEvent('Add_To_Favorites_Click', 'listing', {
          target_folders_count: listingsDefaultFolderIds.length,
          is_first_favorites_action_of_day: false,
        });
        dispatch(
          manageFavItemsInFolders({
            itemIdsArray: [listingDetailsData.listingId],
            type: 'listing',
            folderIdsArray: listingsDefaultFolderIds,
          }),
        ).unwrap();

        dispatch(setIsListingFav(true));
        dispatch(
          updateExtSearchDataIsfav({
            listingId: listingDetailsData.listingId,
            isFavBool: true,
          }),
        );

        setTimeout(() => {
          favPopup(
            listingDetailsData,
            listingsDefaultFolderDetails,
            'add',
            'ImageAndDetails',
          );
        }, 300);
      }
    }
  };

  const handleShopFavoriteClick = async (e) => {
    e.stopPropagation();

    if (shopDetailsData?.isFav) {
      const response = await dispatch(
        fetchFoldersContainingPL({
          itemIdsArray: [shopDetailsData?.shopId],
          type: 'shop',
        }),
      ).unwrap();

      const folderIdsFromResponse =
        response?.data?.items?.flatMap((item) => item.folder_ids) || [];

      const folderDetails = shopsFolderData
        .filter((folder) => folderIdsFromResponse.includes(folder.id))
        .map((folder) => ({
          name: folder.name,
          id: folder.id,
        }));

      await dispatch(
        unfavouritePLFromFav({
          itemId: shopDetailsData?.shopId,
          type: 'shop',
        }),
      ).unwrap();

      dispatch(setIsShopFav(false));

      setTimeout(() => {
        favShopPopup(shopDetailsData, folderDetails, 'undo', 'ImageAndDetails');
      }, 300);

      trackFavoritesEvent('Favorites_Remove_Click', 'shop');

      dispatch(updateFavoriteCount({ type: 'shopCount', amount: -1 }));
    } else {
      if (shopsFolderData.length === 0) {
        trackFavoritesEvent('Add_To_Favorites_Click', 'shop', {
          is_first_favorites_action_of_day: true,
        });
        dispatch(setIsNewFavFolderModal(true));
      } else if (isShopFolderManagement || shopsDefaultFolderIds.length === 0) {
        dispatch(toggleShopsWatchlistModal(true));
        if (isShopFolderManagement) {
          trackFavoritesEvent('Add_To_Favorites_Click', 'shop', {
            is_first_favorites_action_of_day: true,
          });
          dispatch(setManagementModalStatus({ itemType: 'shop' })); //BE update
          dispatch(setShopFolderMgmtModalStatus(false)); //local update
        }
      } else {
        trackFavoritesEvent('Add_To_Favorites_Click', 'shop', {
          target_folders_count: shopsDefaultFolderIds.length,
          is_first_favorites_action_of_day: false,
        });
        dispatch(
          manageFavItemsInFolders({
            itemIdsArray: [shopDetailsData.shopId],
            type: 'shop',
            folderIdsArray: shopsDefaultFolderIds,
          }),
        ).unwrap();

        dispatch(setIsShopFav(true));

        setTimeout(() => {
          favShopPopup(
            shopDetailsData,
            shopsDefaultFolderDetails,
            'add',
            'ImageAndDetails',
          );
        }, 300);

        dispatch(updateFavoriteCount({ type: 'shopCount', amount: 1 }));
      }
    }
  };

  return loading ? (
    <StyledWrapper>
      <div className="ImageAndDetailsWrapper">
        <div className="ImageWrapper">
          <Skeleton
            variant="rounded"
            width={148}
            height={148}
            animation="wave"
          />
        </div>
        <div className="DetailsHeading">
          <Skeleton
            variant="rectangular"
            animation="wave"
            width={240}
            height={50}
          />
          <div className="LocationAndRateWrap skeleton">
            <div className="subWrap">
              <Skeleton
                variant="text"
                animation="wave"
                width={50}
                sx={{ fontSize: '1.5rem' }}
              />
              <Skeleton
                variant="text"
                animation="wave"
                width={70}
                sx={{ fontSize: '1.2rem' }}
              />
            </div>
            <div className="subWrap">
              <Skeleton
                variant="text"
                animation="wave"
                width={50}
                sx={{ fontSize: '1.5rem' }}
              />
              <Skeleton
                variant="text"
                animation="wave"
                width={90}
                sx={{ fontSize: '1.2rem' }}
              />
            </div>
          </div>
        </div>
      </div>
    </StyledWrapper>
  ) : (
    <StyledWrapper $hideDetails={userData?.hide_details}>
      <div className="ImageAndDetailsWrapper">
        <div className="ImageWrapper">
          <ImageCarousel details={details} />
        </div>
        <div className="DetailsHeading">
          <div className="HeadingAndSvgWrap">
            {activeButton === 'Listing Details' && (
              <h5 className="Heading">
                <span className="heading-text">
                  {decodeHTMLEntities(details.heading)}
                </span>
              </h5>
            )}
            {activeButton === 'Shop Details' && (
              <h5 className="shop-details-heading">
                <span className="heading-text">
                  {decodeHTMLEntities(details.heading)}
                </span>
                {/* <span
                  onClick={() => window.open(details.url, '_blank')}
                  className="svgSpan"
                >
                  <img src={shareIcon} alt="share-icon" />
                </span> */}
              </h5>
            )}
          </div>
          {/* {activeButton === 'Shop Details' && (
            <p className="DetailsSubHeading shop-subheading">
              {details.subHeading}
            </p>
          )} */}
          <div className="LocationAndRateWrap">
            {activeButton === 'Shop Details' && (
              <div className="subWrap">
                <p className="DetailsSubHeading">Location</p>
                <p className="LocationAndRateValues">{details.location}</p>
              </div>
            )}
            {activeButton === 'Listing Details' && (
              <div className="subWrap">
                <p className="DetailsSubHeading">Price</p>
                <p className="DetailsSubHeading PriceColor">
                  {details.currencySymbol}
                  {Number(details.price).toLocaleString('en-US')}
                </p>
              </div>
            )}
            {activeButton === 'Shop Details' && (
              <div className="subWrap">
                <p className="DetailsSubHeading">Shop Rating</p>
                <Rating
                  className="RattingStyled"
                  value={details.rate}
                  readOnly
                />
              </div>
            )}
            {activeButton === 'Listing Details' && (
              <div className="subWrap">
                <p className="DetailsSubHeading">Shop</p>
                <p className="DetailsSubHeading ShopValue">{details.shop}</p>
              </div>
            )}
          </div>
          <div className="btns-wrapper">
            {activeButton === 'Shop Details' && shouldShowShopTooltip ? (
              <HeaderTooltip
                PopperProps={{
                  style: {
                    zIndex: 99999999,
                  },
                }}
                title={
                  <>
                    <i>Upgrade to favorite more items.</i>
                    <br />
                    <i>Click to upgrade</i>
                  </>
                }
                placement="top"
              >
                <button className="btns" onClick={handleUpgradeClick}>
                  <img src={favUnfilled} alt="Favorite Unfilled" />
                  <span>Save to favorites</span>
                </button>
              </HeaderTooltip>
            ) : (
              <button
                className="btns"
                onClick={
                  activeButton === 'Listing Details'
                    ? handleListingClickFavourites
                    : activeButton === 'Shop Details'
                      ? handleShopFavoriteClick
                      : undefined
                }
              >
                {(
                  activeButton === 'Listing Details'
                    ? listingDetailsData?.isFav
                    : shopDetailsData?.isFav
                ) ? (
                  <img src={favFilled} alt="Favorite Filled" />
                ) : (
                  <img src={favUnfilled} alt="Favorite Unfilled" />
                )}
                <span>
                  {(
                    activeButton === 'Listing Details'
                      ? listingDetailsData?.isFav
                      : shopDetailsData?.isFav
                  )
                    ? 'Saved to favorites'
                    : 'Save to favorites'}
                </span>
              </button>
            )}
            <button
              className="btns"
              onClick={() => {
                amplitude.track('View_On_Etsy_Click', {
                  product_type: 'extension',
                  feature_type: 'etsy',
                  etsy_type:
                    window.location.pathname === '/'
                      ? 'home_page'
                      : window.location.href.includes('/shop/')
                        ? 'shop_page'
                        : window.location.href.includes('/listing/')
                          ? 'listing_page'
                          : window.location.href.includes('/search?q=')
                            ? 'search_results'
                            : 'other_page',
                  item_type:
                    activeButton === 'Listing Details' ? 'listing' : 'shop',
                  source_type: 'listing_details',
                });
                window.open(details.url, '_blank');
              }}
            >
              <img src={etsyLogo} alt="Etsy Logo" />
              <span>View on Etsy</span>
              <img src={shareIcon} alt="Etsy Logo" />
            </button>
          </div>
        </div>
      </div>

      {isNewFavFolderModal && (
        <NewFavFolderModal
          row={
            activeButton === 'Listing Details'
              ? listingDetailsData
              : shopDetailsData
          }
          context="ImageAndDetails"
        />
      )}

      {isListingsWatchlistModal && (
        <ListingsWatchlistModal
          row={listingDetailsData}
          context="ImageAndDetails"
        />
      )}

      {isShopsWatchlistModal && (
        <ShopsWatchlistModal row={shopDetailsData} context="ImageAndDetails" />
      )}
    </StyledWrapper>
  );
};

export default ImageAndDetails;
