function renderBar(bar, ctx) {
  const { uniqueLabels, adCount, state, onToggleLabel, onToggleAds, onReset } =
    ctx;
  bar.innerHTML = '';

  const active = getActiveLabels(state);
  const hideAds = !!state.hideAds;
  const activeServer = getActiveServerFilters();
  const staticFilters = getStaticServerFilters();
  // Always-visible filters own their label: any DOM badge wording variant
  // ("Best seller", "Bestseller") is folded into the canonical chip so the
  // filter can never render twice, or under a label that shifts between
  // searches.
  const staticLabels = staticFilters.map((sf) => sf.canonical);
  const isStaticLabel = (l) => staticFilters.some((sf) => sf.matches(l));
  // Ensure each active server filter shows up as a chip even if no matching
  // DOM badge is currently rendered (e.g. immediately after navigation, or
  // when Etsy's filtered grid hasn't hydrated yet). Always-visible filters
  // are already covered by staticLabels.
  const serverFallbackLabels = activeServer
    .filter((sf) => !sf.alwaysVisible && !uniqueLabels.some((l) => sf.matches(l)))
    .map((sf) => sf.canonical);
  const anyFilter = active.size > 0 || hideAds || activeServer.length > 0;
  const dynamicLabels = Array.from(
    new Set([
      ...uniqueLabels,
      ...Array.from(active),
      ...serverFallbackLabels,
    ]),
  )
    .filter((l) => !isStaticLabel(l))
    .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
  // Static chips are pinned to the front so they hold a stable position
  // instead of drifting alphabetically as page badges come and go.
  const renderedLabels = [...staticLabels, ...dynamicLabels];

  if (renderedLabels.length > 0) {
    const title = document.createElement('span');
    title.className = 'eb-title';

    const icon = document.createElement('img');
    icon.className = 'eb-title__icon';
    icon.alt = 'EverBee';
    icon.src = chrome.runtime.getURL('svg/everbee-logo-sm.svg');

    const titleText = document.createElement('span');
    titleText.textContent =
      active.size > 0 || activeServer.length > 0 ? 'Showing only' : 'Show only';

    title.appendChild(icon);
    title.appendChild(titleText);
    bar.appendChild(title);

    renderedLabels.forEach((label) => {
      const sf = getServerFilterForLabel(label);
      const on = sf ? isServerFilterActive(label) : active.has(label);
      const pill = document.createElement('button');
      pill.type = 'button';
      pill.className = 'eb-pill';
      pill.setAttribute('data-on', on ? 'true' : 'false');
      pill.setAttribute('aria-pressed', on ? 'true' : 'false');
      pill.setAttribute('data-label', label);

      const dot = document.createElement('span');
      dot.className = 'eb-dot';

      const text = document.createElement('span');
      text.className = 'eb-label';
      text.textContent = label;

      pill.appendChild(dot);
      pill.appendChild(text);
      pill.addEventListener('click', () => onToggleLabel(label));
      bar.appendChild(pill);
    });
  }

  if (adCount > 0) {
    if (renderedLabels.length > 0) {
      const div = document.createElement('span');
      div.className = 'eb-divider';
      bar.appendChild(div);
    }

    const sw = document.createElement('button');
    sw.type = 'button';
    sw.className = 'eb-switch';
    sw.setAttribute('role', 'switch');
    sw.setAttribute('aria-checked', hideAds ? 'true' : 'false');
    sw.setAttribute('data-on', hideAds ? 'true' : 'false');
    sw.setAttribute(
      'title',
      hideAds
        ? `Currently hiding ${adCount} sponsored listing${adCount === 1 ? '' : 's'}`
        : `${adCount} sponsored listing${adCount === 1 ? '' : 's'} on this page`,
    );

    const label = document.createElement('span');
    label.className = 'eb-switch__label';
    label.textContent = 'Hide ads';

    const count = document.createElement('span');
    count.className = 'eb-switch__count';
    count.textContent = `(${adCount})`;

    const track = document.createElement('span');
    track.className = 'eb-switch__track';
    const thumb = document.createElement('span');
    thumb.className = 'eb-switch__thumb';
    track.appendChild(thumb);

    sw.appendChild(label);
    sw.appendChild(count);
    sw.appendChild(track);
    sw.addEventListener('click', onToggleAds);
    bar.appendChild(sw);
  }

  if (anyFilter) {
    const reset = document.createElement('button');
    reset.type = 'button';
    reset.className = 'eb-reset';
    reset.textContent = 'Show all';
    reset.addEventListener('click', onReset);
    bar.appendChild(reset);
  }
}

// ---------- Persistence ------------------------------------------------------

const DEFAULT_STATE = { selected: {}, hideAds: false };

function coerceState(raw) {
  if (!raw || typeof raw !== 'object') return { ...DEFAULT_STATE };
  const rawSelected =
    raw.selected && typeof raw.selected === 'object' ? raw.selected : {};
  // Strip out any persisted entries for labels that are now handled via URL
  // query params (Bestseller / Etsy's Pick). Otherwise stale state from
  // before this change would continue to hide cards client-side on top of
  // the server-side filter.
  const selected = {};
  for (const key in rawSelected) {
    if (rawSelected[key] === true && !getServerFilterForLabel(key)) {
      selected[key] = true;
    }
  }
  return {
    selected,
    hideAds: raw.hideAds === true,
  };
}

async function loadState() {
  try {
    if (!chrome?.storage?.session) return { ...DEFAULT_STATE };
    const r = await chrome.storage.session.get(CONFIG.storageKey);
    return coerceState(r?.[CONFIG.storageKey]);
  } catch (_) {
    return { ...DEFAULT_STATE };
  }
}

function saveState(state) {
  try {
    if (!chrome?.storage?.session) return;
    chrome.storage.session.set({ [CONFIG.storageKey]: state });
  } catch (_) {
    /* silent */
  }
}

// ---------- Orchestration ----------------------------------------------------

/**
 * Locate the container to mount above. Prefers a container that actually holds
 * listing cards. Falls back to the first matching container even when it holds
 * none, so a zero-result page (e.g. a search + `is_best_seller=true` combo Etsy
 * has nothing for) still gets the bar — otherwise that page would offer no
 * chips and no "Show all", leaving the user stranded.
 */
function findGridRoot() {
  let empty = null;
  for (const sel of CONFIG.gridSelectors) {
    const el = document.querySelector(sel);
    if (!el) continue;
    if (el.querySelector(CONFIG.cardSelector)) return el;
    if (!empty && CONFIG.emptyGridSelectors.includes(sel)) empty = el;
  }
  return empty;
}

function debounce(fn, ms) {
  let t;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
}

/**
 * Entry point. Idempotent — safe to call repeatedly.
 *
 * The tag filter only mounts when the user is signed in to EverBee. Auth state
 * is derived from `chrome.storage.local` (see userSlice / App.jsx); we also
 * subscribe to storage changes so logging in on another tab mounts the bar,
 * and logging out tears it down, without a page reload.
 */
export function initTagFilter() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;

  const setup = async () => {
    if (initialized) return;
    if (!CONFIG.urlMatcher(window.location.href)) return;
    if (!(await isEverbeeLoggedIn())) return;

    const gridRoot = findGridRoot();
    if (!gridRoot) return;

    // Prevent double-mount on this page load.
    if (document.querySelector('[data-everbee-tag-filter-host]')) return;

    initialized = true;

    injectHidingStyle();

    const { host, bar } = createHost();

    // Place the bar immediately above the results grid.
    if (gridRoot.parentNode) {
      gridRoot.parentNode.insertBefore(host, gridRoot);
    } else {
      return;
    }

    let state = await loadState();
    let currentCardMap = new Map();
    let currentLabels = [];
    let currentAdCount = 0;
    let hasTrackedView = false;

    const rerender = () => {
      renderBar(bar, {
        uniqueLabels: currentLabels,
        adCount: currentAdCount,
        state,
        onToggleLabel: handleToggleLabel,
        onToggleAds: handleToggleAds,
        onReset: handleReset,
      });
      applyVisibility(currentCardMap, state);
    };

    const handleToggleLabel = (label) => {
      // Bestseller / Etsy's Pick are delegated to Etsy via URL query params
      // (is_best_seller / is_merch_library). Toggling navigates the page; we
      // do not mirror them in local state, so the chip's on/off state is
      // derived from the URL on next render.
      if (getServerFilterForLabel(label)) {
        const wasOn = isServerFilterActive(label);
        if (toggleServerFilterForLabel(label)) {
          if (!wasOn) {
            amplitude.track('On_Page_Filter_Apply', {
              product_type: 'extension',
              filter_name: label.toLowerCase(),
            });
          }
          return;
        }
      }

      const selected = { ...state.selected };
      const turningOn = selected[label] !== true;
      if (selected[label] === true) delete selected[label];
      else selected[label] = true;
      state = { ...state, selected };
      saveState(state);
      if (turningOn) {
        amplitude.track('On_Page_Filter_Apply', {
          product_type: 'extension',
          filter_name: label.toLowerCase(),
        });
      }
      rerender();
    };

    const handleToggleAds = () => {
      state = { ...state, hideAds: !state.hideAds };
      saveState(state);
      rerender();
    };

    const handleReset = () => {
      // Clear server-side filter params too. If any were set,
      // clearAllServerFilters triggers a navigation and the page reloads —
      // local state is still saved first so we end up in a clean baseline.
      state = { ...DEFAULT_STATE };
      saveState(state);
      if (clearAllServerFilters()) return;
      rerender();
    };

    let activeGridRoot = gridRoot;

    const rescan = () => {
      const liveGrid = findGridRoot() || activeGridRoot;
      const { cardMap, uniqueLabels, adCount } = scanGrid(liveGrid);
      currentCardMap = cardMap;
      currentLabels = uniqueLabels;
      currentAdCount = adCount;

      // Always-visible filters keep the bar mounted even on a page whose
      // results carry no badges at all — that is the whole point of a static
      // chip. Only hide when there is genuinely nothing to render.
      if (
        uniqueLabels.length === 0 &&
        adCount === 0 &&
        getStaticServerFilters().length === 0
      ) {
        host.style.display = 'none';
        return;
      }
      host.style.display = 'block';
      if (!hasTrackedView) {
        hasTrackedView = true;
        let shouldFire = true;
        try {
          const url = new URL(window.location.href);
          const searchKey =
            url.pathname + '|' + (url.searchParams.get('q') || '');
          if (
            sessionStorage.getItem('eb_filter_last_view_search') === searchKey
          ) {
            shouldFire = false;
          } else {
            sessionStorage.setItem('eb_filter_last_view_search', searchKey);
          }
        } catch (_) {
          /* silent */
        }
        if (shouldFire) {
          amplitude.track('On_Page_Filter_View', {
            product_type: 'extension',
          });
        }
      }
      rerender();
    };

    rescan();

    const debouncedRescan = debounce(rescan, CONFIG.observerDebounceMs);

    let mo = new MutationObserver(debouncedRescan);
    const observeGrid = (root) => {
      try {
        mo.disconnect();
        mo = new MutationObserver(debouncedRescan);
        mo.observe(root, {
          childList: true,
          subtree: true,
          attributes: false,
          characterData: false,
        });
        activeGridRoot = root;
      } catch (_) {
        /* silent */
      }
    };
    observeGrid(gridRoot);

    /**
     * After SPA navigation the old gridRoot is detached, so the
     * MutationObserver goes deaf and the host element disappears.
     * Retry until the new grid is ready, then re-parent the host
     * and reconnect the observer.
     */
    const reconnectAfterNavigation = () => {
      let navAttempts = 0;
      const tryReconnect = () => {
        const newGrid = findGridRoot();
        if (newGrid) {
          if (!host.isConnected || !newGrid.parentNode?.contains(host)) {
            if (newGrid.parentNode) {
              newGrid.parentNode.insertBefore(host, newGrid);
            }
          }
          observeGrid(newGrid);
          // Etsy often hydrates listings in waves. Re-scan several times so
          // active filters get re-applied to late-arriving cards.
          const staged = [0, 300, 700, 1200, 2000, 3200, 5000];
          staged.forEach((ms) => {
            setTimeout(() => {
              if (!initialized) return;
              if (!activeGridRoot?.isConnected) return;
              rescan();
            }, ms);
          });
          return;
        }
        navAttempts += 1;
        if (navAttempts < 20) {
          setTimeout(tryReconnect, 300);
        }
      };
      tryReconnect();
    };

    // Safety net for Etsy flows that swap the grid without a URL change.
    const detachedGridCheck = setInterval(() => {
      if (!initialized) return;
      if (
        !activeGridRoot?.isConnected &&
        CONFIG.urlMatcher(window.location.href)
      ) {
        reconnectAfterNavigation();
      } else if (hasActiveFilters(state)) {
        // Keep applying selected filters while Etsy progressively appends cards.
        debouncedRescan();
      }
    }, 1200);

    let lastHref = window.location.href;
    const urlCheck = setInterval(() => {
      if (window.location.href === lastHref) return;
      lastHref = window.location.href;
      if (!CONFIG.urlMatcher(lastHref)) {
        teardown?.();
      } else {
        hasTrackedView = false;
        reconnectAfterNavigation();
      }
    }, 500);

    // Expose a single teardown so we can unmount on logout, URL change, or
    // any other external trigger. Safe to call multiple times.
    teardown = () => {
      if (!initialized) return;
      try {
        mo.disconnect();
      } catch (_) {
        /* silent */
      }
      clearInterval(urlCheck);
      clearInterval(detachedGridCheck);
      host.remove();
      initialized = false;
      teardown = null;
    };
  };

  // Retry a few times — Etsy hydrates the grid asynchronously.
  let attempts = 0;
  const tick = () => {
    if (initialized) return;
    setup();
    attempts += 1;
    if (!initialized && attempts < 20) {
      setTimeout(tick, 500);
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', tick, { once: true });
  } else {
    tick();
  }

  // React to EverBee login / logout without requiring a page reload. The auth
  // token lives in chrome.storage.local under REACT_APP_AUTH_COOKIE_NAME; when
  // it appears we try to mount, when it disappears we tear down.
  try {
    const authKey = getAuthStorageKey();
    if (authKey && chrome?.storage?.onChanged) {
      chrome.storage.onChanged.addListener((changes, areaName) => {
        if (areaName !== 'local') return;
        if (!(authKey in changes)) return;
        const nowLoggedIn = !!changes[authKey].newValue;
        if (nowLoggedIn) {
          if (!initialized) {
            attempts = 0;
            tick();
          }
        } else if (initialized) {
          teardown?.();
        }
      });
    }
  } catch (_) {
    /* silent */
  }
}

export default initTagFilter;
