/*global chrome*/
import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Skeleton } from '@mui/material';
import * as amplitude from '@amplitude/analytics-browser';
import { StyledWrapper } from './StyledWrapper';
import HeadingAndIcons from './HeadingAndIcons';
import SlideTabs from './SlideTabs';
import ImageAndDetails from './ImageAndDetails';
import DetailsTable from '../DetailsTable/DetailsTable';
import Tags from './Tags';
import MoreDetails from './MoreDetails';
import {
  changeActiveSubMenu,
  changeFeaturePage,
  changeIframeUrl,
  toggleRightPane,
} from '../../store/slices/sidebarSlice';
import { MAIN_MENU, SUB_MENU_LIST } from '../../constants/menuList';
import TagsModal from '../TagsModal/TagsModal';
import {
  toggleSidebarTrendsModal,
  toggleTagsModal,
} from '../../store/slices/utilitySlice';
import LockIconDark from '@components/LockIconDark';
import RightSidePaneTooltip from '@components/CustomToolTip/RightSidePaneTooltip';

import Graph from '../DailyTrends/Graph';
import SidebarTrendsModal from '../SidebarTrendsModal/SidebarTrendsModal';
import PromoBanner from '../PromoBanner/PromoBanner';

const RightPane = ({ closeDrawer, isAuth }) => {
  const dispatch = useDispatch();
  const [activeButton, setActiveButton] = useState('Listing Details');

  const { userData } = useSelector((state) => state.user);
  const {
    listingDetailsData,
    shopDetailsData,
    sidePanTags,
    rightPaneLoading,
    isTagsModal,
    isSidebarTrendsModal,
    timeRange,
  } = useSelector((state) => state.utilities);

  const maximizeIcon = chrome.runtime.getURL('svg/expand-big.svg');

  const daysOrMonths =
    timeRange === 'last_30_days' ||
    timeRange === 'last_1_month' ||
    timeRange === 'last_3_months' ||
    (timeRange === 'all_time' && listingDetailsData.listingAge < 6)
      ? 'Days'
      : 'Months';

  const listingDetails = {
    image: listingDetailsData.image,
    listingImages: listingDetailsData.listingImages,
    heading: listingDetailsData.title,
    // subHeading: listingDetailsData,
    price: listingDetailsData.price,
    currencySymbol: listingDetailsData.currencySymbol,
    shop: shopDetailsData.name,
    url: listingDetailsData.url,
  };

  const listingdetailsGridData = [
    {
      heading: 'Mo. Sales',
      value: listingDetailsData.monthlySales,
      tooltip: 'Approximate number of units sold over the last month.',
    },
    {
      heading: 'Mo. Revenue',
      value: listingDetailsData.monthlyRevenue,
      currencySymbol: listingDetailsData.currencySymbol,
      tooltip:
        'Approximate total revenue earned over the last month including all variants.',
    },
    {
      heading: 'Total sales',
      value: listingDetailsData.totalSales,
      tooltip:
        'Total estimated number of units sold since the listing was created.',
    },
    {
      heading: 'Listing age',
      value: listingDetailsData.listingAge,
      tooltip: 'Duration (in months) since the listing was published.',
    },
    {
      heading: 'Reviews',
      value: listingDetailsData.reviews,
      tooltip: 'Total number of customer reviews for this listing.',
    },
    {
      heading: 'Views',
      value: listingDetailsData.views,
      tooltip:
        'Total number of times this listing has been viewed by customers.',
    },
    {
      heading: 'Favorites',
      value: listingDetailsData.favourites,
      tooltip: 'Total number of times customers have favorited this listing.',
    },
    {
      heading: 'Mo. Reviews',
      value: listingDetailsData.reviewsPerMonth,
      tooltip:
        'The typical number of reviews this listing receives each month, calculated from the time it was first created',
    },
  ];

  const listingdetailsConversionData = [
    {
      heading: 'Conversion rate',
      value: listingDetailsData?.conversionRate,
      tooltip:
        'Average conversion rate for this listing, calculated as Total Sales divided by Total Views.',
    },
    {
      heading: 'Category',
      value: listingDetailsData.category,
      tooltip: 'Category within Etsy in which the product is listed.',
    },
    {
      heading: 'Visibility score',
      value: listingDetailsData.visibilityscore,
      tooltip:
        'Compares daily views of a listing against others on the platform, indicating its performance in terms of visibility and average daily views',
    },
    {
      heading: 'Review ratio',
      value: listingDetailsData.reviewRatio,
      tooltip:
        'The proportion of reviews relative to the number of sales for this listing.',
    },
  ];

  const moreDetailsData = [
    {
      subHeading: 'When Made',
      value: listingDetailsData.whenMade,
    },
    {
      subHeading: 'Listing Type',
      value: listingDetailsData.listingType,
    },
    {
      subHeading: 'Customizable',
      value: listingDetailsData.customizable,
    },
    {
      subHeading: 'Craft Supply',
      value: listingDetailsData.craftSupply,
    },
    {
      subHeading: 'Personalized',
      value: listingDetailsData.personalized,
    },
    {
      subHeading: 'Auto Renew',
      value: listingDetailsData.autoRenew,
    },
    {
      subHeading: 'Has variations',
      value: listingDetailsData.hasVariations,
    },
    {
      subHeading: 'Placements of Listing Shops',
      value: listingDetailsData.placementOfListingShops,
    },
    {
      subHeading: 'Title character count',
      value: listingDetailsData.titleCharCount,
    },
    {
      subHeading: '# of tags',
      value: listingDetailsData.tagsCount,
    },
    {
      subHeading: 'Who Made',
      value: listingDetailsData.whoMade,
    },
  ];

  const shopDetails = {
    image: shopDetailsData.image,
    heading: shopDetailsData.name,
    subHeading: shopDetailsData.title,
    location: shopDetailsData.location,
    rate: shopDetailsData.reviews,
    url: shopDetailsData.url,
  };

  const shopDetailsGrid = [
    {
      heading: 'Total Sales',
      value: shopDetailsData.totalSales,
      tooltip:
        'The total number of sales this shop has recieved since being created',
    },
    {
      heading: 'Shop Age',
      value: shopDetailsData.shopAge,
      tooltip: 'The number of months since the shop was created',
    },
    {
      heading: 'Total Reviews',
      value: shopDetailsData.totalReviews,
      tooltip:
        'The total number of reviews this shop has recieved since being created',
    },
    {
      heading: 'Total Listings',
      value: shopDetailsData.totalListings,
      tooltip: 'The total number of listings this shop has',
    },
  ];

  const reviewRatio = () => {
    const reviews = listingDetailsData?.reviews;
    const totalSales = listingDetailsData?.totalSales;
    if (reviews?.toString().includes('Please upgrade')) {
      return 'Upgrade';
    }
    const ratio = (reviews / totalSales) * 100;
    return isNaN(ratio) ? '--' : `${ratio.toFixed(2)}%`;
  };

  const handleAnalyzeShopClick = () => {
    dispatch(toggleRightPane(false));
    dispatch(
      changeActiveSubMenu({
        value: SUB_MENU_LIST.RESEARCH_TOOLS[1].slug,
        subMenuIndex: 1,
      }),
    );
    // dispatch(changeIframeUrl(`shop-analyzer/${shopDetails.heading}`));
    window.open(
      `https://app.everbee.io/shop-analyzer/${shopDetails.heading}`,
      '_blank',
    );

    // Amplitude
    amplitude.track('Analyze_Shop_Click', {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      shop_name: shopDetails.heading,
      listing_name: listingDetailsData.title,
      source_type: 'listing_details',
    });
  };

  const handlModalClose = () => {
    dispatch(toggleTagsModal(false));
  };

  const handlTrendsModalClose = () => {
    dispatch(toggleSidebarTrendsModal(false));
  };

  const handleTrendsExpandClick = () => {
    dispatch(toggleSidebarTrendsModal(true));
  };

  const handleUpgradeClick = () => {
    if (isAuth) {
      dispatch(toggleRightPane(false));
      dispatch(changeFeaturePage(MAIN_MENU.PRICING));
      dispatch(changeIframeUrl('pricing'));
      return;
    } else {
      window.location.href = `${process.env.REACT_APP_AUTH_FRONTEND_APP}/login?redirect_to=https://etsy.com`;
      return;
    }
  };

  return (
    <StyledWrapper>
      <HeadingAndIcons
        activeButton={activeButton}
        closeDrawer={closeDrawer}
        loading={rightPaneLoading}
      />
      <SlideTabs
        activeButton={activeButton}
        setActiveButton={setActiveButton}
        shopDetails={listingDetails}
      />

      {activeButton === 'Listing Details' && (
        <>
          <ImageAndDetails
            activeButton={activeButton}
            details={listingDetails}
            loading={rightPaneLoading}
          />
          <DetailsTable
            activeButton={activeButton}
            details={listingdetailsGridData}
            loading={rightPaneLoading}
          />
          <DetailsTable
            activeButton={activeButton}
            conversionGrid
            details={listingdetailsConversionData}
            reviewRatio={reviewRatio}
            loading={rightPaneLoading}
          />
          <div className="daily_trends_container">
            <div className="trends_header">
              <div className="trends-header-left">
                <RightSidePaneTooltip
                  PopperProps={{
                    style: {
                      zIndex: 9999999,
                    },
                  }}
                  title={
                    'View estimated historical trends data for this item. Find out when this item is in-demand.'
                  }
                  placement="top"
                  arrow
                >
                  <span className="trends-graph">Trends Graph</span>
                </RightSidePaneTooltip>
                {/* <div className="trends-beta-tag">Beta</div> */}
              </div>
              {userData?.current_plan !== 'hobby' && !rightPaneLoading && (
                <div className="trends-header-right">
                  {/* <div className="timeframe-indicator">{daysOrMonths}</div> */}
                  <img
                    className="down-arrow"
                    src={maximizeIcon}
                    alt="btn_expand"
                    onClick={handleTrendsExpandClick}
                  />{' '}
                </div>
              )}
            </div>
            {userData?.current_plan === 'hobby' && (
              <div className="trends-overlay">
                <div className="trends-hobby-container">
                  <LockIconDark />
                  <span className="trends-hobby-header">
                    This is a paid feature
                  </span>
                  <span className="trends-hobby-desc">
                    Upgrade your plan to get full access to daily trends data
                  </span>
                </div>
                <button className="upgrade-button" onClick={handleUpgradeClick}>
                  Upgrade
                </button>
              </div>
            )}
            <div className="trends_graph_wrapper">
              <Graph
                currencySymbol={listingDetailsData?.currencySymbol}
                listingName={listingDetailsData.title}
                details={listingDetailsData}
              />
            </div>
            {/* <span className="trends-note">
              Note: Estimates reflect data up to 7 days before today and are updated on a daily basis.
            </span> */}
          </div>

          <Tags
            TAGS_TABLE_DATA={sidePanTags}
            loading={rightPaneLoading}
            isAuth={isAuth}
          />
          <MoreDetails details={moreDetailsData} loading={rightPaneLoading} />
        </>
      )}

      {activeButton === 'Shop Details' && (
        <>
          <ImageAndDetails
            activeButton={activeButton}
            details={shopDetails}
            loading={rightPaneLoading}
          />
          <DetailsTable
            activeButton={activeButton}
            details={shopDetailsGrid}
            loading={rightPaneLoading}
          />
          {rightPaneLoading ? (
            <Skeleton
              variant="rounded"
              width={107}
              height={32}
              animation="wave"
              sx={{ margin: '16px 0px 16px 20px' }}
            />
          ) : (
            <button className="button-style" onClick={handleAnalyzeShopClick}>
              Analyze Shop
            </button>
          )}
          {!rightPaneLoading && (
            <PromoBanner variant="compact" touchpoint="listing_sidebar" />
          )}
        </>
      )}

      {isTagsModal && (
        <TagsModal handleClose={handlModalClose} isAuth={isAuth} />
      )}
      {isSidebarTrendsModal && (
        <SidebarTrendsModal
          handleClose={handlTrendsModalClose}
          currencySymbol={listingDetailsData?.currencySymbol}
        />
      )}
    </StyledWrapper>
  );
};

export default RightPane;
