/*global chrome*/
import axios from 'axios';

const EMAIL_BASE_URL = process.env.REACT_APP_EMAIL_BACKEND;

// Deliberately a standalone axios instance instead of the shared default one.
// This endpoint lives on the email backend, and a user who simply has no email
// app access (or whose token is not provisioned there) must not have that
// answer treated as a Research auth failure. The shared instance also carries
// a request interceptor that assumes the Research backend.
const emailClient = axios.create();

// chrome.storage.local is async and callback-based, so the token has to be
// awaited rather than read inline the way the web app reads its cookie.
const getToken = () =>
  new Promise((resolve) => {
    chrome.storage.local.get(
      `${process.env.REACT_APP_AUTH_COOKIE_NAME}`,
      (result) => resolve(result?.[process.env.REACT_APP_AUTH_COOKIE_NAME]),
    );
  });

export const getEmailAppActivatedAPI = async () => {
  const token = await getToken();

  return emailClient.get(`${EMAIL_BASE_URL}/api/v1/users/email_app_activated`, {
    headers: {
      Accept: 'application/json',
      'X-Access-Token': token,
    },
  });
};
