/*global chrome*/
import { FindByAttributeValue } from './getElementThroughAttribute';

function getListingIds(
  category,
  setEtsyCurrencyCode,
  setListingDetails,
  everBeeLogo,
) {
  // const everBeeLogo = chrome.runtime.getURL("images/everBee-logo.svg");
  var listingIds = [];
  var listingDetailsArray = [];
  if (category == 'shop') {
    let listings = document.querySelectorAll('.v2-listing-card');
    listings.forEach((item) => {
      if (item.getAttribute('data-listing-id')) {
        if (
          item.getElementsByClassName('vertically-centered-placeholder') &&
          item.getElementsByClassName('vertically-centered-placeholder')[0]
        ) {
          item
            .getElementsByClassName('vertically-centered-placeholder')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('vertically-centered-placeholder')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%"   src=${everBeeLogo} alt="logo"/></div>`;
        } else if (
          item.getElementsByClassName('lc-carousel-container') &&
          item.getElementsByClassName('lc-carousel-container')[0]
        ) {
          item
            .getElementsByClassName('lc-carousel-container')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('lc-carousel-container')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%"   src=${everBeeLogo} alt="logo"/></div>`;
        }
        listingDetailsArray.push({
          id: item.getAttribute('data-listing-id'),
          discountedPrice: item
            .querySelector('.currency-value')
            ?.innerText?.replace(/,/g, ''),
          originalPrice: item
            .querySelector('.search-collage-promotion-price .currency-value')
            ?.innerText?.replace(/,/g, ''),
          discountPercent: item
            .querySelector('.search-collage-promotion-price')
            ?.lastElementChild?.innerText?.match(/\d+([\.]\d+)?/g)?.[0],
        });
        listingIds.push(item.getAttribute('data-listing-id'));
      }
    });
  } else if (category == 'people') {
    let listings = document.querySelectorAll(
      '.wt-list-unstyled .v2-listing-card, .block-grid-no-whitespace .v2-listing-card',
    );
    listings.forEach((item) => {
      listingIds.push(item.getAttribute('data-listing-id'));
    });

    // Scrapped Individual analytics for people
    listings.forEach((item) => {
      if (item.getAttribute('data-listing-id')) {
        if (
          item.getElementsByClassName('vertically-centered-placeholder') &&
          item.getElementsByClassName('vertically-centered-placeholder')[0]
        ) {
          item
            .getElementsByClassName('vertically-centered-placeholder')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('vertically-centered-placeholder')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%" src=${everBeeLogo} alt="logo"/></div>`;
        } else if (
          item.getElementsByClassName('lc-carousel-container') &&
          item.getElementsByClassName('lc-carousel-container')[0]
        ) {
          item
            .getElementsByClassName('lc-carousel-container')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('lc-carousel-container')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%" src=${everBeeLogo} alt="logo"/></div>`;
        }
        listingIds.push(item.getAttribute('data-listing-id'));
        listingDetailsArray.push({
          id: item.getAttribute('data-listing-id'),
          discountedPrice: item
            .querySelector('.currency-value')
            ?.innerText?.replace(/,/g, ''),
          originalPrice: item
            .querySelector('.search-collage-promotion-price .currency-value')
            ?.innerText?.replace(/,/g, ''),
          discountPercent: item
            .querySelector('.search-collage-promotion-price')
            ?.lastElementChild?.innerText?.match(/\d+([\.]\d+)?/g)?.[0],
        });
      }
    });
  } else if (category == 'trending_now') {
    let listings = document.querySelectorAll('ul#search-results li a');
    listings.forEach((item) => {
      listingIds.push(item.getAttribute('data-listing-id'));
    });

    // Scrapped Individual analytics for trending_now

    listings.forEach((item) => {
      if (item.getAttribute('data-listing-id')) {
        if (
          item.getElementsByClassName('vertically-centered-placeholder') &&
          item.getElementsByClassName('vertically-centered-placeholder')[0]
        ) {
          item
            .getElementsByClassName('vertically-centered-placeholder')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('vertically-centered-placeholder')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%" src=${everBeeLogo} alt="logo"/></div>`;
        } else if (
          item.getElementsByClassName('lc-carousel-container') &&
          item.getElementsByClassName('lc-carousel-container')[0]
        ) {
          item
            ?.getElementsByClassName('lc-carousel-container')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('lc-carousel-container')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%" src=${everBeeLogo} alt="logo"/></div>`;
        }
        listingIds.push(item.getAttribute('data-listing-id'));
        listingDetailsArray.push({
          id: item.getAttribute('data-listing-id'),
          discountedPrice: item
            .querySelector('.currency-value')
            ?.innerText?.replace(/,/g, ''),
          originalPrice: item
            .querySelector('.search-collage-promotion-price .currency-value')
            ?.innerText?.replace(/,/g, ''),
          discountPercent: item
            .querySelector('.search-collage-promotion-price')
            ?.lastElementChild?.innerText?.match(/\d+([\.]\d+)?/g)?.[0],
        });
      }
    });
  } else if (category == 'homePage') {
    let listings = document.querySelectorAll('.v2-listing-card');
    if (listings.length <= 0) {
      listings = document.querySelectorAll('#content ul.wt-block-grid li a');
      if (listings.length <= 0) {
        listings = document.querySelectorAll('.block-grid-no-whitespace li');
      }
    }
    listings.forEach((item) => {
      listingIds.push(item.getAttribute('data-listing-id'));
    });

    // Scrapped Individual analytics for Homepage
    listings.forEach((item) => {
      if (item.getAttribute('data-listing-id')) {
        if (
          item.getElementsByClassName('vertically-centered-placeholder') &&
          item.getElementsByClassName('vertically-centered-placeholder')[0]
        ) {
          item.getElementsByClassName('vertically-centered-placeholder')[0].innerHTML +=
            `<span class="overlay_eb"   data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img  src=${everBeeLogo} alt="logo"/></span>`;
        } else if (
          item.getElementsByClassName('lc-carousel-container') &&
          item.getElementsByClassName('lc-carousel-container')[0]
        ) {
          item.getElementsByClassName('lc-carousel-container')[0].innerHTML +=
            `<span class="overlay_eb"   data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img  src=${everBeeLogo} alt="logo"/></span>`;
        }
        listingIds.push(item.getAttribute('data-listing-id'));
        listingDetailsArray.push({
          id: item.getAttribute('data-listing-id'),
          discountedPrice: item
            .querySelector('.currency-value')
            ?.innerText?.replace(/,/g, ''),
          originalPrice: item
            .querySelector('.search-collage-promotion-price .currency-value')
            ?.innerText?.replace(/,/g, ''),
          discountPercent: item
            .querySelector('.search-collage-promotion-price')
            ?.lastElementChild?.innerText?.match(/\d+([\.]\d+)?/g)?.[0],
        });
      }
    });
  } else {
    let searchedRelatedResults = FindByAttributeValue(
      'data-above-recs-and-footer',
      '',
    );
    let listings = document.querySelectorAll('.v2-listing-card');

    // Scrapped Individual analytics for remaining categories
    listings?.forEach((item) => {
      if (item.getAttribute('data-listing-id')) {
        if (
          item.getElementsByClassName('vertically-centered-placeholder') &&
          item.getElementsByClassName('vertically-centered-placeholder')[0]
        ) {
          item
            ?.getElementsByClassName('vertically-centered-placeholder')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('vertically-centered-placeholder')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%"   src=${everBeeLogo} alt="logo"/></div>`;
        } else if (
          item.getElementsByClassName('lc-carousel-container') &&
          item.getElementsByClassName('lc-carousel-container')[0]
        ) {
          item
            ?.getElementsByClassName('lc-carousel-container')?.[0]
            ?.classList?.add('everbee-icon-container');
          item.getElementsByClassName('lc-carousel-container')[0].innerHTML +=
            `<div class="overlay_eb" data-listing-id1=${item.getAttribute(
              'data-listing-id',
            )}><img id="overlay_eb img" width="100%"   src=${everBeeLogo} alt="logo"/></div>`;
        }
        listingDetailsArray.push({
          id: item.getAttribute('data-listing-id'),
          discountedPrice: item
            .querySelector('.currency-value')
            ?.innerText?.replace(/,/g, ''),
          originalPrice: item
            .querySelector('.search-collage-promotion-price .currency-value')
            ?.innerText?.replace(/,/g, ''),
          discountPercent: item
            .querySelector('.search-collage-promotion-price')
            ?.lastElementChild?.innerText?.match(/\d+([\.]\d+)?/g)?.[0],
        });
        if (
          searchedRelatedResults === undefined ||
          searchedRelatedResults === null
        ) {
          listingIds.push(item.getAttribute('data-listing-id'));
        }
      }
    });
    if (searchedRelatedResults) {
      let searchRelatedListings =
        searchedRelatedResults.querySelectorAll('.v2-listing-card');
      for (let i = 0; i < searchRelatedListings.length; i++) {
        if (searchRelatedListings[i].getAttribute('data-listing-id')) {
          listingIds.push(
            searchRelatedListings[i].getAttribute('data-listing-id'),
          );
        }
      }
    }
  }

  setListingDetails((prev) => prev.concat(...listingDetailsArray));

  const getCurrencyCodeFromEtsy = document
    .getElementById('locale-picker-trigger')
    ?.innerText.split('|')[2]
    ?.trim()
    ?.split(' ')[1]
    ?.replace(/[()]/g, '');
  setEtsyCurrencyCode(getCurrencyCodeFromEtsy);
}

export function getListingIdsByCategoryIndividualAnalytics(
  setEtsyCurrencyCode,
  setListingDetails,
  everBeeLogo,
) {
  var fullUrl = window.location.href;
  if (fullUrl.indexOf('/shop/') !== -1) {
    getListingIds('shop', setEtsyCurrencyCode, setListingDetails, everBeeLogo);
  } else if (fullUrl.indexOf('people') !== -1) {
    getListingIds(
      'people',
      setEtsyCurrencyCode,
      setListingDetails,
      everBeeLogo,
    );
  } else if (
    fullUrl.indexOf('search?') !== -1 ||
    fullUrl.indexOf('/search/') !== -1 ||
    fullUrl.indexOf('/everyday') !== -1
  ) {
    getListingIds(
      'keywords',
      setEtsyCurrencyCode,
      setListingDetails,
      everBeeLogo,
    );
  } else if (fullUrl.indexOf('market/') !== -1) {
    getListingIds(
      'trending_now',
      setEtsyCurrencyCode,
      setListingDetails,
      everBeeLogo,
    );
  } else if (
    (fullUrl.indexOf('/c') !== -1 && fullUrl.indexOf('/ca') === -1) ||
    fullUrl.indexOf('/markets') !== -1
  ) {
    getListingIds(
      'pCategory',
      setEtsyCurrencyCode,
      setListingDetails,
      everBeeLogo,
    );
  } else if (
    fullUrl.indexOf('www.etsy.com') !== -1 ||
    fullUrl.indexOf('?ref=lgo') !== -1
  ) {
    getListingIds(
      'homePage',
      setEtsyCurrencyCode,
      setListingDetails,
      everBeeLogo,
    );
  } else {
  }
}

// Single-listing product page (/listing/<id>): there are no `.v2-listing-card`
// grid cards, so inject ONE `.overlay_eb` bee into the image carousel. Since the
// page is one listing, the id is constant — a single overlay on the carousel
// container stays bottom-right while the user flips through images, and the
// gemini hover pill (content.js) keys off `.overlay_eb` like everywhere else.
export function injectListingPageOverlay(everBeeLogo) {
  if (window.location.href.indexOf('/listing/') === -1) return;
  const container = document.querySelector('.image-carousel-container');
  if (!container) return;
  // Idempotent — skip if we already added it.
  if (container.querySelector(':scope > .overlay_eb')) return;
  const listingId = container.parentElement?.getAttribute(
    'data-palette-listing-id',
  );
  if (!listingId) return;
  container.classList.add('everbee-icon-container');
  // insertAdjacentHTML (not innerHTML +=) so Etsy's carousel DOM/handlers are
  // left intact — we only append the bee.
  container.insertAdjacentHTML(
    'beforeend',
    `<div class="overlay_eb" data-listing-id1="${listingId}"><img id="overlay_eb img" width="100%" src="${everBeeLogo}" alt="logo"/></div>`,
  );
}
