
import { getNumberWithCommas } from "./getNumberWithCommas";
import { generateHtmlContent } from "./onPageMetricsContent";
import * as amplitude from '@amplitude/analytics-browser';
import { toast } from "react-toastify";
import { FindByAttributeValue } from "./getElementThroughAttribute";

export const handleLockPricing = (e) => {
  e.stopPropagation();
  window.open(
    `${
      process.env.REACT_APP_FRONTEND_URL
    }/authentication?token=${localStorage.getItem(
      "everbeeUserId"
    )}&email=${encodeURIComponent(
      localStorage.getItem("everbeeEmail")
    )}&redirectToPricing=true`,
    "_blank"
  );
};

export const onPageMetricsAssignValue = (
  onPageMetricsData,
  handleClick,
  setOnPageMetricsData,
  handleClickFavourites,
  isListingFav,
  currentPlan,
  handlePricing
) => {
  const beeIcon = chrome.runtime.getURL("svg/everbee-logo-sm.svg");
  const favoriteFill = chrome.runtime.getURL("svg/favorite-fill.svg");
  const infoIcon = chrome.runtime.getURL("svg/info-dark-gray.svg");
  const lockIconMetrics = chrome.runtime.getURL("svg/lock-metrics.svg");
  const filledfavorite = chrome.runtime.getURL("svg/favorite-filled.svg");
  
  let UrlLink = window.location.href;
  if (UrlLink.includes("/listing/")) {
  let breadcrumbNavElementOuter = FindByAttributeValue(
    'id',
    'listing-right-column',
  );
  let breadcrumbNavElement = breadcrumbNavElementOuter?.firstElementChild;
  let adaptiveListingPageElement = FindByAttributeValue(
    'data-selector',
    'adaptive-listing-page',
  );
    let priceContainer = FindByAttributeValue(
      "data-buy-box-listing-title",
      "true"
    );
   
    let backgroundColor = "";
    let color = "";
    if (onPageMetricsData?.conversionRate < 0.1) {
      backgroundColor = "#F1706C33";
      color = "#DC3C36";
    }
    if (
      onPageMetricsData?.conversionRate > 0.1 &&
      onPageMetricsData?.conversionRate < 5
    ) {
      backgroundColor = "#6FB4F733";
      color = "#1F76CC";
    }
    if (onPageMetricsData?.conversionRate > 5) {
      backgroundColor = "#4AA65933";
      color = "#4AA659";
    }
    const loadingAnalyzepresent = document.getElementById(
      "eb-on-page-metrics-analyze-loading"
    );
    if (loadingAnalyzepresent) {
      loadingAnalyzepresent.remove();
    }
    let newDiv = document.querySelector(".new-metrics-div"); 
      if (!newDiv) {
        newDiv = document.createElement("div");
        newDiv.className = "new-metrics-div"; // Add a class for easier selection later
        newDiv.style.padding = "6px"; // Adjust the padding as needed
        newDiv.style.width = "63%";
        newDiv.style.marginLeft = "22px";
        if (breadcrumbNavElement) {
          breadcrumbNavElement.firstElementChild?.prepend(newDiv);
        } else if (adaptiveListingPageElement) {
          adaptiveListingPageElement.prepend(newDiv);
        }
      }
      if (
        Object.keys(onPageMetricsData).length   === 0
      ) {
        const htmlContent = generateHtmlContent(
          "TestGroupLoading",
          beeIcon,
          onPageMetricsData.isFav ?filledfavorite: favoriteFill,
          infoIcon,
          lockIconMetrics,
          onPageMetricsData?.listingAge,
          onPageMetricsData?.estMoSales,
          onPageMetricsData?.views,
          onPageMetricsData?.conversionRate,
          onPageMetricsData?.favourites
        );
        newDiv.innerHTML = htmlContent;
      } else if (
        Object.keys(onPageMetricsData).length   !== 0 
      ) {
        const htmlContent = generateHtmlContent(
          currentPlan !== 'hobby' ? 'TestGroup3PaidPlan': 'TestGroup3HobbyPlan',
          beeIcon,
          isListingFav === true ? filledfavorite : favoriteFill,
          infoIcon,
          lockIconMetrics,
          getNumberWithCommas(onPageMetricsData?.listingAge),
          getNumberWithCommas(onPageMetricsData?.monthlySales),
          getNumberWithCommas(onPageMetricsData?.views),
          onPageMetricsData?.conversionRate,
          getNumberWithCommas(onPageMetricsData?.totalSales),
          getNumberWithCommas(onPageMetricsData?.favourites),
          handleClick,
          backgroundColor,
          color,
          onPageMetricsData?.listingAge,
          getNumberWithCommas(onPageMetricsData?.shopSales),
          isListingFav === true  ? true : false,
          handlePricing
        );
        newDiv.innerHTML = htmlContent;
      }
      const tooltips = newDiv?.querySelectorAll(".tooltip-pg .eb-tooltiptext");
      if (tooltips) {
        tooltips.forEach((tooltip) => {
          tooltip.addEventListener("click", (e) => {
            e.stopPropagation();
            handlePricing(e);
          });
        });
      }
    
    const listingButton = document.getElementById("eb-listing-details");
    const analyticsBtn = document.getElementById("everbee-analytics-btn");
    const favoriteButton = document.getElementById("eb-add-favorite");
    const analyticsDiv = document.getElementById(
      "eb-on-page-metrics-analyze-loading"
    );
    const moSalesLock = document?.querySelector(".eb-moSalesLock");
    const totalSalesLock = document?.querySelector(".eb-totalSalesLock");
    const convRateLock = document?.querySelector(".eb-convRateLock");

    if (listingButton) {
      listingButton?.addEventListener("click", (e) => {
        let lid = analyticsBtn.getAttribute("data-listing-id1");
        e.stopPropagation();
        handleClick(e, lid);
        amplitude.track("Listing_Details_View", {
          product_type: 'extension',
          feature_type: 'etsy',
          etsy_type: window.location.pathname === '/' ? 'home_page' : 
                        window.location.href.includes('/shop/') ? 'shop_page' : 
                        window.location.href.includes('/listing/') ? 'listing_page' : 
                        window.location.href.includes('/search?q=') ? 'search_results' : 
                        'other_page',
          listing_name: onPageMetricsData?.title,
          // product_url: onPageMetricsData?.url,
          source_type: 'on_page_metrics',
          listing_details_tab_type: 'listing_details_tab'
        });
      });
    }
    if(favoriteButton) {
      favoriteButton?.addEventListener("click", (e) => {
        let lid = analyticsBtn.getAttribute("data-listing-id1");
        
          handleClickFavourites(e);
        
      });
    }
    if (moSalesLock && totalSalesLock && convRateLock) {
      moSalesLock?.addEventListener("click", (e) => {
        handlePricing(e);
      });
      totalSalesLock?.addEventListener("click", (e) => {
        handlePricing(e);
      });
      convRateLock?.addEventListener("click", (e) => {
        handlePricing(e);
      });
    }
  }
};
