const FavKeywordUpdateToast = (props) => {
  if (props.errorMessage) {
    return (
      <StyledFavUpdateWrapper $isModal={props.isModal}>
        <AlertCircle color="#009fe3" />
        <div className="message" style={{ fontWeight: 400 }}>
          {props.errorMessage}
        </div>
      </StyledFavUpdateWrapper>
    );
  }
  return <FavKeywordUpdateToastInner {...props} />;
};

const FavKeywordUpdateToastInner = ({
  row,
  folderDetailsArray,
  action,
  onClose,
  isModal = false,
  onUndoSuccess,
}) => {
  const dispatch = useDispatch();
  const keywordsIcon = chrome.runtime.getURL('svg/keywords.svg');
  const folderNamesArray = folderDetailsArray.map((folder) => folder.name);
  const folderIdsArray = folderDetailsArray.map((folder) => folder.id);
  const bulkKeywordRowsForChange = useSelector(
    (state) => state.utilities.bulkKeywordRowsForChange,
  );
  const bulkKeywordRowsSource = useSelector(
    (state) => state.utilities.bulkKeywordRowsSource,
  );

  const handleCTAClick = async () => {
    if (action === 'add') {
      if (bulkKeywordRowsForChange?.length > 0) {
        dispatch(setCurrentKeywordRowData(bulkKeywordRowsForChange[0]));
        const restoredRowIds = bulkKeywordRowsForChange.map((r) => r.id);
        const restoreAction =
          bulkKeywordRowsSource === 'modal'
            ? updateModalTagsCheckedRows
            : updateSidePanTagsCheckedRows;
        dispatch(
          restoreAction({
            rowIds: restoredRowIds,
            rowsData: bulkKeywordRowsForChange,
          }),
        );
      } else {
        dispatch(setCurrentKeywordRowData(row));
      }
      dispatch(setKeywordsDefaultFolderData(folderDetailsArray));
      setTimeout(() => {
        dispatch(toggleKeywordsWatchlistModal(true));
      }, 300);
      onClose();
    } else if (action === 'undo') {
      const response = await dispatch(
        manageFavItemsInFolders({
          itemIdsArray: [row.keywordId],
          type: 'keyword_analytic',
          folderIdsArray: folderIdsArray,
          idType: 'database',
        }),
      ).unwrap();

      if (onUndoSuccess) {
        onUndoSuccess(row, folderDetailsArray);
      } else {
        setTimeout(() => {
          favKeywordPopup(row, folderDetailsArray, 'add');
        }, 300);
      }

      // Update the isFav status back to true
      dispatch(
        updateSidePaneTagsIsFav({
          keywordId: row.keywordId,
          isFavBool: true,
        }),
      );

      // Increment shops favorite count for undo action
      const added = response?.data?.details?.added || [];
      const removed = response?.data?.details?.removed || [];
      const unchanged = response?.data?.details?.unchanged || [];

      if (added.length > 0 && removed.length === 0 && unchanged.length === 0) {
        dispatch(updateFavoriteCount({ type: 'keywordCount', amount: 1 }));
      }

      onClose();
    }
  };

  const getDisplayTitle = () => {
    if (!Array.isArray(folderNamesArray)) {
      return folderNamesArray; // If it's not an array, return as is
    }

    if (folderNamesArray.length === 1) {
      return folderNamesArray[0];
    }

    if (folderNamesArray.length > 1) {
      const additionalCount = folderNamesArray.length - 1;
      const folderText = additionalCount === 1 ? 'folder' : 'folders';
      return `${folderNamesArray[0]} +${additionalCount} ${folderText}`;
    }

    return ''; // Empty array case
  };

  return (
    <StyledFavUpdateWrapper $isModal={isModal}>
      {bulkKeywordRowsForChange?.length > 1 ? (
        <div className="image-container stacked">
          <div className="main-icon-layer">
            <img src={keywordsIcon} alt="keywords" />
          </div>
        </div>
      ) : (
        <div className="image-container">
          <img src={keywordsIcon} alt="keywords" />
        </div>
      )}
      <div className="message">
        {action === 'add' ? 'Saved to ' : 'Removed from '}{' '}
        <span>{getDisplayTitle()}</span>
      </div>
      <div className="cta" onClick={handleCTAClick}>
        {action === 'add' ? 'Change' : 'Undo'}
      </div>
    </StyledFavUpdateWrapper>
  );
};

export default FavKeywordUpdateToast;
