import React from 'react';
import { Box, Tab, Tabs } from '@mui/material';
import styled from 'styled-components';
import * as amplitude from '@amplitude/analytics-browser';

const StyledWrapper = styled.div`
  display: flex;
  margin: '16px 20px 0px 20px';
  background: ${({ theme }) => theme.colors.neutral.gray200};
  border-radius: 6px;
  height: 36px;
  margin: 12px 16px 0 16px;

  .MuiTabs-flexContainer {
    display: flex;
    justify-content: space-between;
    padding: 4px;
  }

  .MuiButtonBase-root {
    // font-family: 'Satoshi';
    font-style: normal;
    font-weight: 500;
    font-size: 12px;
    line-height: 16px;
    text-transform: none;
    color: ${({ theme }) => theme.colors.neutral.gray900};
    padding: 4px 24px 4px 24px;
    min-height: 28px;
    flex-grow: 1;
  }

  .Mui-selected {
    color: ${({ theme }) => theme.colors.neutral.gray900} !important;
    background: #ffffff;
    box-shadow: ${({ theme }) => theme.shadows.panel2};
    border-radius: 6px;
  }

  .MuiTabs-indicator {
    display: none;
  }
`;

const SlideTabs = ({ activeButton, setActiveButton, shopDetails }) => {
  const handleChange = (e, newValue) => {
    amplitude.track('Listing_Details_View', {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type: window.location.pathname === '/'
                    ? 'home_page'
                    : window.location.href.includes('/shop/')
                      ? 'shop_page'
                      : window.location.href.includes('/listing/')
                        ? 'listing_page'
                        : window.location.href.includes('/search?q=')
                          ? 'search_results'
                          : 'other_page',
      listing_name: shopDetails.heading,
      listing_details_tab_type: newValue === 'Listing Details' ? 'listing_details_tab' : 'shop_details_tab',
    })

    setActiveButton(newValue);
  };
  return (
    <StyledWrapper>
      <Box sx={{ width: '100%', height: '100%' }}>
        <Tabs value={activeButton} onChange={handleChange}>
          <Tab value="Listing Details" label="Listing Details" />
          <Tab value="Shop Details" label="Shop Details" />
        </Tabs>
      </Box>
    </StyledWrapper>
  );
};

export default SlideTabs;
