import { FindByAttributeValue } from './getElementThroughAttribute';
import { scrapePriceInfoFromListingPage } from './scrapePriceInfoFromListingPage';

export function openCalculator() {
  let UrlLink = window.location.href;
  let result = {};

  if (UrlLink.includes('/listing/')) {
    let originalPrice = 0;
    let discountPercentage = 0;
    let costOfDeliver = 0;
    // price and discount scrapping
    let priceElement = FindByAttributeValue('data-buy-box-region', 'price');

    if (priceElement !== undefined) {
      const [originalP, discountP] =
        scrapePriceInfoFromListingPage('calculator');
      originalPrice = originalP;
      discountPercentage = discountP;
      // console.log(originalPrice, 'originalPrice')
      // console.log(discountPercentage, 'discountPercentage')
      result.originalPrice = originalPrice;
      result.discountPercentage = discountPercentage;
    } else {
      //if targeted element is not there
      originalPrice = 0;
      discountPercentage = 0;
      result.originalPrice = originalPrice;
      result.discountPercentage = discountPercentage;
    }

    //Cost to deliver scrapping

    const costOfDeliverElement = FindByAttributeValue(
      'data-estimated-shipping',
      '',
    );
    //if element is present
    if (costOfDeliverElement !== undefined) {
      const costOfDeliverInnerText =
        costOfDeliverElement?.firstElementChild?.querySelector('p') ||
        costOfDeliverElement?.innerText;

      if (
        costOfDeliverInnerText !== null &&
        costOfDeliverInnerText !== undefined
      ) {
        if (
          (typeof costOfDeliverInnerText == 'string' &&
            costOfDeliverInnerText?.includes('Free')) ||
          costOfDeliverInnerText?.innerText?.includes('Free')
        ) {
          costOfDeliver = 0;
        } else {
          costOfDeliver = costOfDeliverInnerText?.innerText
            ? parseFloat(
                costOfDeliverInnerText?.innerText?.replace(/[^0-9\.-]+/g, ''),
              )
            : parseFloat(costOfDeliverInnerText?.replace(/[^0-9\.-]+/g, ''));
        }
      } else {
        costOfDeliver = 0;
      }
    } else {
      costOfDeliver = 0;
    }
    // scrapping for physical or digital product

    const productTypeElement = FindByAttributeValue(
      'data-listing-page-item-details-component',
      '',
    );
    let productType = '';
    if (productTypeElement !== undefined) {
      const productTypeInnerText =
        productTypeElement.firstElementChild.firstElementChild.innerText;
      if (productTypeInnerText.includes('Digital download')) {
        productType = 'digital';
      } else {
        productType = 'physical';
      }
    } else {
      productType = 'physical';
    }
    result.shippingPrice = !isNaN(costOfDeliver) ? costOfDeliver : 0;
    result.shippingCostOfOrder = productType == 'physical' ? 4.5 : 0;
    result.salesPrice = originalPrice;
    result.discountInAmt = discountPercentage ? discountPercentage : 0;
    result.itemCost =
      productType == 'physical' ? (0.4 * originalPrice).toFixed(2) : 0;
    // console.log(originalPrice, 'salesPrice')
    // console.log(!isNaN(costOfDeliver) ? costOfDeliver : 0, 'shippingPrice')
    // console.log(productType == "physical" ? 4.5 : 0, 'shippingCostOfOrder')
    // console.log(discountPercentage ? discountPercentage : 0, 'discountInAmt')
    // console.log(productType == "physical" ? (0.4 * originalPrice).toFixed(2) : 0, 'itemCost')
    // setInputsCalculator((prev) => ({
    //   ...prev,
    //   salesPrice: originalPrice,
    //   shippingPrice: !isNaN(costOfDeliver) ? costOfDeliver : 0,
    //   shippingCostOfOrder: productType == "physical" ? 4.5 : 0,
    //   discountInAmt: discountPercentage ? discountPercentage : 0,
    //   itemCost:
    //     productType == "physical" ? (0.4 * originalPrice).toFixed(2) : 0,
    // }));

    // setModals((prev) => ({ ...prev, etsyCalculator: true }));
    return result;
  } else {
    // setModals((prev) => ({ ...prev, etsyCalculator: true }));
  }
}
