import styled from 'styled-components';

const StyledWrapper = styled.div`
  height: 68px;
  width: 22%;
  background-color: #f7f7f7;
  font-size: 14px;
  padding-left: 16px;
  padding-top: 12px;
  border-radius: 6px;
  .display-name {
    color: #646566;
  }

  .display-data {
    color: #313233;
  }
`;

const SmallTileItem = ({ displayName, displayData }) => {
  const isNetProfitMargin = displayName === 'Net Profit Margin';
  let isNegative = false;

  if (displayData < 0) {
    isNegative = true;
    displayData = -1 * displayData;
  }

  if (displayName === 'Total Fees + Costs') {
    isNegative = true;
  }

  return (
    <StyledWrapper>
      <div className="display-name">{displayName}</div>
      <div className="display-data">
        {isNegative
          ? `-${!isNetProfitMargin ? '$' : ''}${
              displayName === 'Net Profit'
                ? displayData.toFixed(2)
                : displayData
            }`
          : `${!isNetProfitMargin ? '$' : ''}${displayData}`}
        {isNetProfitMargin && '%'}
      </div>
    </StyledWrapper>
  );
};

export default SmallTileItem;
