import { useState, useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import Button from '@components/Button';
import {
  manageFavItemsInFolders,
  createNewFavFolder,
  setKeywordFolderMgmtModalStatus,
  setKeywordsDefaultFolderData,
  setKeywordsFolderData,
  setListingFolderMgmtModalStatus,
  setListingsDefaultFolderData,
  setListingsFolderData,
  setManagementModalStatus,
  setShopFolderMgmtModalStatus,
  setShopsFolderData,
  setShopsDefaultFolderData,
} from '../../store/slices/favoritesSlice';
import favListingPopup from '@components/FavUpdateToast/Listings/FavPopup';
import favKeywordPopup from '@components/FavUpdateToast/Keywords/FavKeywordPopup';
import favShopPopup from '@components/FavUpdateToast/Shops/FavShopPopup';
import { StyledWrapper } from './StyledWrapper';
import SimpleModal from '../SimpleModal/SimpleModal';
import {
  setIsListingFav,
  setIsNewFavFolderModal,
  updateExtSearchDataIsfav,
  updateSidePaneTagsIsFav,
  updateSidePaneTagsIsFavBulk,
  clearSidePanTagsCheckedRows,
  clearModalTagsCheckedRows,
  setIsShopFav,
} from '../../store/slices/utilitySlice';
import { updateFavoriteCount } from '../../store/slices/userSlice';
import { showFavoriteLimitErrorToast } from '../../utils/favoriteLimitHelpers';

const NewFavFolderModal = ({ row, context, onConfirmSuccess }) => {
  const closeBtn = chrome.runtime.getURL('svg/close-button.svg');

  const dispatch = useDispatch();
  const [newFolderName, setNewFolderName] = useState('My Folder');
  const { isNewFavFolderModal, sidePanTags } = useSelector(
    (state) => state.utilities,
  );
  const bulkKeywordRowsForChange = useSelector(
    (state) => state.utilities.bulkKeywordRowsForChange,
  );
  const bulkKeywordRowsSource = useSelector(
    (state) => state.utilities.bulkKeywordRowsSource,
  );
  const inputRef = useRef(null);

  const handleFolderNameChange = (newValue) => {
    if (newValue.length > 60) {
      return; // limit of 60 characters
    }
    setNewFolderName(newValue);
  };

  const handleClose = () => {
    dispatch(setIsNewFavFolderModal(false));
  };

  const handleCreateNewFolder = () => {
    if (row.listingId) {
      // Handle listing favorites
      let newlyCreatedFolderId;
      let newlyCreatedFolder;

      dispatch(
        createNewFavFolder({ folderName: newFolderName, type: 'listing' }),
      )
        .then((createFolderResponse) => {
          if (createFolderResponse?.payload) {
            newlyCreatedFolderId =
              createFolderResponse?.payload?.data?.folder?.id;
            newlyCreatedFolder = createFolderResponse?.payload?.data?.folder;

            return dispatch(
              manageFavItemsInFolders({
                itemIdsArray: [row.listingId],
                type: 'listing',
                folderIdsArray: [newlyCreatedFolderId],
              }),
            );
          }
          return null;
        })
        .then((addToFolderResponse) => {
          if (addToFolderResponse?.payload) {
            if (context === 'singleListing') {
              dispatch(setIsListingFav(true));
            } else if (context === 'onPageSingleListing') {
              dispatch(
                updateExtSearchDataIsfav({
                  listingId: row.listingId,
                  isFavBool: true,
                }),
              );
            } else if (
              context === 'ImageAndDetails' ||
              context === 'HeadingAndIcons'
            ) {
              dispatch(setIsListingFav(true));
              dispatch(
                updateExtSearchDataIsfav({
                  listingId: row.listingId,
                  isFavBool: true,
                }),
              );
            }

            setTimeout(() => {
              favListingPopup(row, [newlyCreatedFolder], 'add', context);
            }, 1000);

            dispatch(setListingsFolderData([newlyCreatedFolder]));
            dispatch(setListingsDefaultFolderData([newlyCreatedFolder]));
            dispatch(setManagementModalStatus({ itemType: 'listing' }));
            dispatch(setListingFolderMgmtModalStatus(false));
          }
        })
        .finally(() => {
          handleClose();
        });
    } else if (row.keywordId) {
      // Handle keyword favorites
      const isBulk =
        Array.isArray(bulkKeywordRowsForChange) &&
        bulkKeywordRowsForChange.length > 1 &&
        bulkKeywordRowsForChange.some(
          (r) => r?.keywordId === row?.keywordId,
        );
      const itemIdsArray = isBulk
        ? bulkKeywordRowsForChange
            .filter((r) => !r.isFav)
            .map((r) => r.keywordId)
        : [row.keywordId];

      let newlyCreatedFolderId;
      let newlyCreatedFolder;

      dispatch(
        createNewFavFolder({
          folderName: newFolderName,
          type: 'keyword_analytic',
        }),
      )
        .then((createFolderResponse) => {
          if (createFolderResponse?.payload) {
            newlyCreatedFolderId =
              createFolderResponse?.payload?.data?.folder?.id;
            newlyCreatedFolder = createFolderResponse?.payload?.data?.folder;

            return dispatch(
              manageFavItemsInFolders({
                itemIdsArray,
                type: 'keyword_analytic',
                folderIdsArray: [newlyCreatedFolderId],
                idType: 'database',
              }),
            );
          }
          return null;
        })
        .then((addToFolderResponse) => {
          if (newlyCreatedFolder) {
            dispatch(setKeywordsFolderData([newlyCreatedFolder]));
            dispatch(setKeywordsDefaultFolderData([newlyCreatedFolder]));
            dispatch(
              setManagementModalStatus({ itemType: 'keyword_analytic' }),
            );
            dispatch(setKeywordFolderMgmtModalStatus(false));
          }
          if (showFavoriteLimitErrorToast(addToFolderResponse)) {
            if (isBulk) {
              dispatch(
                bulkKeywordRowsSource === 'modal'
                  ? clearModalTagsCheckedRows()
                  : clearSidePanTagsCheckedRows(),
              );
            }
            return;
          }
          if (addToFolderResponse?.payload) {
            if (isBulk) {
              dispatch(
                updateSidePaneTagsIsFavBulk({
                  keywordIds: itemIdsArray,
                  isFavBool: true,
                }),
              );
              dispatch(
                updateFavoriteCount({
                  type: 'keywordCount',
                  amount: itemIdsArray.length,
                }),
              );
              dispatch(
                bulkKeywordRowsSource === 'modal'
                  ? clearModalTagsCheckedRows()
                  : clearSidePanTagsCheckedRows(),
              );

              if (onConfirmSuccess) {
                onConfirmSuccess(bulkKeywordRowsForChange[0], [
                  { name: newlyCreatedFolder.name, id: newlyCreatedFolder.id },
                ]);
              } else {
                setTimeout(() => {
                  favKeywordPopup(
                    bulkKeywordRowsForChange[0],
                    [newlyCreatedFolder],
                    'add',
                  );
                }, 1000);
              }
            } else {
              if (context === 'tags') {
                dispatch(
                  updateSidePaneTagsIsFav({
                    keywordId: row.keywordId,
                    isFavBool: true,
                  }),
                );
              }

              if (onConfirmSuccess) {
                onConfirmSuccess(row, [
                  { name: newlyCreatedFolder.name, id: newlyCreatedFolder.id },
                ]);
              } else {
                setTimeout(() => {
                  favKeywordPopup(row, [newlyCreatedFolder], 'add', context);
                }, 1000);
              }

              dispatch(updateFavoriteCount({ type: 'keywordCount', amount: 1 }));
            }
          }
        })
        .finally(() => {
          handleClose();
        });
    } else if (row.shopId) {
      // Handle shop favorites
      let newlyCreatedFolderId;
      let newlyCreatedFolder;

      dispatch(
        createNewFavFolder({
          folderName: newFolderName,
          type: 'shop',
        }),
      )
        .then((createFolderResponse) => {
          if (createFolderResponse?.payload) {
            newlyCreatedFolderId =
              createFolderResponse?.payload?.data?.folder?.id;
            newlyCreatedFolder = createFolderResponse?.payload?.data?.folder;

            return dispatch(
              manageFavItemsInFolders({
                itemIdsArray: [row.shopId],
                type: 'shop',
                folderIdsArray: [newlyCreatedFolderId],
              }),
            );
          }
          return null;
        })
        .then((addToFolderResponse) => {
          if (addToFolderResponse?.payload) {
            dispatch(setIsShopFav(true));

            setTimeout(() => {
              favShopPopup(row, [newlyCreatedFolder], 'add', context);
            }, 1000);

            dispatch(setShopsFolderData([newlyCreatedFolder]));
            dispatch(setShopsDefaultFolderData([newlyCreatedFolder]));
            dispatch(setManagementModalStatus({ itemType: 'shop' }));
            dispatch(setShopFolderMgmtModalStatus(false));

            dispatch(updateFavoriteCount({ type: 'shopCount', amount: 1 }));
          }
        })
        .finally(() => {
          handleClose();
        });
    }
  };

  useEffect(() => {
    if (isNewFavFolderModal) {
      const focusAndSelect = () => {
        if (inputRef.current?.offsetHeight > 0) {
          window.focus();
          inputRef.current.focus();
          setTimeout(() => inputRef.current?.select(), 10);
          return true;
        }
        return false;
      };

      // Try immediately
      if (focusAndSelect()) return;

      // Set up observer if not ready
      const observer = new MutationObserver(() => {
        if (focusAndSelect()) {
          observer.disconnect();
        }
      });

      observer.observe(document.body, {
        childList: true,
        subtree: true,
      });

      return () => observer.disconnect();
    }
  }, [isNewFavFolderModal]);

  const styleOverridesObj = {
    padding: '0',
    width: '600px',
    borderRadius: '8px',
  };

  return (
    <SimpleModal
      open={isNewFavFolderModal}
      handleClose={handleClose}
      styleOverridesObj={styleOverridesObj}
    >
      <StyledWrapper>
        <div className="heading">
          <span className="heading-text">Create a favorites folder</span>
          <img
            className="close-button"
            src={closeBtn}
            alt="Close button"
            onClick={handleClose}
          />
        </div>
        <div className="input-container">
          <div className="label-input-container">
            <span className="label">Name</span>
            <input
              ref={inputRef}
              className="field-input"
              type="text"
              name="new-folder-name"
              value={newFolderName}
              onChange={(e) => handleFolderNameChange(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && newFolderName.trim()) {
                  handleCreateNewFolder();
                }
              }}
            />
          </div>
        </div>
        <div className="footer">
          <Button
            buttonText="Create"
            backgroundColor="#3d98f2"
            customPadding="8px 20px 8px 20px"
            customWidth="100%"
            customBorderRadius="8px"
            customFontWeight="500"
            customBoxShadow="0 1px 0 0 rgba(255, 255, 255, 0.30) inset, 0 1px 1px 0 rgba(13, 97, 181, 0.80), 0 0 0 1px #3490EC"
            onClick={handleCreateNewFolder}
            disabled={!newFolderName.trim()}
          />
        </div>
      </StyledWrapper>
    </SimpleModal>
  );
};

export default NewFavFolderModal;
