import styled, { keyframes } from 'styled-components';

/* ── Keyframes ────────────────────────────────────────────── */

const shine = keyframes`
  0%   { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
`;

/* ── Shine Overlay ────────────────────────────────────────────
 * The keyframe carries the highlight (the gradient's 50% stop) from half a
 * banner-width left of the element to half a width past its right edge, so it
 * crosses the full width. Do NOT add a static `translateX(-100%)` on top of
 * the animation — the two stack, shifting the sweep a full width left so the
 * highlight dies at the banner's midpoint and the right edge never lights up.
 * `linear` keeps the traverse even end to end; `ease-in-out` crams it into a
 * fast blur through the middle.
 */

export const ShineOverlay = styled.div`
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    105deg,
    rgba(255, 255, 255, 0) 38%,
    rgba(255, 255, 255, 0.28) 50%,
    rgba(255, 255, 255, 0) 62%
  );
  animation: ${shine} 3.5s linear infinite;
`;

/* ── Orange mesh gradient (RESEARCH-3192) ─────────────────────
 * Amber warmth in the top-left, a soft white sheen along the top, and deep
 * brown-orange settling into the bottom-right, over a light -> primary -> dark
 * orange base.
 *
 * The layers are deliberately wide (radii > 100%) and low-alpha so every one
 * fades out past the opposite edge and none of them brightens against the
 * base. Blobs sized by the default `farthest-corner` instead terminate inside
 * the element, which leaves a hard falloff edge where the alpha ramp stops,
 * and a light blob sitting to the right of a dark one reverses brightness
 * partway across and creases the flow. This keeps it monotonic left to right.
 */

const ohoneyMesh = `
  background-color: #f97316;
  background-image:
    radial-gradient(
      120% 180% at 74% 0%,
      rgba(255, 255, 255, 0.1) 0%,
      rgba(255, 255, 255, 0.04) 45%,
      rgba(255, 255, 255, 0) 100%
    ),
    radial-gradient(
      140% 200% at 0% 0%,
      rgba(251, 191, 36, 0.55) 0%,
      rgba(251, 191, 36, 0.18) 38%,
      rgba(251, 191, 36, 0) 78%
    ),
    radial-gradient(
      140% 200% at 100% 100%,
      rgba(156, 70, 18, 0.45) 0%,
      rgba(156, 70, 18, 0.16) 40%,
      rgba(156, 70, 18, 0) 80%
    ),
    linear-gradient(100deg, #ef7d2b 0%, #f97316 48%, #c2410c 100%);
`;

