/* CTA hover: a small lift plus a warm drop shadow, with the arrow nudging
 * forward. The card lifts on hover too, so the button's travel is kept smaller
 * than the card's so the two stay distinguishable. */
const ctaButton = `
  background: #fff;
  color: #c2410c;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  box-shadow: 0 1px 3px rgba(120, 45, 10, 0.25);
  transition:
    color 0.15s,
    box-shadow 0.15s,
    transform 0.15s;

  svg {
    transition: transform 0.15s;
  }

  &:hover {
    color: #9c4612;
    box-shadow: 0 8px 18px rgba(120, 45, 10, 0.4);
    transform: translateY(-2px);

    svg {
      transform: translateX(2px);
    }
  }

  &:active {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(120, 45, 10, 0.3);
  }
`;

