/*global chrome*/
import React, { useEffect } from 'react';
import { useSelector } from 'react-redux';
import * as amplitude from '@amplitude/analytics-browser';
import Graph from '../DailyTrends/Graph/Graph';
import { StyledWrapper } from './StyledWrapper';
import SimpleModal from '../SimpleModal/SimpleModal';
import { getEventData } from '../../utils/eventData';
import { decodeHTMLEntities } from '../../utils/decodeHTMLText';

const SidebarTrendsModal = ({ handleClose }) => {
  const closeBtn = chrome.runtime.getURL('svg/close-button.svg');

  const { isSidebarTrendsModal, listingDetailsData } = useSelector(
    (state) => state.utilities,
  );
  let UrlLink = window.location.href;
  const { userData } = useSelector((state) => state.user);

  useEffect(() => {
    const eventData = getEventData({
      UrlLink,
      datePickerExplicitWidth: false,
      listingName: listingDetailsData?.title,
      extraProps: {},
    });
    eventData && amplitude.track('Expand_View', eventData);
  }, []);

  const handleKeyDown = (e) => {
    if (e.key === 'Escape') handleClose();
  };

  return (
    <SimpleModal
      open={isSidebarTrendsModal}
      handleClose={handleClose}
      sidebarTrendsModal={true}
      styleOverridesObj={{ padding: '0px !important' }}
    >
      <StyledWrapper
        onKeyDown={handleKeyDown}
        $hideDetails={userData?.hide_details}
      >
        <div className="header">
          <div className="header-content">
            <img
              className="header-img"
              src={listingDetailsData.image}
              width={100}
              height={100}
              alt="trends header image"
            />
            <div className="header-text-wrapper">
              <div className="header-text">
                <div className="trend-title">
                  <span className="trend-text">Trends</span>
                  {/* <span className="trend-beta-badge">Beta</span> */}
                </div>
                <div className="content-title">
                  {decodeHTMLEntities(listingDetailsData.title)}
                </div>
              </div>
            </div>
          </div>
          <img
            className="btn-close"
            src={closeBtn}
            alt="Close button"
            onClick={handleClose}
          />
        </div>
        <div className="main-content">
          <Graph
            listingName={listingDetailsData.title}
            datePickerExplicitWidth={'380px'}
            details={listingDetailsData}
            currencySymbol={listingDetailsData?.currencySymbol}
          />
        </div>
      </StyledWrapper>
    </SimpleModal>
  );
};

export default SidebarTrendsModal;
