/*global chrome*/
import React, { useEffect, useState } from 'react';
import { Modal, Typography } from '@mui/material';
import { useSelector, useDispatch } from 'react-redux';
import { getTrueKey } from '../../helper/getTrueKey';
import {
  changeFeaturePage,
  changeIframeUrl,
} from '../../store/slices/sidebarSlice';
import { MinimizedWrapper } from './StyledWrapper';
import { seperatedCamelCase } from '../../helper/seperatedcamelCase';
const MinimizedComponent = ({ setIsMinimized, handleUrlCleanup }) => {
  const [activeRouteName, setActiveRouteName] = useState('');
  const dispatch = useDispatch();
  const close = chrome.runtime.getURL('svg/cross.svg');
  const maximize = chrome.runtime.getURL('svg/maxi.svg');
  const currentFeaturePage = useSelector((state) => state.sidebar.featurePage);
  const truekey = getTrueKey(currentFeaturePage);
  const iframeUrl = useSelector((state) => state.sidebar.iframeUrl);

  useEffect(() => {
    const parts = iframeUrl.split('/');
    const extIndex = parts.indexOf('ext');
    if (extIndex !== -1 && extIndex + 1 < parts.length) {
      const extractedSegment = parts[extIndex + 1];
      const truekey = seperatedCamelCase(extractedSegment);
      setActiveRouteName(truekey);
    }
  }, [iframeUrl]);

  return (
    <>
      <Modal
        disableEnforceFocus
        // Same as MainExtScreen: never let MUI scroll-lock Etsy's <body>.
        disableScrollLock
        open={true}
        aria-labelledby="modal-modal-title"
        hideBackdrop={true}
        aria-describedby="modal-modal-description"
        sx={{
          width: 'calc(100vw-72px)',
          height: '25vh',
          marginLeft: '72px',
          overflowX: 'hidden',
          overflowY: 'hidden',
          top: '85vh',
          right: '17px',
          left: '15px',
          transition: 'top 0.7s linear 0s,height  0.7s linear 0s',
          backgroundColor: ' rgba(204, 204, 204, 0.6)',
          border: 'none',
          borderRadius: '15px 15px 0px 0px',
          backdropFilter: 'blur(10px)',
          display: iframeUrl.includes('/ext/') ? 'block' : 'none',
        }}
      >
        <MinimizedWrapper
          onClick={() => {
            setIsMinimized(false);
            document.body.style.overflowY = 'hidden';
          }}
        >
          <div style={{ display: 'flex', margin: '24px' }}>
            <Typography
              fontSize="24px"
              fontWeight="500"
              lineHeight="32.4px"
              color="rgba(25, 25, 26, 1)"
            >
              {currentFeaturePage?.loginPage ? truekey : activeRouteName}
            </Typography>
          </div>
          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
            <div>
              <div
                style={{
                  display: 'flex',
                  gap: '9px',
                  padding: '5px',
                  margin: '15px',
                }}
              >
                <div
                  className="btn-minimize eb-cta-button"
                  onClick={() => {
                    setIsMinimized(false);
                    document.body.style.overflowY = 'hidden';
                  }}
                >
                  <img src={maximize} />
                </div>
                <div
                  className="btn-close eb-cta-button"
                  onClick={() => {
                    setIsMinimized(false);
                    handleUrlCleanup();
                    dispatch(changeFeaturePage());
                    dispatch(changeIframeUrl('close'));
                  }}
                >
                  <img src={close} />
                </div>
              </div>
            </div>
          </div>
        </MinimizedWrapper>
      </Modal>
    </>
  );
};
export default MinimizedComponent;
