/*global chrome*/
import React, { useState, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useGridApiRef } from '@mui/x-data-grid-pro';
import { AnimatePresence, motion } from 'framer-motion';
import TagsTable from '../TagsTable/TagsTable';
import SimpleModal from '../SimpleModal/SimpleModal';
import { TagsTableColumns } from '../../utils/columns/tagsColumn';
import { StyledWrapper } from './StyledWrapper';
import * as amplitude from '@amplitude/analytics-browser';
import {
  setIsNewFavFolderModal,
  updateSidePaneTagsIsFav,
  updateModalTagsCheckedRows,
  clearModalTagsCheckedRows,
  toggleRemoveFromFavConfirmModal,
} from '../../store/slices/utilitySlice';
import {
  manageFavItemsInFolders,
  fetchFoldersContainingPL,
  toggleKeywordsWatchlistModal,
  setKeywordFolderMgmtModalStatus,
  setCurrentKeywordRowData,
  unfavouritePLFromFav,
} from '../../store/slices/favoritesSlice';
import NewFavFolderModal from '../NewFavFolderModal';
import FavKeywordUpdateToast from '../FavUpdateToast/Keywords/FavKeywordUpdateToast';
import { KeywordsWatchlistModal } from '../WatchlistModal';
import { updateFavoriteCount } from '../../store/slices/userSlice';
import KeywordSelectedRow from '../SelectedRowToolbar/KeywordSelectedRow';

const animationOptions = {
  initialOptions: {
    opacity: 0,
  },
  animateOptions: {
    opacity: 1,
  },
  exitOptions: {
    opacity: 0,
  },
};

const TagsModal = ({ handleClose, isAuth }) => {
  const dispatch = useDispatch();
  const apiRef = useGridApiRef();
  const bannerTimeoutRef = useRef(null);
  const CloseButton = chrome.runtime.getURL('svg/close-button.svg');
  const Tick = chrome.runtime.getURL('svg/green-tick.svg');
  const copyIcon = chrome.runtime.getURL('svg/copy.svg');
  const [tagsCopied, setTagsCopied] = useState(false);
  const [isFavBanner, setIsFavBanner] = useState(false);
  const [favBannerData, setFavBannerData] = useState({
    row: null,
    folderDetailsArray: [],
    action: '',
    errorMessage: '',
  });
  const [favBannerKey, setFavBannerKey] = useState(0);

  const {
    isTagsModal,
    sidePanTags,
    rightPaneLoading,
    isNewFavFolderModal,
    modalTagsCheckedRowIds,
    modalTagsCheckedRowsData,
  } = useSelector((state) => state.utilities);
  const {
    keywordsFolderData,
    keywordsDefaultFolderData,
    isKeywordsWatchlistModal,
    currentKeywordRowData,
  } = useSelector((state) => state.watchlist);
  const isKeywordFolderManagement = useSelector(
    (state) => state.watchlist.folderManagementModalStatus.keyword,
  );

  const defaultFolderDetails = keywordsDefaultFolderData.map((folder) => ({
    name: folder.name,
    id: folder.id,
  }));

  const showFavBanner = (row, folderDetailsArray, action) => {
    // Clear any existing timeout
    if (bannerTimeoutRef.current) {
      clearTimeout(bannerTimeoutRef.current);
    }

    setFavBannerData({ row, folderDetailsArray, action, errorMessage: '' });
    setIsFavBanner(true);
    setFavBannerKey((prev) => prev + 1);

    bannerTimeoutRef.current = setTimeout(() => {
      setIsFavBanner(false);
      bannerTimeoutRef.current = null;
    }, 5000);
  };

  const showFavErrorBanner = (errorMessage) => {
    if (bannerTimeoutRef.current) {
      clearTimeout(bannerTimeoutRef.current);
    }

    setFavBannerData({
      row: null,
      folderDetailsArray: [],
      action: '',
      errorMessage,
    });
    setIsFavBanner(true);
    setFavBannerKey((prev) => prev + 1);

    bannerTimeoutRef.current = setTimeout(() => {
      setIsFavBanner(false);
      bannerTimeoutRef.current = null;
    }, 5000);
  };

  const handleUndoCallback = (row, folderDetailsArray) => {
    showFavBanner(row, folderDetailsArray, 'add');
  };

  const copyAllTags = () => {
    if (rightPaneLoading) return;
    setTagsCopied(true);
    navigator.clipboard.writeText(
      sidePanTags?.map((item) => item.keywords).join(', '),
    );

    amplitude.track('Tags_Copy', {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      tags_copy_type: 'all',
      keyword_name: sidePanTags.map((item) => item.keywords),
      source_type: 'expand_view',
    });
    setTimeout(() => {
      setTagsCopied(false);
    }, 800);
  };

  const handleModalClose = () => {
    dispatch(clearModalTagsCheckedRows());
    dispatch(toggleRemoveFromFavConfirmModal(false));
    if (bannerTimeoutRef.current) clearTimeout(bannerTimeoutRef.current);
    setIsFavBanner(false);
    handleClose?.();
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Escape') handleModalClose();
  };

  const handleRowSelectionChange = (model) => {
    const rowIds = Array.isArray(model) ? model : [...model];
    const rowsData = (sidePanTags || []).filter((row) =>
      rowIds.includes(row.id),
    );
    dispatch(updateModalTagsCheckedRows({ rowIds, rowsData }));
    if (rowIds.length > 0 && isFavBanner) {
      if (bannerTimeoutRef.current) clearTimeout(bannerTimeoutRef.current);
      setIsFavBanner(false);
    }
  };

  const handleAfterToolbarAction = () => {
    dispatch(clearModalTagsCheckedRows());
  };

  const handleWatchlistConfirmSuccess = (row, folderDetailsArray) => {
    showFavBanner(row, folderDetailsArray, 'add');
    handleAfterToolbarAction();
  };

  const handleBulkFavSuccess = (rowsData, folderDetails, action) => {
    if (!rowsData || rowsData.length === 0) return;
    showFavBanner(rowsData[0], folderDetails, action);
  };

  const trackFavoritesEvent = (eventName, additionalProps = {}) => {
    amplitude.track(eventName, {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      source_type: 'expand_view',
      item_type: 'keyword',
      ...additionalProps,
    });
  };

  const handleTagsFavoriteClick = async (e, row) => {
    e.stopPropagation();
    dispatch(setCurrentKeywordRowData(row));

    if (row.isFav) {
      // Unfavorite logic
      const response = await dispatch(
        fetchFoldersContainingPL({
          itemIdsArray: [row.keywordId],
          type: 'keyword_analytic',
          idType: 'database',
        }),
      ).unwrap();

      const folderIdsFromResponse =
        response?.data?.items?.flatMap((item) => item.folder_ids) || [];

      const folderDetails = keywordsFolderData
        .filter((folder) => folderIdsFromResponse.includes(folder.id))
        .map((folder) => ({
          name: folder.name,
          id: folder.id,
        }));

      await dispatch(
        unfavouritePLFromFav({
          itemId: row.keywordId,
          type: 'keyword_analytic',
          idType: 'database',
        }),
      ).unwrap();

      showFavBanner(row, folderDetails, 'undo');

      // Update the isFav status in the tags data
      dispatch(
        updateSidePaneTagsIsFav({
          keywordId: row.keywordId,
          isFavBool: false,
        }),
      );

      dispatch(updateFavoriteCount({ type: 'keywordCount', amount: -1 }));

      trackFavoritesEvent('Favorites_Remove_Click');
    } else {
      // Favorite logic
      const defaultFolderIds = keywordsDefaultFolderData.map(
        (folder) => folder.id,
      );

      if (keywordsFolderData.length === 0) {
        trackFavoritesEvent('Add_To_Favorites_Click', {
          is_first_favorites_action_of_day: true,
        });
        dispatch(setIsNewFavFolderModal(true));
      } else if (isKeywordFolderManagement || defaultFolderIds.length === 0) {
        dispatch(toggleKeywordsWatchlistModal(true));
        if (isKeywordFolderManagement) {
          trackFavoritesEvent('Add_To_Favorites_Click', {
            is_first_favorites_action_of_day: true,
          });
          dispatch(setKeywordFolderMgmtModalStatus(false));
        }
      } else {
        trackFavoritesEvent('Add_To_Favorites_Click', {
          target_folders_count: defaultFolderIds.length,
          is_first_favorites_action_of_day: false,
        });

        await dispatch(
          manageFavItemsInFolders({
            itemIdsArray: [row.keywordId],
            type: 'keyword_analytic',
            folderIdsArray: defaultFolderIds,
            idType: 'database',
          }),
        ).unwrap();

        showFavBanner(row, defaultFolderDetails, 'add');

        // Update the isFav status in the tags data
        dispatch(
          updateSidePaneTagsIsFav({
            keywordId: row.keywordId,
            isFavBool: true,
          }),
        );

        dispatch(updateFavoriteCount({ type: 'keywordCount', amount: 1 }));
      }
    }
  };

  return (
    <SimpleModal open={isTagsModal} handleClose={handleModalClose} tagsModal={true}>
      <StyledWrapper onKeyDown={handleKeyDown}>
        <div className="header">
          <div className="btn-wrapper" style={{ visibility: modalTagsCheckedRowIds.length > 0 ? 'hidden' : 'visible' }}>
            {tagsCopied ? (
              <AnimatePresence>
                {
                  <motion.div
                    variants={animationOptions}
                    initial="initialOptions"
                    animate="animateOptions"
                    exit="exitOptions"
                    transition={{
                      duration: 0.3,
                    }}
                  >
                    <img
                      src={Tick}
                      alt="green-tick-icon"
                      height={16}
                      width={16}
                    />
                  </motion.div>
                }
              </AnimatePresence>
            ) : (
              <img
                className="btn-copy"
                src={copyIcon}
                alt="Copy button"
                onClick={copyAllTags}
              />
            )}
            <img src={CloseButton} alt="Close Button" onClick={handleModalClose} />
          </div>
          {modalTagsCheckedRowIds.length > 0 && (
            <KeywordSelectedRow
              noOfCheckedRows={modalTagsCheckedRowIds.length}
              sourceProp="sp-ta"
              sourceContext="expand_view"
              onFavSuccess={handleBulkFavSuccess}
              onFavError={showFavErrorBanner}
              onAfterAction={handleAfterToolbarAction}
              inline={true}
              stateSource="modal"
            />
          )}
        </div>
        <AnimatePresence>
          {isFavBanner &&
            (favBannerData.row || favBannerData.errorMessage) && (
              <motion.div
                key={favBannerKey}
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.3, ease: 'easeOut' }}
                style={{ overflow: 'hidden', width: '100%' }}
              >
                <FavKeywordUpdateToast
                  row={favBannerData.row}
                  folderDetailsArray={favBannerData.folderDetailsArray}
                  action={favBannerData.action}
                  errorMessage={favBannerData.errorMessage}
                  onClose={() => setIsFavBanner(false)}
                  isModal={true}
                  onUndoSuccess={handleUndoCallback}
                />
              </motion.div>
            )}
        </AnimatePresence>
        <div className="content">
          <TagsTable
            apiRef={apiRef}
            tableData={sidePanTags}
            tableColumns={TagsTableColumns(
              rightPaneLoading,
              isTagsModal,
              handleTagsFavoriteClick,
              isAuth,
            )}
            loading={rightPaneLoading}
            tableType="tagsTableModal"
            checkboxSelection={true}
            onRowSelectionModelChange={handleRowSelectionChange}
            rowSelectionModel={modalTagsCheckedRowIds}
          />
        </div>

        {isNewFavFolderModal && currentKeywordRowData && (
          <NewFavFolderModal
            row={currentKeywordRowData}
            context="tags"
            onConfirmSuccess={handleWatchlistConfirmSuccess}
          />
        )}

        {isKeywordsWatchlistModal && (
          <KeywordsWatchlistModal
            row={currentKeywordRowData}
            context="tags"
            onConfirmSuccess={handleWatchlistConfirmSuccess}
            bulkRowsData={modalTagsCheckedRowIds.length > 0 ? modalTagsCheckedRowsData : undefined}
          />
        )}
      </StyledWrapper>
    </SimpleModal>
  );
};

export default TagsModal;
