import StyledWrapper from './StyledWrapper';

/**
 * Sizes can only be - small | medium | large
 */

const Button = ({
  buttonText,
  size = 'medium',
  customPadding = null,
  customFontSize = null,
  onClick,
  textColor = '#FFFFFF',
  backgroundColor = '#0e59ef',
  customBoxShadow,
  customWidth,
  customBorder,
  customBorderRadius,
  customFontWeight,
  customMargin,
  disabled,
}) => {
  return (
    <StyledWrapper
      size={size}
      customPadding={customPadding}
      customWidth={customWidth}
      customMargin={customMargin}
      customFontSize={customFontSize}
      onClick={onClick}
      textColor={textColor}
      backgroundColor={backgroundColor}
      customBoxShadow={customBoxShadow}
      customBorder={customBorder}
      customBorderRadius={customBorderRadius}
      customFontWeight={customFontWeight}
      disabled={disabled && disabled}
    >
      {buttonText}
    </StyledWrapper>
  );
};

export default Button;
