import React from 'react';
import { createRoot } from 'react-dom/client';
import ReduxProvider from './providers/ReduxProvider';
import App from './App';
import { makeid } from './helper/getRandomID';
import './index.css';
// The px build, deliberately: etsy.com sets a 10.67px root font-size, so the
// rem stylesheet — which the web app uses — would render the rail at ~67%.
import 'everbee-research-sidebar/styles.css';
import {
  createTheme,
  ThemeProvider as MUIThemeProvider,
} from '@mui/material/styles';
import ThemeProvider from './providers/ThemeProvider';
import StyledToastContainer from './components/StyledToastContainer/StyledToastContainer';
import { Toaster } from 'sonner';
import { initTagFilter } from './helper/tagFilter';

window.onerror = (e) => console.log(e);

// Dynamic listing tag filter — only mounts on Etsy search pages.
// Self-contained module; see src/helper/tagFilter.js.
try {
  initTagFilter();
} catch (e) {
  // Never break the extension if the filter fails to initialise.
  console.warn('[EverBee] tagFilter init failed', e);
}

const body = document?.querySelector('body');
const id = makeid();
const app = document?.createElement('div');
app.id = id;
app.setAttribute('data-everbee-app', '');
if (body) {
  body.prepend(app);
}
const root = createRoot(document?.getElementById(id));
const theme = createTheme({
  palette: {
    mode: 'light', // or 'dark'
  },

  // other theme configuration
});

root.render(
  // <React.StrictMode>
  <ReduxProvider>
    <ThemeProvider>
      <MUIThemeProvider theme={theme}>
        <App />
        <StyledToastContainer />
        <Toaster />
      </MUIThemeProvider>
    </ThemeProvider>
  </ReduxProvider>,
  // </React.StrictMode>,
);
