/*global chrome*/
import React, { useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import { Skeleton, Divider } from '@mui/material';
import * as amplitude from '@amplitude/analytics-browser';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { getNumberWithCommas } from '../../../helper/getNumberWithCommas';
import DateRangePicker from '../DateRangePicker';
import { StyledWrapper } from './StyledWrapper';
import { getEventData } from '../../../utils/eventData';

const Graph = ({
  currencySymbol,
  details,
  listingName,
  datePickerExplicitWidth,
}) => {
  const emptyGraph = chrome.runtime.getURL('svg/empty-graph.svg');
  const redDown = chrome.runtime.getURL('svg/red-down.svg');
  const greenUp = chrome.runtime.getURL('svg/green-up.svg');
  let UrlLink = window.location.href;

  const timeoutId = useRef(null);
  const [selectedTab, setSelectedTab] = useState('Sales');
  const { dailyTrendsSales, rightPaneLoading, timeRange } = useSelector(
    (state) => state.utilities,
  );
  const userData = useSelector((state) => state.user.userData);

  let trendGraphData = dailyTrendsSales?.trendsData?.map((item) => ({
    date: item?.date,
    sales: item?.total_sales,
    revenue: item?.total_sales * details?.price,
  }));

  const daysOrMonths =
    timeRange === 'last_30_days' ||
    timeRange === 'last_3_months' ||
    timeRange == 'last_1_month'
      ? 'Days'
      : 'Months';

  if (trendGraphData?.every((item) => item.sales === 0)) {
    trendGraphData = [];
  }
  const isHobbyPlan = userData.current_plan === 'hobby';

  const TABS = [
    {
      tabName: 'Sales',
      val: isHobbyPlan
        ? 4250
        : dailyTrendsSales.trendsData
          ? details.monthlySalesNC
          : 0,
    },
    {
      tabName: 'Revenue',
      val: isHobbyPlan
        ? 1240
        : dailyTrendsSales?.trendsData
          ? details.monthlyRevenueNC
          : 0,
    },
    // {
    //   tabName: 'Growth rate',
    //   val: 23,
    // },
  ];

  const METRICS = [
    {
      tabName: 'Growth Rate',
      subTabName: 'Rate of change for the selected period',
      val: details?.growthRate,
      hobbyVal: '+81',
    },
  ];

  const handleMouseEnter = () => {
    if (!timeoutId.current) {
      timeoutId.current = setTimeout(() => {
        const eventData = getEventData({
          UrlLink,
          datePickerExplicitWidth,
          listingName: details?.title,
          extraProps: {
            metric_type: selectedTab?.toLowerCase(),
          },
        });
        amplitude.track('Graph_Hover', eventData);
        timeoutId.current = null; // Reset so it can fire again next time
      }, 2000);
    }
  };

  const handleMouseLeave = () => {
    if (timeoutId.current) {
      clearTimeout(timeoutId.current);
      timeoutId.current = null;
    }
  };

  const roundNumber = (data) => {
    if (data.tabName === 'Sales') {
      return getNumberWithCommas(Math.round(Number(data.val)));
    } else if (data.tabName === 'Revenue') {
      const roundedNumber = Number(Number(data.val).toFixed(2));
      let roundedString = roundedNumber.toString();
      const seperatedNumberArray = roundedString.split('.');
      const numberWithComma = getNumberWithCommas(seperatedNumberArray[0]);
      seperatedNumberArray[0] = numberWithComma;
      return currencySymbol + seperatedNumberArray.join('.');
    } else if (data.tabName === 'Growth rate') {
      return `${Math.round(data.val)}%`;
    } else return data.val;
  };

  const getMaxValue = (type) => {
    if (dailyTrendsSales && dailyTrendsSales.trendsData) {
      const sales = dailyTrendsSales.trendsData.map(
        (item) => item?.total_sales,
      );
      if (type === 'Sales') {
        return Math.max(...sales) === 0 ? 4 : Math.max(...sales);
      } else if (type === 'Revenue') {
        const revenue = sales.map((sale) => sale * details?.price);
        return Math.max(...revenue) === 0 ? 400 : Math.max(...revenue);
      }
    }
    return 0;
  };

  const formatMonthDate = (date, daysOrMonths) => {
    if (!date) return '';
    const regex = /^\d{4}-\d{2}-\d{2}$/; // YYYY-MM-DD format

    if (regex.test(date)) {
      const [year, month, day] = date.split('-');

      const formattedDateMonthYear = new Date(
        Date.UTC(year, month - 1, day),
      ).toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        timeZone: 'UTC', // Enforce UTC to avoid timezone shifts
      });

      const formattedMonthYear = new Date(
        Date.UTC(year, month - 1, day),
      ).toLocaleDateString('en-US', {
        month: 'short',
        timeZone: 'UTC', // Enforce UTC to avoid timezone shifts
      });

      const formattedDate =
        daysOrMonths === 'Days' ? formattedDateMonthYear : formattedMonthYear;

      return `${formattedDate}, '${year.slice(-2)}`; // Extract last 2 digits of the year
    } else {
      return '';
    }
  };

  const nextMultipleOfFour = (val) => {
    // this function returns the next multiple of 4 from the given number
    return val + ((4 - (val % 4)) % 4);
  };

  return (
    <StyledWrapper
      $metricValue={details?.growthRate}
      $datePickerExplicitWidth={datePickerExplicitWidth}
    >
      <div className="sub-heading-container">
        <div className="calendar_select">
          <DateRangePicker datePickerExplicitWidth={datePickerExplicitWidth} />
          {datePickerExplicitWidth && (
            <>
              <Divider
                orientation="vertical"
                fullWidth
                flexItem
                sx={{
                  '&.MuiDivider-fullWidth': {
                    margin: '0px 10px 0px 20px !important',
                  },
                }}
              />
              <div className="metric-body">
                {METRICS.map((metric, index) => (
                  <div key={index} className="metric-container">
                    <div className="metric-heading" key={metric.tabName}>
                      <span className="metric-heading">{metric.tabName}</span>
                      <span className="metric-subheading">
                        {metric.subTabName}
                      </span>
                    </div>
                    <div>
                      {rightPaneLoading ? (
                        <Skeleton animation="wave" height={45} width={72} />
                      ) : (
                        <div className="metrics-value">
                          {metric?.val > 0
                            ? `${metric.val}%`
                            : `${Math.abs(metric.val)}%`}
                          {metric.val > 0 && (
                            <img src={greenUp} alt="green-up" />
                          )}
                          {metric.val < 0 && (
                            <img src={redDown} alt="red-down" />
                          )}
                        </div>
                      )}
                      <div></div>
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
          {/* {datePickerExplicitWidth && (
            <div className="timeframe-indicator">{daysOrMonths}</div>
          )} */}
        </div>
      </div>
      {!datePickerExplicitWidth && (
        <div style={{ width: '100%' }}>
          {METRICS.map((metric, index) => (
            <div key={index} className="metric-container">
              <div className="metric-heading" key={metric.tabName}>
                <span className="metric-heading">{metric.tabName}</span>
                <span className="metric-subheading">{metric.subTabName}</span>
              </div>
              <div>
                {rightPaneLoading ? (
                  <Skeleton animation="wave" height={45} width={72} />
                ) : (
                  <div
                    className={`metrics-value${
                      userData?.current_plan === 'hobby' ? '-hobby' : ''
                    }`}
                  >
                    {userData?.current_plan === 'hobby' ? (
                      <>
                        {metric?.hobbyVal}{' '}
                        {<img src={greenUp} alt="green-up" />}
                      </>
                    ) : (
                      <>
                        {metric?.val > 0 && metric?.val !== undefined
                          ? `${metric.val}%`
                          : `${Math.abs(metric.val)}%`}
                        {metric.val > 0 && <img src={greenUp} alt="green-up" />}
                        {metric.val < 0 && <img src={redDown} alt="red-down" />}
                      </>
                    )}
                  </div>
                )}
                <div></div>
              </div>
            </div>
          ))}
        </div>
      )}
      <div className="select_tabs_wrapper">
        {TABS.map((tab) => (
          <div key={tab.tabName} className="tab">
            <div
              className={`tab_left ${
                tab.tabName === selectedTab && 'selected_tab'
              }`}
              onClick={() => setSelectedTab(tab.tabName)}
            >
              <div className="tab_name">{tab.tabName}</div>
              {rightPaneLoading ? (
                <Skeleton
                  animation="wave"
                  height={35}
                  width={80}
                  sx={{ marginTop: '-12px' }}
                />
              ) : (
                <div className="tab_value">{roundNumber(tab)}</div>
              )}
            </div>
          </div>
        ))}
      </div>

      {rightPaneLoading ? (
        <Skeleton
          variant="rounded"
          animation="wave"
          height={230}
          width={'100%'}
          sx={{ marginBottom: '8px' }}
        />
      ) : trendGraphData?.length === 0 && userData.current_plan !== 'hobby' ? (
        <div className="no-graph-data">
          <div className="empty-content">
            <img src={emptyGraph} alt="empty graph logo" />
            <div className="nothing-head">Nothing to show</div>
            <div className="nothing-text">
              There is no data for the selected period.
            </div>
          </div>
        </div>
      ) : (
        <div
          className="graph_wrapper"
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
          style={{
            marginLeft: selectedTab === 'Sales' ? '-30px' : '-15px', // Cleaned up syntax
          }}
        >
          <ResponsiveContainer width="100%" height={230}>
            <AreaChart
              data={
                isHobbyPlan
                  ? [
                      {
                        date: '2025-02-01',
                        sales: 27,
                        revenue: 27 * details?.price,
                      },
                      {
                        date: '2025-02-10',
                        sales: 29,
                        revenue: 29 * details?.price,
                      },
                      {
                        date: '2025-02-20',
                        sales: 25,
                        revenue: 25 * details?.price,
                      },
                      {
                        date: '2025-02-28',
                        sales: 81,
                        revenue: 81 * details?.price,
                      },
                    ]
                  : trendGraphData
              }
            >
              <CartesianGrid stroke="transparent" />
              <XAxis
                dataKey="date"
                tickFormatter={(val) => formatMonthDate(val, daysOrMonths)}
                type="category" // Ensures the dates are treated as categories
                tick={{ fontSize: 10, fill: '#373d3f', fontWeight: '600' }}
                ticks={
                  trendGraphData?.length > 0
                    ? trendGraphData?.length == 2
                      ? [
                          trendGraphData[0]?.date, // Start
                          trendGraphData[trendGraphData.length - 1]?.date, // End
                        ]
                      : trendGraphData?.length == 1
                        ? [
                            trendGraphData[0]?.date, // Start
                          ]
                        : [
                            trendGraphData[0]?.date, // Start
                            trendGraphData[
                              Math.floor(trendGraphData.length / 3)
                            ]?.date, // 1/3rd point
                            trendGraphData[
                              Math.floor((trendGraphData.length * 2) / 3)
                            ]?.date, // 2/3rd point
                            trendGraphData[trendGraphData.length - 1]?.date, // End
                          ]
                    : []
                }
              />
              {(() => {
                const maxValue =
                  selectedTab === 'Sales'
                    ? nextMultipleOfFour(getMaxValue('Sales'))
                    : nextMultipleOfFour(getMaxValue('Revenue'));

                const step = Math.ceil(maxValue / 5); // Divide into 5 intervals
                const roundedStep =
                  step < 100 ? step : Math.round(step / 100) * 100;
                const ticks = Array.from(
                  { length: 6 },
                  (_, i) => roundedStep * i,
                );

                return (
                  <YAxis
                    domain={[0, maxValue]}
                    ticks={ticks}
                    tickFormatter={(val) =>
                      selectedTab === 'Revenue'
                        ? `${currencySymbol}${getNumberWithCommas(val)}`
                        : getNumberWithCommas(val)
                    }
                    tick={{ fontSize: 10, fill: '#373d3f', fontWeight: '600' }}
                  />
                );
              })()}
              <Tooltip
                content={({ payload, label }) => {
                  if (payload && payload.length) {
                    const value = payload[0].value;
                    return (
                      <div
                        style={{
                          width: '200px',
                          background: '#fff',
                          borderRadius: '6px',
                          boxShadow: `
                            0 4px 8px rgba(0, 0, 0, 0.1), 
                            0px 20px 25px -8px rgba(0, 0, 0, 0.06), 
                            0px 8px 10px -6px rgba(0, 0, 0, 0.08), 
                            0px 0px 0px 1px rgba(0, 0, 0, 0.06)
                          `,
                        }}
                      >
                        <p
                          style={{
                            padding: '10px',
                            margin: '0',
                            fontWeight: 'bold',
                            color: '#333',
                          }}
                        >
                          {selectedTab}
                        </p>
                        <div
                          style={{
                            width: '100%',
                            height: '1px',
                            background: '#F0F0F0',
                          }}
                        ></div>
                        <div
                          style={{
                            padding: '10px 20px 10px 10px',
                            margin: 0,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                          }}
                        >
                          <div
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              gap: '6px',
                            }}
                          >
                            <div
                              style={{
                                width: '8px',
                                height: '8px',
                                borderRadius: '50%',
                                border: '1.5px solid #3D98F2',
                                background: '#fff',
                              }}
                            ></div>
                            <p
                              style={{
                                color: '#646566',
                              }}
                            >
                              {formatMonthDate(label, daysOrMonths)}
                            </p>
                          </div>
                          <p
                            style={{
                              color: '#19191A',
                              fontWeight: 600,
                            }}
                          >
                            {selectedTab === 'Revenue' ? currencySymbol : ''}
                            {selectedTab === 'Revenue'
                              ? getNumberWithCommas(Math.round(value))
                              : value}{' '}
                            {selectedTab === 'Growth rate' ? '%' : ''}
                          </p>
                        </div>
                      </div>
                    );
                  }
                  return null;
                }}
              />
              <Area
                type="monotone"
                dataKey={selectedTab === 'Sales' ? 'sales' : 'revenue'}
                stroke="#2E8AE5"
                fill="#2E8AE5"
                fillOpacity={0.3}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      )}
    </StyledWrapper>
  );
};

export default Graph;
