export const getSingleListingDetails = createAsyncThunk(
  'utilitySlice/getSingleListingDetails',
  async (
    {
      listingId,
      listingDetails,
      listingAnalytics,
      listingTagAnalytics,
      listingShop,
      updateOnlyTrends,
      timeRange,
    },
    thunkAPI,
  ) => {
    try {
      const response = await getSingleListingDetailsAPI(
        listingId,
        listingDetails,
        listingAnalytics,
        listingTagAnalytics,
        listingShop,
        timeRange,
      );
      return response.data;
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

