export const utilitySlice = createSlice({
  name: 'utilities',
  initialState,
  reducers: {
    updateChecklistProgress: (state, action) => {
      state.onboardingChecklist.checklistProgress = action.payload;
    },
    updateChecklistData: (state, action) => {
      state.onboardingChecklist.checklistData = action.payload;
    },
    updateGraphData: (state, action) => {
      state.graph = action.payload;
    },
    updateTilesData: (state, action) => {
      state.tiles.tileData = action.payload;
    },
    changeTileSelected: (state, actions) => {
      state.tiles.dashboard.tileSelected = actions.payload;
    },
    toggleTilesVisible: (state) => {
      state.tiles.productAnalytics.tilesVisible =
        !state.tiles.productAnalytics.tilesVisible;
    },
    setActivePage: (state, actions) => {
      state.page.activePage = actions.payload;
    },
    setConnectShop: (state, actions) => {
      state.shopConnection = actions.payload;
    },
    setEtsyConnection: (state, actions) => {
      state.etsyConnection = actions.payload;
    },
    changeEtsyCalculatorType: (state, { payload }) => {
      state.etsyCalculatorType = payload;
    },
    openToggleBox: (state, actions) => {
      state.MUItoggleBox.showToggleBox = {
        ...state.showToggleBox,
        [actions.payload]: true,
      };
    },
    closeToggleBox: (state, actions) => {
      state.MUItoggleBox.showToggleBox = {
        ...state.showToggleBox,
        [actions.payload]: false,
      };
    },
    changeActiveDiscountUnit: (state, { payload }) => {
      state.activeDiscountUnit = payload;
    },
    changeEtsyAdUnit: (state, { payload }) => {
      state.activeEtsyAdUnit = payload;
    },
    changeSearchText: (state, { payload }) => {
      state.searchText = payload;
    },
    changeCountSearchBool: (state, { payload }) => {
      state.countSearchBool = payload;
    },
    setSearchedEver: (state, { payload }) => {
      state.isSearchedEver = payload;
    },
    addItemToMainLoader: (state, { payload }) => {
      const updatedLoad = [...state.mainLoader, payload];
      state.mainLoader = updatedLoad;
    },
    removeItemFromMainLoader: (state, { payload }) => {
      const updatedLoad = state.mainLoader.filter((item) => item !== payload);
      state.mainLoader = updatedLoad;
    },
    setIsFavActive: (state, { payload }) => {
      if (payload) {
        state.isFavActive = payload;
      } else {
        state.isFavActive = !state.isFavActive;
      }
    },
    setIsSnoozeModal: (state) => {
      state.isSnoozeModal = !state.isSnoozeModal;
    },
    setIsTrademarksModal: (state) => {
      state.isTrademarksModal = !state.isTrademarksModal;
    },
    toggleTagsModal: (state, { payload }) => {
      state.isTagsModal = payload;
    },
    toggleSidebarTrendsModal: (state, { payload }) => {
      state.isSidebarTrendsModal = payload;
    },
    setIsPAInitialLoad: (state, { payload }) => {
      state.isPAInitialLoad = payload;
    },
    setIsKRInitialLoad: (state, { payload }) => {
      state.isKRInitialLoad = payload;
    },
    setMainModalOpen: (state, { payload }) => {
      state.isMainModalOpen = payload;
    },
    setIsNewFavFolderModal: (state, { payload }) => {
      state.isNewFavFolderModal = payload;
    },
    updateScrappedListingIds: (state, { payload }) => {
      state.listingIdsForPA = payload;
    },
    // Clear the right-pane's per-listing data and flip it into a loading state.
    // Dispatched synchronously when opening the pane for a *different* listing,
    // so the pane never paints the previously-viewed listing's data before the
    // fetch (which runs in a post-paint effect) kicks in.
    resetRightPaneData: (state) => {
      state.rightPaneLoading = true;
      state.listingDetailsData = {};
      state.shopDetailsData = {};
      state.sidePanTags = [];
      state.dailyTrendsSales = {};
    },
    setIsListingFav: (state, { payload }) => {
      state.isListingFav = payload;
      state.listingDetailsData = {
        ...state.listingDetailsData,
        isFav: payload,
      };
    },
    setIsShopFav: (state, { payload }) => {
      state.shopDetailsData = {
        ...state.shopDetailsData,
        isFav: payload,
      };
    },
    updateSidePaneTagsData: (state, { payload }) => {
      state.sidePanTags = payload;
    },
    updateSidePaneTagsIsFav: (state, { payload }) => {
      const { keywordId, isFavBool } = payload;
      state.sidePanTags = state.sidePanTags.map((item) =>
        item.keywordId === keywordId ? { ...item, isFav: isFavBool } : item,
      );
    },
    updateSidePaneTagsIsFavBulk: (state, { payload }) => {
      const { keywordIds, isFavBool } = payload;
      const idSet = new Set(keywordIds);
      state.sidePanTags = state.sidePanTags.map((item) =>
        idSet.has(item.keywordId) ? { ...item, isFav: isFavBool } : item,
      );
    },
    updateSidePanTagsCheckedRows: (state, { payload }) => {
      const { rowIds, rowsData } = payload;
      state.sidePanTagsCheckedRowIds = rowIds;
      state.sidePanTagsCheckedRowsData = rowsData;
    },
    clearSidePanTagsCheckedRows: (state) => {
      state.sidePanTagsCheckedRowIds = [];
      state.sidePanTagsCheckedRowsData = [];
    },
    updateModalTagsCheckedRows: (state, { payload }) => {
      state.modalTagsCheckedRowIds = payload.rowIds;
      state.modalTagsCheckedRowsData = payload.rowsData;
    },
    clearModalTagsCheckedRows: (state) => {
      state.modalTagsCheckedRowIds = [];
      state.modalTagsCheckedRowsData = [];
    },
    setBulkKeywordRowsForChange: (state, { payload }) => {
      if (payload && typeof payload === 'object' && 'rows' in payload) {
        state.bulkKeywordRowsForChange = payload.rows;
        state.bulkKeywordRowsSource = payload.source ?? 'sidepane';
      } else {
        state.bulkKeywordRowsForChange = payload;
      }
    },
    toggleRemoveFromFavConfirmModal: (state, { payload }) => {
      state.isRemoveFromFavConfirmModal = payload;
    },
    setClientSortOrder: (state, { payload }) => {
      state.clientSortOrder = payload;
    },
    toggleClientSortOrder: (state) => {
      if (state.clientSortOrder === 'desc') {
        state.clientSortOrder = 'asc';
      } else {
        state.clientSortOrder = 'desc';
      }
    },
    setClientActiveSortColumn: (state, { payload }) => {
      state.clientActiveSortColumn = payload;
    },
    setLearnModuleActive: (state, { payload }) => {
      state.isLearnModuleActive = payload;
    },
    setExtPrevListingIds: (state, { payload }) => {
      state.extPrevListingIds = payload;
    },
    setExtSearchTerm: (state, { payload }) => {
      state.extSearchTerm = payload;
    },
    setShopNameInPage: (state, { payload }) => {
      state.shopNameInPage = payload;
    },
    updateExtSearchData: (state, { payload }) => {
      state.extSearchData = payload;
      state.extSearchTotalCount = payload.length;
    },
    concatExtSearchData: (state, { payload }) => {
      const newData = payload.map(mapProduct);
      // Append new data to existing extSearchData while avoiding duplicates
      state.extSearchData = [
        ...state.extSearchData,
        ...newData.filter(
          (newListing) =>
            !state.extSearchData.some(
              (existingListing) =>
                existingListing.listingId === newListing.listingId,
            ),
        ),
      ];
      // Update the total count of listings analyzed
      state.extSearchTotalCount += newData.length;
    },
    updatePASingleListingTimeRange: (state, action) => {
      state.timeRange = action.payload;
    },
    updateExtSearchDataIsfav: (state, { payload }) => {
      const { listingId, isFavBool } = payload;
      const newData = state.extSearchData.map((item) => {
        if (item.listingId === listingId) {
          return { ...item, isFav: isFavBool };
        } else {
          return item;
        }
      });
      state.extSearchData = newData;
    },
  },
  extraReducers: (builder) => {
    //   builder.addCase(getDashboardTilesData.pending, (state) => {
    //     state.tiles.loading = true;
    //   });
    //   builder.addCase(getDashboardTilesData.fulfilled, (state, action) => {
    //     state.tiles.tileData = action.payload;
    //     state.tiles.loading = false;
    //   });
    //   builder.addCase(getDashboardTilesData.rejected, (state, action) => {
    //     state.tiles.error = action.payload;
    //     state.tiles.loading = false;
    //   });
    //   builder.addCase(getDashboardGraphData.pending, (state) => {
    //     state.graph.loading = true;
    //   }),
    //     builder.addCase(getDashboardGraphData.fulfilled, (state, action) => {
    //       state.graph.graphData = action.payload;
    //       state.graph.loading = false;
    //     }),
    //     builder.addCase(getDashboardGraphData.rejected, (state, action) => {
    //       state.graph.error = action.payload;
    //       state.graph.loading = false;
    //     });
    builder.addCase(getSingleListingDetails.pending, (state, { meta }) => {
      state.rightPaneLoading = meta.arg.updateOnlyTrends ? false : true;
    });
    builder.addCase(getSingleListingDetails.fulfilled, (state, { payload }) => {
      state.listingDetailsData = mapListings(payload.listing);
      state.isListingFav = state.listingDetailsData.isFav;

      // const salesThirtyDays =
      //   payload?.listing?.sales_data_30_days?.length == undefined ||
      //   payload?.listing?.sales_data_7_days === 'Please upgrade'
      //     ? []
      //     : payload?.listing?.sales_data_30_days;
      const salesSevenDays =
        payload?.listing?.sales_data_7_days?.length == undefined ||
        payload?.listing?.sales_data_7_days === 'Please upgrade'
          ? []
          : payload?.listing?.sales_data_7_days;
      const trendsData =
        payload?.listing?.trends.length === undefined ||
        payload?.listing?.trends === 'Please upgrade'
          ? []
          : payload?.listing?.trends;
      state.dailyTrendsSales = {
        trendsData,
        salesSevenDays,
      };

      if (payload?.shop) {
        state.shopDetailsData = mapshopDetails(payload.shop);
      }
      if (payload?.tags_analysis) {
        const newTags = payload?.tags_analysis?.map(mapTags);
        const filteredTagsByScore = clientSideSort(
          newTags,
          'keywordScore',
          'desc',
        );
        state.sidePanTags = filteredTagsByScore;
      }
      state.rightPaneLoading = false;
    });
    builder.addCase(getSingleListingDetails.rejected, (state) => {
      state.rightPaneLoading = false;
    });
    builder.addCase(addListingToFavourites.pending, (state) => {
      // state.loading = true;
    });
    builder.addCase(addListingToFavourites.fulfilled, (state, { payload }) => {
      // state.loading = false;
      Toast(`Listing added successfully to Favorites`, 'success');
      const updatedExtSearchData = state.extSearchData.map((data) =>
        data.listingId === payload.data
          ? { ...data, isFav: true } // or whatever new value for isFav
          : data,
      );
      state.extSearchData = updatedExtSearchData;
      // console.log(state.extSearchData,'ext')
    });

    builder.addCase(addListingToFavourites.rejected, (state, { payload }) => {
      // state.loading = false;
      // state.error = payload;
    });
    builder.addCase(deleteListingFromFav.pending, (state) => {
      // state.loading = true;
    });
    builder.addCase(deleteListingFromFav.fulfilled, (state, { payload }) => {
      // state.loading = false;
      Toast(`Listing removed successfully from Favorites`, 'success');
      const updatedExtSearchData = state.extSearchData.map((data) =>
        data.listingId === payload.data
          ? { ...data, isFav: false } // or whatever new value for isFav
          : data,
      );
      state.extSearchData = updatedExtSearchData;
    });
    builder.addCase(deleteListingFromFav.rejected, (state, { payload }) => {
      // state.loading = false;
      // state.error = payload;
    });
    builder.addCase(exportKeywordsByIds.fulfilled, () => {
      Toast(
        'Export sent! In a few moments, the file will arrive in your mailbox 📩',
        'success',
      );
    });
    builder.addCase(exportKeywordsByIds.rejected, () => {
      Toast('Something went wrong!, Try Again', 'error');
    });
  },
});

export const {
  updateChecklistProgress,
  updateChecklistData,
  updateGraphData,
  updateTilesData,
  changeTileSelected,
  toggleTilesVisible,
  setActivePage,
  setConnectShop,
  setEtsyConnection,
  changeEtsyCalculatorType,
  openToggleBox,
  closeToggleBox,
  changeActiveDiscountUnit,
  changeEtsyAdUnit,
  changeSearchText,
  changeCountSearchBool,
  setSearchedEver,
  addItemToMainLoader,
  removeItemFromMainLoader,
  setIsFavActive,
  setIsSnoozeModal,
  setIsTrademarksModal,
  toggleTagsModal,
  toggleSidebarTrendsModal,
  setIsPAInitialLoad,
  setIsKRInitialLoad,
  setMainModalOpen,
  setIsNewFavFolderModal,
  updateScrappedListingIds,
  resetRightPaneData,
  setIsListingFav,
  setIsShopFav,
  updateSidePaneTagsData,
  updateSidePaneTagsIsFav,
  updateSidePaneTagsIsFavBulk,
  updateSidePanTagsCheckedRows,
  clearSidePanTagsCheckedRows,
  toggleRemoveFromFavConfirmModal,
  updateModalTagsCheckedRows,
  clearModalTagsCheckedRows,
  setBulkKeywordRowsForChange,
  setClientSortOrder,
  toggleClientSortOrder,
  setClientActiveSortColumn,
  setLearnModuleActive,
  setExtPrevListingIds,
  setExtSearchTerm,
  updateExtSearchData,
  concatExtSearchData,
  setShopNameInPage,
  updatePASingleListingTimeRange,
  updateExtSearchDataIsfav
} = utilitySlice.actions;

export default utilitySlice.reducer;
