import { useState, useEffect, useRef, useMemo } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import Folder from './Folder';
import { StyledWrapper } from './StyledWrapper';
import * as amplitude from '@amplitude/analytics-browser';
import {
  manageFavItemsInFolders,
  createNewFavFolder,
  fetchFavFolderList,
  toggleKeywordsWatchlistModal,
  setKeywordsDefaultFolderData,
} from '../../store/slices/favoritesSlice';
import { toggleRightPane } from '../../store/slices/sidebarSlice';
import {
  changeFeaturePage,
  changeIframeUrl,
} from '../../store/slices/sidebarSlice';
import { MAIN_MENU } from '../../constants/menuList';
import { PLANS } from '../../constants/pricingPage';
import { KEYWORD_LIMITS } from '../../constants/favoriteLimits';
import Button from '@components/Button';
import { ClickAwayListener } from '@mui/material';
import favKeywordPopup from '@components/FavUpdateToast/Keywords/FavKeywordPopup';
import SimpleModal from '../SimpleModal/SimpleModal';
import HeaderTooltip from '@components/CustomToolTip/HeaderTooltip';
import {
  updateSidePaneTagsIsFav,
  updateSidePaneTagsIsFavBulk,
  setBulkKeywordRowsForChange,
  updateSidePanTagsCheckedRows,
  updateModalTagsCheckedRows,
} from '../../store/slices/utilitySlice';
import { updateFavoriteCount } from '../../store/slices/userSlice';
import { showFavoriteLimitErrorToast } from '../../utils/favoriteLimitHelpers';

const KeywordsWatchlistModal = ({
  row,
  context,
  setCurrentModalData,
  onConfirmSuccess,
  bulkRowsData,
}) => {
  const bulkKeywordRowsForChange = useSelector(
    (state) => state.utilities.bulkKeywordRowsForChange,
  );
  const bulkKeywordRowsSource = useSelector(
    (state) => state.utilities.bulkKeywordRowsSource,
  );
  const effectiveBulkRowsData =
    Array.isArray(bulkRowsData) && bulkRowsData.length > 0
      ? bulkRowsData
      : bulkKeywordRowsForChange?.length > 0
        ? bulkKeywordRowsForChange
        : null;
  const isBulk = Array.isArray(effectiveBulkRowsData) && effectiveBulkRowsData.length > 0;
  const [localBulkRows, setLocalBulkRows] = useState([]);
  const closeBtn = chrome.runtime.getURL('svg/close-button.svg');
  const closeIcon = chrome.runtime.getURL('svg/close-icon.svg');
  const enterKeyIcon = chrome.runtime.getURL('svg/corner-right-up.svg');

  const dispatch = useDispatch();
  const newFolderInputRef = useRef(null);
  const foldersScrollRef = useRef(null);

  const [selectedFolders, setSelectedFolders] = useState([]);
  const [folderName, setFolderName] = useState('My Folder');
  const [showCreateFolder, setShowCreateFolder] = useState(false);
  const [hasSetInitialDefaults, setHasSetInitialDefaults] = useState(false);
  const [error, setError] = useState(null);
  const {
    keywordsFolderData,
    keywordsDefaultFolderData,
    isKeywordsWatchlistModal,
  } = useSelector((state) => state.watchlist);
  const { userData } = useSelector((state) => state.user);

  const shouldShowTooltip = useMemo(() => {
    const folderCountExcludingAll = keywordsFolderData.filter(
      (folder) => folder.name !== 'All Keywords',
    ).length;

    const isHobbyLimitReached =
      userData?.current_plan === PLANS.HOBBY &&
      folderCountExcludingAll >= KEYWORD_LIMITS.HOBBY.folders;

    const isGrowthLimitReached =
      (userData?.current_plan === PLANS.GROWTH_MONTHLY ||
        userData?.current_plan === PLANS.GROWTH_ANUALLY) &&
      folderCountExcludingAll >= KEYWORD_LIMITS.GROWTH.folders;

    return isHobbyLimitReached || isGrowthLimitReached;
  }, [userData?.current_plan, keywordsFolderData]);

  const handleClose = ({ keepBulkRows = false } = {}) => {
    dispatch(toggleKeywordsWatchlistModal(false));
    if (!keepBulkRows) {
      dispatch(setBulkKeywordRowsForChange([]));
    }
    setCurrentModalData && setCurrentModalData(null);
  };

  const validateFolderName = (name) => {
    const trimmedName = name.trim();

    // Check if empty after trimming
    if (trimmedName === '') {
      setError(null); // No error for empty name, just don't allow creation
      return false;
    }

    // Check for duplicates using trimmed name
    const isDuplicate = keywordsFolderData.some(
      (folder) => folder.name === trimmedName,
    );

    if (isDuplicate) {
      setError('Folder name already exists');
      return false;
    }

    // Valid name
    setError(null);
    return true;
  };

  const isFolderSelected = (folderId) => {
    return selectedFolders.some((folder) => folder.id === folderId);
  };

  const handleFolderNameChange = (newValue) => {
    if (newValue.length > 60) {
      return; // limit of 60 characters
    }
    setFolderName(newValue);
    validateFolderName(newValue);
  };

  const handleFolderSelect = (folderId, folderName, isChecked) => {
    setSelectedFolders((prev) => {
      if (isChecked) {
        // Check if folder is already selected by ID
        const isAlreadySelected = prev.some((folder) => folder.id === folderId);
        return isAlreadySelected
          ? prev
          : [...prev, { id: folderId, name: folderName }];
      } else {
        // Remove folder by ID
        return prev.filter((folder) => folder.id !== folderId);
      }
    });
  };

  const handleClickAway = () => {
    if (showCreateFolder) {
      setShowCreateFolder(false);
      setFolderName('My Folder'); // Reset to default
      setError(null); // Clear validation error
    }
  };

  const handleCreateNewFolder = () => {
    if (!validateFolderName(folderName)) {
      return; // Don't proceed if validation fails
    }

    dispatch(createNewFavFolder({ folderName, type: 'keyword_analytic' })).then(
      (response) => {
        const newFolderId = response?.payload?.data?.folder?.id; // ID of newly created folder

        // New folder created automatically selected
        if (newFolderId) {
          setSelectedFolders((prev) => [
            { id: newFolderId, name: folderName },
            ...prev,
          ]);
        }

        dispatch(fetchFavFolderList({ type: 'keyword_analytic' })).then(() => {
          if (foldersScrollRef.current) {
            foldersScrollRef.current.scrollTo({
              top: 0,
              behavior: 'smooth', // Smooth animation
            });
          }
        }); // Refetch folder list after new folder creation
      },
    );
    setShowCreateFolder(false);
    setFolderName('My Folder'); // Reset to default
  };

  const handleRemoveKeyword = (keywordId) => {
    setLocalBulkRows((prev) => {
      const updated = prev.filter((r) => (r.keywordId ?? r.id) !== keywordId);
      if (updated.length === 0) {
        handleClose();
        return updated;
      }
      const updatedIds = updated.map((r) => r.id);
      const updateCheckedRows =
        bulkKeywordRowsSource === 'modal'
          ? updateModalTagsCheckedRows
          : updateSidePanTagsCheckedRows;
      dispatch(updateCheckedRows({ rowIds: updatedIds, rowsData: updated }));
      return updated;
    });
  };

  const handleConfirmClick = () => {
    const selectedFolderIds = selectedFolders.map((folder) => folder.id);
    const activeRows = isBulk ? localBulkRows : null;
    const itemIds = isBulk
      ? activeRows.filter((r) => !r.isFav).map((r) => r.keywordId)
      : [row.keywordId];

    dispatch(
      manageFavItemsInFolders({
        itemIdsArray: itemIds,
        type: 'keyword_analytic',
        folderIdsArray: selectedFolderIds,
        idType: 'database',
      }),
    ).then((response) => {
      if (showFavoriteLimitErrorToast(response)) {
        return;
      }
      if (response?.payload) {
        const orderedSelectedFolders = keywordsFolderData
          .filter((folder) => selectedFolderIds.includes(folder.id))
          .map((folder) => ({ id: folder.id, name: folder.name }));

        if (isBulk) {
          dispatch(
            setBulkKeywordRowsForChange({
              rows: activeRows,
              source: bulkKeywordRowsSource,
            }),
          );
        }

        if (onConfirmSuccess) {
          onConfirmSuccess(isBulk ? activeRows[0] : row, orderedSelectedFolders);
        } else {
          setTimeout(() => {
            favKeywordPopup(isBulk ? activeRows[0] : row, orderedSelectedFolders, 'add');
          }, 300);
        }

        const newDefaultFolders = keywordsFolderData.filter((folder) =>
          selectedFolderIds.includes(folder.id),
        );
        dispatch(setKeywordsDefaultFolderData(newDefaultFolders));

        if (isBulk) {
          dispatch(
            updateSidePaneTagsIsFavBulk({
              keywordIds: itemIds,
              isFavBool: true,
            }),
          );
          dispatch(
            updateFavoriteCount({ type: 'keywordCount', amount: itemIds.length }),
          );
        } else {
          dispatch(
            updateSidePaneTagsIsFav({
              keywordId: row.keywordId,
              isFavBool: true,
            }),
          );

          const added = response?.payload?.data?.details?.added || [];
          const removed = response?.payload?.data?.details?.removed || [];
          const unchanged = response?.payload?.data?.details?.unchanged || [];

          if (
            added.length > 0 &&
            removed.length === 0 &&
            unchanged.length === 0
          ) {
            dispatch(updateFavoriteCount({ type: 'keywordCount', amount: 1 }));
          }
        }
      }
    });

    amplitude.track('Favorites_Save_Confirm', {
      folders_count: selectedFolders.length,
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      item_type: 'keyword',
    });

    handleClose({ keepBulkRows: isBulk });
  };

  useEffect(() => {
    setHasSetInitialDefaults(false);
    dispatch(fetchFavFolderList({ type: 'keyword_analytic' }));
  }, []);

  useEffect(() => {
    if (showCreateFolder && newFolderInputRef.current) {
      // Small timeout to ensure DOM is fully updated
      setTimeout(() => {
        newFolderInputRef.current.select();
      }, 50);
    }
  }, [showCreateFolder]);

  useEffect(() => {
    if (keywordsFolderData.length > 0 && !hasSetInitialDefaults) {
      const defaultFolders = keywordsDefaultFolderData.map((folder) => ({
        id: folder.id,
        name: folder.name,
      }));

      setSelectedFolders(defaultFolders);
      setHasSetInitialDefaults(true);
    }
  }, [keywordsFolderData, hasSetInitialDefaults]);

  useEffect(() => {
    if (isKeywordsWatchlistModal) {
      document.body.style.overflow = 'hidden';
      document.documentElement.style.overflow = 'hidden';
      if (isBulk) {
        setLocalBulkRows(effectiveBulkRowsData);
      }
      if (keywordsDefaultFolderData.length > 0) {
        setSelectedFolders(
          keywordsDefaultFolderData.map((f) => ({ id: f.id, name: f.name })),
        );
        setHasSetInitialDefaults(true);
      }
    } else {
      document.body.style.overflow = 'unset';
      document.documentElement.style.overflow = 'unset';
    }

    return () => {
      document.body.style.overflow = 'unset';
      document.documentElement.style.overflow = 'unset';
    };
  }, [isKeywordsWatchlistModal]);

  const styleOverridesObj = {
    padding: '0',
    width: '600px',
    borderRadius: '12px',
  };

  return (
    <SimpleModal
      open={isKeywordsWatchlistModal}
      handleClose={handleClose}
      styleOverridesObj={styleOverridesObj}
    >
      <StyledWrapper>
        <div className="heading-wrap">
          <div className="heading">Move keyword(s) to folder</div>
          <img
            src={closeBtn}
            alt="Close"
            className="close-btn"
            onClick={() => handleClose()}
          />
        </div>
        <div className="divider" />
        <div className="keyword-info">
          {isBulk
            ? localBulkRows.map((r) => (
                <div className="keyword-pill" key={r.keywordId ?? r.id}>
                  {r.keywords}
                  <button
                    className="keyword-pill-remove"
                    onClick={() => handleRemoveKeyword(r.keywordId ?? r.id)}
                    aria-label={`Remove ${r.keywords}`}
                  >
                    <img src={closeIcon} width={16} height={16} alt="" />
                  </button>
                </div>
              ))
            : row?.keywords && (
                <div className="keyword-pill">{row.keywords}</div>
              )}
        </div>
        <div className="middle-wrap">
          {/* <SearchBox watchlist /> */}
          <div className="folders-wrap" ref={foldersScrollRef}>
            {keywordsFolderData
              .filter((folder) => folder.name !== 'All Keywords')
              .map(({ name, items_count, id }) => (
                // FolderHover below is just styled.div
                <Folder
                  key={id}
                  folderId={id}
                  folderName={name}
                  listingsCount={items_count}
                  isSelected={isFolderSelected(id)} // Use isFolderSelected() for checking selection
                  onSelectionChange={handleFolderSelect}
                />
              ))}
            {/* <AddNewFolder folderName={'Create New Group'} /> */}
            {showCreateFolder && (
              <ClickAwayListener onClickAway={handleClickAway}>
                <div className="create-folder-input-wrap">
                  <input
                    ref={newFolderInputRef}
                    type="text"
                    name="new-folder-input"
                    className={
                      error
                        ? 'new-folder-input error-input-field'
                        : 'new-folder-input'
                    }
                    value={folderName}
                    onChange={(e) => handleFolderNameChange(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        handleCreateNewFolder();
                      }
                    }}
                  />
                  <button
                    className="create-button"
                    onClick={handleCreateNewFolder}
                  >
                    <span className="create-text">Create</span>
                    <img src={enterKeyIcon} />
                  </button>
                  {error && <span className="error-text">{error}</span>}
                </div>
              </ClickAwayListener>
            )}
          </div>
          {(() => {
            const createFolderButton = (
              <button
                className="button-add-folder"
                onClick={() => {
                  if (shouldShowTooltip) {
                    dispatch(toggleRightPane(false));
                    dispatch(changeFeaturePage(MAIN_MENU.PRICING));
                    dispatch(changeIframeUrl('pricing'));
                    handleClose();
                  } else {
                    setShowCreateFolder(true);
                  }
                }}
              >
                <span className="create-folder">Create new folder</span>
              </button>
            );

            return shouldShowTooltip ? (
              <HeaderTooltip
                PopperProps={{
                  style: {
                    zIndex: 99999999,
                  },
                }}
                title={
                  <>
                    <i>Upgrade to create additional folders.</i>
                    <br />
                    <i>Click to upgrade</i>
                  </>
                }
                placement="right"
                disableInteractive={true}
              >
                {createFolderButton}
              </HeaderTooltip>
            ) : (
              createFolderButton
            );
          })()}
        </div>
        <div className="divider" />
        <div className="button-wrap">
          <Button
            buttonText="Cancel"
            textColor="#19191A"
            size="small"
            customPadding="11px"
            customFontSize="14px"
            backgroundColor="#FFFFFF"
            customWidth="72px"
            customBorderRadius="8px"
            customBoxShadow="0 1px 1px 0 rgba(0, 0, 0, 0.10), 0 0 0 1px rgba(0, 0, 0, 0.08)"
            onClick={() => handleClose()}
          />
          <Button
            buttonText="Confirm"
            size="small"
            customPadding="11px"
            customFontSize="14px"
            backgroundColor="#3d98f2"
            customWidth="72px"
            customBorderRadius="8px"
            customBoxShadow="0 1px 0 0 rgba(255, 255, 255, 0.30) inset, 0 1px 1px 0 rgba(13, 97, 181, 0.80), 0 0 0 1px #3490EC"
            onClick={handleConfirmClick}
            disabled={selectedFolders.length === 0}
          />
        </div>
      </StyledWrapper>
    </SimpleModal>
  );
};

export default KeywordsWatchlistModal;
