import axios from 'axios';

const AUTH_BASE_URL = process.env.REACT_APP_BACKEND_URL;
const AUTH_SSO_URL = process.env.NEXT_PUBLIC_SSO_BACKEND_APP;

export const getSubscriptionDataAPI = (userEmail) => {
  return axios.get(`${AUTH_BASE_URL}/stripe_subscriptions/ids`, userEmail);
};

export const getManageBillingAPI = () => {
  return axios.get(`${AUTH_BASE_URL}/current_plan/manage`);
};

export const getSalesChannelsAPI = () => {
  return axios.get(`${AUTH_BASE_URL}/sales_channels`);
};

export const deleteSalesChannelsAPI = (sales_channel_id) => {
  return axios.delete(`${AUTH_BASE_URL}/sales_channels/${sales_channel_id}`);
};

export const changePasswordAPI = (change_password) => {
  return axios.post(
    `${AUTH_BASE_URL}/passwords/change_password`,
    change_password,
  );
};

export const updateHideDetailsAPI = (hide) => {
  return axios.post(`${AUTH_BASE_URL}/users/update_hide_details_option`, {
    hide_details: hide,
  });
};
export const getUserDataAPI = () => {
  return axios.get(`${AUTH_BASE_URL}/users/show`);
};
export const updateDefaultSalesChannelAPI = (salesChannelsId) => {
  return axios.post(`${AUTH_BASE_URL}/users/update_default_sales_channel_ids`, {
    default_sales_channel_ids: salesChannelsId,
  });
};

export const sidebarOnboardingShownAPI = (token) => {
  const headers = {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${token}`,
  };
  return axios.patch(
    `${process.env.REACT_APP_SSO_BACKEND_APP}/update_sidebar_onboarding_shown`,
    {},
    { headers },
  );
};

export const onboardingFlowAPI = () => {
  return axios.put(`${AUTH_BASE_URL}/users/complete_onboarding_flow`, {});
};

