export const extensionAttributes = (payload) =>
  axios.put(`${AUTH_BASE_URL}/users/update_extension_attributes`, payload);

export const addToStoreWaitlist = () => {
  return axios.post(`${AUTH_SSO_URL}/add_to_store_waitlist`, {});
};

export const closeBannerTouchpointAPI = (touchpoint, product = 'oposhop') => {
  return axios.patch(`${AUTH_BASE_URL}/users/close_touchpoint`, {
    touchpoint,
    product,
  });
};
