import styled from 'styled-components';
import Checkbox from '../Checkbox/index.js';

const StyledWrapper = styled.div`
  cursor: pointer !important;
  height: 56px;
  padding: 10px;
  border-radius: 4px;
  background-color: ${({ theme }) => theme.colors.background};
  border: 1px solid ${({ isSelected }) => isSelected ? '#3D98F2' : 'transparent'};

  display: flex;
  align-items: center;
  gap: 12px;

  .folder-name {
    font-size: 14px;
    color: ${({ theme }) => theme.colors.neutral.gray800};
    font-weight: 400;
    line-height: 20px;
  }

  .folder-listings {
    font-size: 12px;
    color: ${({ theme }) => theme.colors.neutral.gray600};
  }
`;

const Folder = ({ folderName, folderId, listingsCount, isSelected = false, onSelectionChange }) => {

  const handleFolderClick = () => {
    onSelectionChange(folderId, folderName, !isSelected);
  };

  const handleCheckboxChange = (e) => {
    onSelectionChange(folderId, folderName, e.target.checked);
  };

  
  return (
    <StyledWrapper 
      onClick={handleFolderClick}
      isSelected={isSelected}
    >
      <Checkbox  
        checked={isSelected}           // Pass the checked state
        onChange={handleCheckboxChange} 
      />
      <div className="folder-details">
        <div className="folder-name">{folderName}</div>
        <div className="folder-listings">
          {(listingsCount ?? 0) > 1 || (listingsCount ?? 0) === 0
            ? `${listingsCount ?? 0} items`
            : `${listingsCount ?? 0} item`}
        </div>
      </div>
    </StyledWrapper>
  );
};

export default Folder;
