import { PLANS } from "../constants/pricingPage";

export const isContentLocked = (currentPlan, dateRange, type) => {

    // Handle null/undefined inputs
    // if(!currentPlan || !dateRange) {
    //     console.warn("Invalid inputs to isContentLocked", { currentPlan, dateRange });
    //     return true; // Default to locked for safety
    // }

    if(currentPlan === PLANS.HOBBY) {
        return true;
    } else if (currentPlan === PLANS.GROWTH_MONTHLY || currentPlan === PLANS.GROWTH_ANUALLY) {
        return type === 'listing' ? false : dateRange !== 'last_1_month';
    } else if (currentPlan === PLANS.BUSINESS_MONTHLY || currentPlan === PLANS.BUSINESS_ANUALLY) {
        return false;
    } else {
        console.warn("Unknown plan type:", currentPlan);
        return true; // Default to locked for unknown plans
    }
}