/*global chrome*/
import styled from 'styled-components';
import * as amplitude from '@amplitude/analytics-browser';
import { IFrame } from '../IFrame/IFrame';

const StyledWrapper = styled.div`
  padding: 16px;
  width: 100%;

  .video-content {
    width: 100%;
    margin-bottom: 12px;
  }

  .video-content iframe {
    /* pointer-events: none; */
  }

  .sub-heading {
    margin-bottom: 12px;
  }

  .heading {
    color: #19191a;
    font-size: 18px;
    font-weight: 700;
    line-height: 28px;
  }

  .sub-heading {
    color: #646566;
    font-size: 14px;
    font-weight: 500;
    line-height: 20px;
  }

  .help-center {
    display: flex;
    align-items: center;
    cursor: pointer;
  }

  .help-text {
    color: #1f76cc;
    font-size: 14px;
    font-weight: 500;
    line-height: 20px;
    text-decoration-line: underline;
  }
`;

const VideoCard = ({ heading, subHeading, videoSrc, helpLink }) => {
  const linkOutBlue = chrome.runtime.getURL('svg/link-out-blue.svg');

  const handleVideoClick = () => {
    amplitude.track('Learn - video clicked - extension');
  };

  const handleHelpClick = () => {
    window.open(helpLink, '_blank');
  };

  return (
    <StyledWrapper>
      <div className="video-content">
        <IFrame
          width="100%"
          height={200}
          src={videoSrc}
          title="YouTube video player"
          // eslint-disable-next-line
          frameborder="0"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          // eslint-disable-next-line
          referrerpolicy="strict-origin-when-cross-origin"
          allowfullscreen
          onInferredClick={handleVideoClick}
        />
      </div>
      <div className="heading">{heading}</div>
      <div className="sub-heading">{subHeading}</div>
      {helpLink !== null && (
        <div className="help-center" onClick={handleHelpClick}>
          <span className="help-text">View help center</span>
          <img className="link-icon" src={linkOutBlue} alt="link icon" />
        </div>
      )}
    </StyledWrapper>
  );
};

export default VideoCard;
