import React from 'react';
import { toast } from 'sonner';
import FavShopUpdateToast from './FavShopUpdateToast';

const FavShopPopup = (row, folderDetailsArray, action, context) => {
  toast.dismiss(); // Dismiss existing toasts before showing a new ones

  toast.custom(
    (id) => (
      <FavShopUpdateToast
        row={row}
        folderDetailsArray={folderDetailsArray}
        action={action}
        context={context}
        onClose={() => toast.dismiss(id)}
      />
    ),
    { duration: 5000, unstyled: true, position: 'bottom-right' },
  );
};

export default FavShopPopup;
