/*global chrome*/
import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import * as amplitude from '@amplitude/analytics-browser';
import { StyledWrapper } from './StyledWrapper';
import { changeFeaturePage } from '../../store/slices/sidebarSlice';
import {
  manageFavItemsInFolders,
  fetchFoldersContainingPL,
  setListingFolderMgmtModalStatus,
  setManagementModalStatus,
  toggleListingsWatchlistModal,
  unfavouritePLFromFav,
} from '../../store/slices/favoritesSlice';
import {
  setIsListingFav,
  setIsNewFavFolderModal,
  updateExtSearchDataIsfav,
} from '../../store/slices/utilitySlice';
import favPopup from '../FavUpdateToast/Listings/FavPopup';
import NewFavFolderModal from '../NewFavFolderModal';
import { ListingsWatchlistModal } from '../WatchlistModal';

const HeadingAndIcons = ({ activeButton, closeDrawer }) => {
  const dispatch = useDispatch();
  const Calculator = chrome.runtime.getURL('svg/calc-sidebar.svg');
  const CloseButton = chrome.runtime.getURL('svg/close-button.svg');
  const favFilled = chrome.runtime.getURL('svg/fav-filled.svg');
  const favUnfilled = chrome.runtime.getURL('svg/fav-unfilled.svg');

  const { listingDetailsData, isListingFav, isNewFavFolderModal } = useSelector(
    (state) => state.utilities,
  );
  const {
    listingsFolderData,
    listingsDefaultFolderData,
    isListingsWatchlistModal,
  } = useSelector((state) => state.watchlist);
  const isListingFolderManagement = useSelector(
    (state) => state.watchlist.folderManagementModalStatus.listing,
  );

  const currentUrl = window.location.href;

  const trackFavoritesEvent = (eventName, additionalProps = {}) => {
    amplitude.track(eventName, {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      source_type: 'listing_details',
      item_type: 'listing',
      ...additionalProps,
    });
  };

  const handleClickFavourites = async (e) => {
    e.stopPropagation();

    if (isListingFav) {
      const response = await dispatch(
        fetchFoldersContainingPL({
          itemIdsArray: [listingDetailsData?.listingId],
          type: 'listing',
        }),
      ).unwrap();

      const folderIdsFromResponse =
        response?.data?.items?.flatMap((item) => item.folder_ids) || [];

      const folderDetails = listingsFolderData
        .filter((folder) => folderIdsFromResponse.includes(folder.id))
        .map((folder) => ({
          name: folder.name,
          id: folder.id,
        }));

      await dispatch(
        unfavouritePLFromFav({
          itemId: listingDetailsData?.listingId,
          type: 'listing',
        }),
      ).unwrap();

      dispatch(setIsListingFav(false));
      dispatch(
        updateExtSearchDataIsfav({
          listingId: listingDetailsData.listingId,
          isFavBool: false,
        }),
      );

      setTimeout(() => {
        favPopup(listingDetailsData, folderDetails, 'undo', 'HeadingAndIcons');
      }, 300);

      trackFavoritesEvent('Favorites_Remove_Click');
    } else {
      const defaultFolderIds = listingsDefaultFolderData.map(
        (folder) => folder.id,
      );

      if (listingsFolderData.length === 0) {
        trackFavoritesEvent('Add_To_Favorites_Click', {
          is_first_favorites_action_of_day: true,
        });
        dispatch(setIsNewFavFolderModal(true));
      } else if (isListingFolderManagement || defaultFolderIds.length === 0) {
        dispatch(toggleListingsWatchlistModal(true));
        if (isListingFolderManagement) {
          trackFavoritesEvent('Add_To_Favorites_Click', {
            is_first_favorites_action_of_day: true,
          });
          dispatch(setManagementModalStatus({ itemType: 'listing' })); //BE update
          dispatch(setListingFolderMgmtModalStatus(false)); //local update
        }
      } else {
        trackFavoritesEvent('Add_To_Favorites_Click', {
          target_folders_count: defaultFolderIds.length,
          is_first_favorites_action_of_day: false,
        });
        dispatch(
          manageFavItemsInFolders({
            itemIdsArray: [listingDetailsData.listingId],
            type: 'listing',
            folderIdsArray: defaultFolderIds,
          }),
        ).then((response) => {
          if (response?.payload) {
            dispatch(setIsListingFav(true));
            dispatch(
              updateExtSearchDataIsfav({
                listingId: listingDetailsData.listingId,
                isFavBool: true,
              }),
            );

            const defaultFolderDetails = listingsDefaultFolderData.map(
              (folder) => ({
                name: folder.name,
                id: folder.id,
              }),
            );
            setTimeout(() => {
              favPopup(
                listingDetailsData,
                defaultFolderDetails,
                'add',
                'HeadingAndIcons',
              );
            }, 300);
          }
        });
      }
    }
  };

  const handleCalculator = () => {
    amplitude.track('Calculator_View', {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      source_type: 'listing_details',
    });

    if (!currentUrl.includes('/listing')) {
      window.open(
        `https://www.etsy.com/listing/${listingDetailsData?.listingId}?openFeaturePage=etsyCalculator`,
        '_blank',
      );
    } else {
      dispatch(changeFeaturePage('etsy-calculator'));
    }
  };

  return (
    <StyledWrapper>
      <div className="HeadingIconsWrapper">
        <div className="HeadingWrapper">
          <h5 className="Heading main-heading">
            {activeButton === 'Listing Details'
              ? 'Listing Details'
              : 'Shop Details'}
          </h5>
        </div>
        <div className="IconsWrapper">
          {/* {activeButton === 'Listing Details' && (
            <button
              onClick={handleClickFavourites}
              style={{ backgroundColor: 'transparent' }}
            >
              <img
                src={isListingFav ? favFilled : favUnfilled}
                alt={isListingFav ? 'Favorite Filled' : 'Favorite Unfilled'}
                width={20}
                height={20}
              />
            </button>
          )} */}
          <button>
            <img
              src={Calculator}
              alt="Calculator"
              onClick={handleCalculator}
              width={28}
              height={28}
            />
          </button>
          <span className="pipe"></span>
          <button onClick={closeDrawer}>
            <img src={CloseButton} alt="CloseButton" />
          </button>
        </div>
      </div>

      {isNewFavFolderModal && (
        <NewFavFolderModal row={listingDetailsData} context="HeadingAndIcons" />
      )}

      {isListingsWatchlistModal && (
        <ListingsWatchlistModal
          row={listingDetailsData}
          context="HeadingAndIcons"
        />
      )}
    </StyledWrapper>
  );
};

export default HeadingAndIcons;
