/*global chrome*/
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import * as amplitude from '@amplitude/analytics-browser';
import {
  deleteSalesChannelsAPI,
  getSalesChannelsAPI,
  getSubscriptionDataAPI,
  updateHideDetailsAPI,
  getUserDataAPI,
  sidebarOnboardingShownAPI,
  onboardingFlowAPI,
  closeBannerTouchpointAPI,
} from '../../services/account';

// import Toast from '@components/StyledToastContainer/toast';

// Promo banner campaigns keep their dismissal state under separate `ui_flags`
// keys, so only the active product's touchpoints are affected (RESEARCH-3192).
const BANNER_PRODUCT_FLAG_KEY = {
  oposhop: 'banners',
  ohoney: 'ohoney_banners',
};

const initialState = {
  userData: {},
  subscriptions: {},
  salesChannels: [],
  salesChannelDeleted: '',
  timePeriod: 'Last 30 Days',
  loading: false,
  salesChannelLoading: false,
  error: null,
  isUnlinkSalesChannelModal: false,
  salesChannelName: '',
  favoriteLimits: {
    keywordCount: 0,
    shopCount: 0,
  },
};

export const getUserData = createAsyncThunk(
  'user/getUserData',
  async (args, thunkAPI) => {
    try {
      const response = await getUserDataAPI();
      var manifestData = chrome.runtime.getManifest();
      amplitude.init(process.env.REACT_APP_AMPLITUDE_KEY, response.data.id, {
        defaultTracking: false,
        autocapture: false,
      });
      const identify = new amplitude.Identify();
      identify
        .set('user_email', response.data.email)
        .set('ext_version', manifestData.version)
        .set('extension_installed', true);
      amplitude.identify(identify);
      return response.data;
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const updateHideDetails = createAsyncThunk(
  'user/updateHideDetails',
  async ({ hide }, thunkAPI) => {
    try {
      const response = await updateHideDetailsAPI(hide);
      return response.data;
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const getSalesChannels = createAsyncThunk(
  'user/getSalesChannels',
  async (handleStoreSelectLoading, thunkAPI) => {
    try {
      handleStoreSelectLoading(true);
      const response = await getSalesChannelsAPI();
      return response.data.sales_channels;
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    } finally {
      handleStoreSelectLoading(false);
    }
  },
);

