export const closeBannerTouchpoint = createAsyncThunk(
  'user/closeBannerTouchpoint',
  async ({ touchpoint, product = 'oposhop' }, thunkAPI) => {
    try {
      const response = await closeBannerTouchpointAPI(touchpoint, product);
      return { touchpoint, product, data: response.data };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response?.data || err.message);
    }
  },
);

export const userSlice = createSlice({
  name: 'user',
  initialState,
  reducers: {
    updateUserData: (state, actions) => {
      state.userData = actions.payload;
    },
    updateSubscriptionsData: (state, actions) => {
      state.subscriptions = actions.payload;
    },
    updateDeletedSalesChannel: (state, actions) => {
      state.salesChannelDeleted = actions.payload;
    },
    updateSalesChannel: (state, actions) => {
      state.salesChannels = actions.payload;
    },
    updateTimePeriod: (state, actions) => {
      state.timePeriod = actions.payload;
    },
    setIsUnlinkSalesChannelModal: (state) => {
      state.isUnlinkSalesChannelModal = !state.isUnlinkSalesChannelModal;
    },
    setSalesChannelName: (state, { payload }) => {
      state.salesChannelName = payload;
    },
    updateFavoriteCount: (state, { payload }) => {
      const { type, amount = 1 } = payload;

      state.favoriteLimits[type] += amount;
    },
    dismissBannerTouchpoint: (
      state,
      { payload: { touchpoint, product = 'oposhop' } },
    ) => {
      const flagKey = BANNER_PRODUCT_FLAG_KEY[product];
      const dismissed = state.userData?.ui_flags?.[flagKey]?.dismissed;

      if (dismissed && touchpoint in dismissed) {
        dismissed[touchpoint] = true;

        // If 2 or more touchpoints are dismissed, dismiss all
        const dismissedCount = Object.values(dismissed).filter(Boolean).length;
        if (dismissedCount >= 2) {
          Object.keys(dismissed).forEach((key) => {
            dismissed[key] = true;
          });
        }
      }
    },
  },
  extraReducers: (builder) => {
    builder.addCase(getSubscriptionData.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(getSubscriptionData.fulfilled, (state, actions) => {
      state.subscriptions = actions.payload;
      state.loading = false;
    });
    builder.addCase(getSubscriptionData.rejected, (state, actions) => {
      state.loading = false;
      state.error = actions.payload;
    });
    builder.addCase(getUserData.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(getUserData.fulfilled, (state, actions) => {
      state.userData = actions.payload;

      // Update keyword favorite count from API response
      if (
        actions.payload.favorites_restrictions?.keyword
          ?.current_favorite_count !== undefined
      ) {
        state.favoriteLimits.keywordCount =
          actions.payload.favorites_restrictions.keyword.current_favorite_count;
      }

      // Update shop favorite count from API response
      if (
        actions.payload.favorites_restrictions?.shop?.current_favorite_count !==
        undefined
      ) {
        state.favoriteLimits.shopCount =
          actions.payload.favorites_restrictions.shop.current_favorite_count;
      }

      state.loading = false;
      localStorage.setItem('everbeeUserId', actions.payload.id);
      // Mirror `showImagePromptFeature` into chrome.storage.local so the
      // content-script bee menu (gemini/content.js) can gate itself without
      // needing Redux access.
      const showImagePromptFeature =
        actions.payload.showImagePromptFeature ??
        actions.payload.show_image_prompt_feature ??
        false;
      chrome.storage.local.set({
        [process.env.REACT_APP_AUTH_COOKIE_NAME]:
          actions.payload.new_sso_auth_token,
        everbee_show_image_prompt_feature: !!showImagePromptFeature,
      });
    });
    builder.addCase(getUserData.rejected, (state, actions) => {
      state.loading = false;
      state.error = actions.payload;
      state.userData = {};
    });
    builder.addCase(updateHideDetails.pending, (state) => {
      // state.loading = true;
    });
    builder.addCase(updateHideDetails.fulfilled, (state, actions) => {
      // state.userData = actions.payload;
      // state.loading = false;
    });
    builder.addCase(updateHideDetails.rejected, (state, actions) => {
      // state.loading = false;
      state.error = actions.payload;
    });
    builder.addCase(getSalesChannels.pending, (state) => {
      state.loading = true;
      state.salesChannelLoading = true;
    });
    builder.addCase(getSalesChannels.fulfilled, (state, actions) => {
      state.salesChannels = actions.payload;
      state.loading = false;
      state.salesChannelLoading = false;
    });
    builder.addCase(getSalesChannels.rejected, (state, actions) => {
      state.loading = false;
      state.salesChannelLoading = false;
      state.error = actions.payload;
      // Toast('Please try again', 'error');
    });
    builder.addCase(deleteSalesChannels.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(deleteSalesChannels.fulfilled, (state, { payload }) => {
      const updatedSaleChannels = state.salesChannels.filter(
        (item) => item.sales_channel_id !== payload.salesChannelId,
      );
      state.salesChannels = updatedSaleChannels;
      const newDefaultSalesChannelId =
        state.userData.default_sales_channel_ids.filter(
          (item) => item !== payload.salesChannelId,
        );
      const newSalesChannelInUserData = state.userData.sales_channels.filter(
        (item) => item.id !== payload.salesChannelId,
      );
      if (state.userData.sales_channels.length !== 0)
        newDefaultSalesChannelId.push(state.userData.sales_channels[0].id);
      state.userData.default_sales_channel_ids = newDefaultSalesChannelId;
      state.userData.sales_channels = newSalesChannelInUserData;
      state.userData.shop_name =
        state.salesChannels.length !== 0
          ? state.salesChannels[0].sales_channel_shop_name
          : null;
      state.loading = false;
      // Toast('Sales channel deleted', 'success');
    });
    builder.addCase(deleteSalesChannels.rejected, (state, actions) => {
      state.loading = false;
      state.error = actions.payload;
      // Toast('Please try again', 'error');
    });
    builder.addCase(sidebarOnboardingShown.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(sidebarOnboardingShown.fulfilled, (state, { payload }) => {
      state.loading = false;
    });
    builder.addCase(sidebarOnboardingShown.rejected, (state, actions) => {
      state.loading = false;
      state.error = actions.payload;
    });
    builder.addCase(onboardingFlow.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(onboardingFlow.fulfilled, (state, { payload }) => {
      state.userData.onboarding_flow = true;
      state.loading = false;
    });
    builder.addCase(onboardingFlow.rejected, (state, actions) => {
      state.loading = false;
      state.error = actions.payload;
    });
  },
});

export const {
  updateUserData,
  updateSubscriptionsData,
  updateDeletedSalesChannel,
  updateSalesChannel,
  updateTimePeriod,
  setIsUnlinkSalesChannelModal,
  setSalesChannelName,
  updateFavoriteCount,
  dismissBannerTouchpoint,
} = userSlice.actions;

export default userSlice.reducer;
