import axios from 'axios';
const AUTH_BASE_URL = process.env.REACT_APP_BACKEND_URL;

export const getAllFoldersPL = (type) => {
  return axios.get(`${AUTH_BASE_URL}/folders?type=${type}`);
};

export const createNewFolderPL = (folderName, type) => {
  return axios.post(`${AUTH_BASE_URL}/folders`, {
    folder: {
      name: folderName,
      favoritable_type: type,
    },
  });
};

export const manageFavItemsInFoldersAPI = (
  itemIdsArray,
  type,
  folderIdsArray,
  idType = 'search',
) => {
  return axios.post(`${AUTH_BASE_URL}/favorites/set_folders`, {
    item_ids: itemIdsArray,
    item_type: type,
    folder_ids: folderIdsArray,
    id_type: idType,
  });
};

export const unfavouritePLFromFavAPI = (
  itemId,
  type,
  idType = 'search', // idType: 'search' for listings by default, 'database' for keywords/tags
) => {
  return axios.delete(
    `${AUTH_BASE_URL}/favorites/unfavorite?id_type=${idType}&item_type=${type}&item_id=${itemId}`,
  );
};

export const getFoldersContainingPL = (
  itemIdsArray,
  type = 'listing',
  idType = 'search',
) => {
  return axios.get(`${AUTH_BASE_URL}/favorites/status`, {
    params: {
      item_type: type,
      'item_ids[]': itemIdsArray,
      id_type: idType,
    },
  });
};

export const getManagementModalStatusAPI = () => {
  return axios.get(`${AUTH_BASE_URL}/management_modals`);
};

export const setManagementModalStatusAPI = (itemType) => {
  return axios.put(`${AUTH_BASE_URL}/management_modals/${itemType}/seen`);
};
