export function getListingIds(category, setScrappedListingIds, setAdListings) {
  var listingIds = [];
  var adListingIds = [];
  if (category === 'shop') {
    let listings = document.querySelectorAll('.v2-listing-card');
    listings.forEach((item) => {
      if (item.getAttribute('data-page-type') !== 'recently_viewed_carousel')
        listingIds.push(item.getAttribute('data-listing-id'));
    });

    setScrappedListingIds(listingIds);
  } else if (category === 'people') {
    let listings = document.querySelectorAll(
      '.wt-list-unstyled .v2-listing-card, .block-grid-no-whitespace .v2-listing-card',
    );
    listings.forEach((item) => {
      if (
        item
          .querySelector(
            '.v2-listing-card__info p.wt-text-caption.wt-text-truncate.wt-text-gray.wt-mb-xs-1',
          )
          ?.innerText?.includes('Ad by')
      )
        adListingIds.push(parseInt(item.getAttribute('data-listing-id')));
      listingIds.push(item.getAttribute('data-listing-id'));
    });
    setScrappedListingIds(listingIds);
  } else if (category === 'trending_now') {
    let listings = document.querySelectorAll('ul#search-results li a');
    listings.forEach((item) => {
      if (
        item
          .querySelector(
            '.v2-listing-card__info p.wt-text-caption.wt-text-truncate.wt-text-gray.wt-mb-xs-1',
          )
          ?.innerText?.includes('Ad by')
      )
        adListingIds.push(parseInt(item.getAttribute('data-listing-id')));
      listingIds.push(item.getAttribute('data-listing-id'));
    });
    setScrappedListingIds(listingIds);
  } else if (category === 'homePage') {
    let listings = document.querySelectorAll(
      '.hp-carousel__card',
    );
    // console.log('home page listings', listings);
    if (listings.length <= 0) {
      listings = document.querySelectorAll('#content ul.wt-block-grid li a');
      if (listings.length <= 0) {
        listings = document.querySelectorAll('.block-grid-no-whitespace li');
      }
    }
    listings.forEach((item) => {
      // Get the immediate child with the listing card class
      const listingCard = item.querySelector('.js-merch-stash-check-listing');
      const listingId = listingCard?.getAttribute('data-listing-id');
      
      if (listingId) {
        listingIds.push(listingId);
      }
    });
    setScrappedListingIds(listingIds);
  } else if (category === 'gifts') {
    let listings = document.querySelectorAll('.js-merch-stash-check-listing');
    listings.forEach((item) => {
      listingIds.push(item.getAttribute('data-listing-id'));
    });
    setScrappedListingIds(listingIds);
  } else {
    let listings = document.querySelectorAll('.v2-listing-card');
    listings.forEach((item) => {
      if (
        item.getAttribute('data-page-type') !== 'recently_viewed_carousel' &&
        item.getAttribute('data-page-type') !== 'homepage' 
        // && item.getAttribute('data-page-type') !== ''
      ) {
        // let listingsProducts = document.querySelectorAll('.v2-listing-card');
        // listingsProducts.forEach((item) => {
        //   if (
        //     item.querySelector('.v2-listing-card__info') &&
        //     item
        //       .querySelector('.v2-listing-card__info')
        //       .children[4]?.innerText?.includes(`Ad`)
        //   ) {
        //     adListingIds.push(parseInt(item.getAttribute('data-listing-id')));
        //   }
        // });
        listingIds.push(item.getAttribute('data-listing-id'));
      }
    });

    setScrappedListingIds(listingIds);
    setAdListings(adListingIds);
  }
}

export function getScrappedListingIdsByCategory(
  setScrappedListingIds,
  setAdListings,
) {
  var fullUrl = window.location.href;

  if (fullUrl.indexOf('/shop/') !== -1) {
    getListingIds('shop', setScrappedListingIds, setAdListings);
  } else if (fullUrl.indexOf('people') !== -1) {
    getListingIds('people', setScrappedListingIds, setAdListings);
  } else if (
    fullUrl.indexOf('search?') !== -1 ||
    fullUrl.indexOf('/search/') !== -1 ||
    fullUrl.indexOf('/everyday') !== -1
  ) {
    getListingIds('keywords', setScrappedListingIds, setAdListings);
  } else if (fullUrl.indexOf('market/') !== -1) {
    getListingIds('trending_now', setScrappedListingIds, setAdListings);
  } else if (
    (fullUrl.indexOf('/c') !== -1 && fullUrl.indexOf('/ca') === -1) ||
    fullUrl.indexOf('/markets') !== -1
  ) {
    getListingIds('pCategory', setScrappedListingIds, setAdListings);
  } else if (fullUrl.indexOf('/gift-mode') !== -1) {
    getListingIds('gifts', setScrappedListingIds, setAdListings);
  } else if (
    fullUrl.indexOf('featured') !== -1 ||
    fullUrl.indexOf('themes') !== -1 ||
    fullUrl.indexOf('picks') !== -1 ||
    fullUrl.indexOf('similar') !== -1 ||
    fullUrl.indexOf('/r/group') !== -1
  ) {
    getListingIds('others', setScrappedListingIds, setAdListings);
  } else if (
    fullUrl.indexOf('www.etsy.com') !== -1 ||
    fullUrl.indexOf('?ref=lgo') !== -1
  ) {
    getListingIds('homePage', setScrappedListingIds, setAdListings);
  } else {
  }
}
