import axios from 'axios';

const AUTH_BASE_URL = process.env.REACT_APP_BACKEND_URL;

export const getSingleListingDetailsAPI = (
  listingId,
  listingDetails,
  listingAnalytics,
  listingTagAnalytics,
  listingShop,
  timeRange,
) => {
  return axios.get(
    `${AUTH_BASE_URL}/listing/${listingId}?fromApp=extension&listingDetails=${listingDetails}&listingAnalytics=${listingAnalytics}&listingTagAnalytics=${listingTagAnalytics}&listingShop=${listingShop}&time_range=${timeRange}`,
  );
};

export const keywordSuggestion = async (keyword) => {
  return axios.post(
    `${AUTH_BASE_URL}/keyword_research/keywords_data?type_of_search=search_bar_keywords_search_volume`,
    { keywords: keyword },
    {
      headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json',
        'Authorized-token': localStorage.getItem('everbeeUserId'),
      },
    },
  );
};
export const addListingToFavouritesAPI = (listingId) => {
  return axios.post(`${AUTH_BASE_URL}/favorites`, { listing_id: listingId });
};

export const deleteListingFromFavAPI = (listingId) => {
  return axios.delete(`${AUTH_BASE_URL}/favorites/${listingId}`);
};

export const getExtListingDetailsAPI = (
  item,
  keyword = 'cups',
  currency = 'USD',
  type = 'keyword',
) => {
  return axios.post(
    `${AUTH_BASE_URL}/etsy_apis/listing`,
    JSON.stringify({
      listing_ids: item,
      search_term: keyword,
      user_currency: currency,
      type: type,
    }),
  );
};
