/*global chrome*/

import React from 'react';
import styled from 'styled-components';
import LockIconTooltip from '@components/CustomToolTip/LockIconTooltip';
import { useDispatch, useSelector } from 'react-redux';
import {
  changeIframeUrl,
  toggleRightPane,
} from '../../store/slices/sidebarSlice';
import { toggleSidebarTrendsModal } from '../../store/slices/utilitySlice';


const StyledIcon = styled.div`
  display: flex;
  padding: 0.125rem;
  justify-content: center;
  align-items: center;
  //gap: 0.625rem;
  border-radius: 50%;
  background: #19191a;
  width: 24px;
  height: 24px;
  cursor: pointer;
  .icon {
    width: 1rem;
    height: 1rem;
  }
`;

const LockIconDark = ({ placement='top' }) => {
  const dispatch = useDispatch();
  const lockDark = chrome.runtime.getURL('svg/lock-dark.svg');
  const { isSidebarTrendsModal } = useSelector(
    (state) => state.utilities,
  );

  const handleLockIconClick = (e) => {
    e.stopPropagation();
    dispatch(toggleRightPane(false));
    if(isSidebarTrendsModal) {
      dispatch(toggleSidebarTrendsModal(false))
    }
    setTimeout(() => {
      dispatch(changeIframeUrl('pricing'));
    }, 200);
    // dispatch(changeIframeUrl('pricing'));
  };

  return (
    <LockIconTooltip
      PopperProps={{
        style: {
          zIndex: 9999999,
        },
      }}
      title={
        <span
          style={{
            fontSize: '10px',
            color: 'inherit',
            cursor: 'pointer',
          }}
          // onClick={handleLockIconClick}
        >
          <em>Click to upgrade</em>
        </span>
      }
      placement={placement}
      arrow
      disableInteractive={true} // Prevent interaction with tooltip content
      leaveDelay={0}
    >
      <StyledIcon onClick={handleLockIconClick}>
        <img src={lockDark} alt="lock-icon" className="icon" />
      </StyledIcon>
    </LockIconTooltip>
  );
};

export default LockIconDark;
