/*global chrome*/
import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import StyledWrapper from './StyledWrapper';
import {
  changeFeaturePage,
  changeIframeUrl,
} from '../../store/slices/sidebarSlice';
import Modal from '@mui/material/Modal';
import MinimizedComponent from '../MinimizedComponent';
import { fetchFavFolderList } from '../../store/slices/favoritesSlice';

const MainExtScreen = ({ children }) => {
  const dispatch = useDispatch();
  const [isMinimized, setIsMinimized] = useState(false);
  const isSidebarExpanded = useSelector((state) => state.sidebar.isExpanded);
  const minimize = chrome.runtime.getURL('svg/minimize.svg');
  const close = chrome.runtime.getURL('svg/cross.svg');
  const [needIcons, setNeedIcons] = useState(true);
  const featurePage = useSelector((state) => state?.sidebar.featurePage);
  const iframeUrl = useSelector((state) => state?.sidebar.iframeUrl);

  const handleUrlCleanup = () => {
    const URL = new URLSearchParams(window.location.search);
    if (URL.get('openFeaturePage')) {
      URL.delete('openFeaturePage');
      URL.delete('keyword');
      const newUrl = `${window.location.origin}${window.location.pathname}?${URL.toString()}`;
      window.history.replaceState({}, '', newUrl);
    }
  };

  useEffect(() => {
    // Add a message event listener to receive messages from the iframe
    window.addEventListener('message', handleIframeMessage);
    return () => {
      // Remove the event listener when the component unmounts
      window.removeEventListener('message', handleIframeMessage);
    };
  }, []);

  const handleIframeMessage = (event) => {
    if (event.origin === process.env.REACT_APP_FRONTEND_URL) {
      const { displayToggleBox } = event.data;
      if (displayToggleBox === false) {
        setNeedIcons(true);
      }
      if (displayToggleBox === true) {
        setNeedIcons(false);
      }
    }
  };

  return (
    <>
      <Modal
        disableEnforceFocus
        // This Modal is open={true} for the whole lifetime of the extension —
        // it is only hidden visually via `sx.display` below. MUI does not care
        // about `display`: an open Modal without disableScrollLock makes
        // ModalManager slap `overflow: hidden` + a scrollbar-width
        // `padding-right` onto Etsy's <body>, which freezes the host page until
        // some other effect happens to write body.style.overflowY back. We are
        // an overlay on someone else's site — never seize their scroll.
        disableScrollLock
        open={true}
        aria-labelledby="modal-modal-title"
        hideBackdrop={true}
        aria-describedby="modal-modal-description"
        sx={{
          // Tracks the rail rather than restating its width. 72px was the old
          // common-components rail (76px collapsed, near enough); the research
          // rail is 64px, and the 8px difference showed as a white strip down
          // the left of the iframe. --ebsb-width is published on the host
          // documentElement by the sidebar itself, so the two can't drift again.
          // The fallback covers the frame before the rail has mounted.
          // (The old width was `calc(100vw-72px)` — no spaces around the minus,
          // so it was invalid and dropped; the box happened to size correctly
          // from left/right anyway.)
          width: 'calc(100vw - var(--ebsb-width, 64px))',
          height: isMinimized ? '0vh' : '100vh',
          marginLeft: 'var(--ebsb-width, 64px)',
          overflowX: 'hidden',
          overflowY: 'hidden',
          top: isMinimized ? '100vh' : '',
          transition: 'top 0.3s linear 0s,height  0.3s linear 0s',
          background: isMinimized ? ' rgba(204, 204, 204, 0.6)' : 'white',
          border: 'none',
          display: iframeUrl.includes('/ext/') ? 'block' : 'none',
          // left: isMinimized && '0',
          // right: isMinimized && '0',
        }}
      >
        <StyledWrapper
          $isMinimized={isMinimized}
          $isSidebarExpanded={isSidebarExpanded}
        >
          {needIcons ? (
            <div className="header-container">
              <div className="action-buttons">
                {!isMinimized && (
                  <div
                    className="btn-minimize eb-cta-button"
                    onClick={() => {
                      setIsMinimized(true);
                      document.body.style.overflowY = 'scroll';
                      if (featurePage.favorites) {
                        dispatch(fetchFavFolderList({ type: 'listing' }));
                      }
                    }}
                  >
                    <img src={minimize} />
                  </div>
                )}
                <div
                  className="btn-close eb-cta-button"
                  onClick={() => {
                    handleUrlCleanup();
                    dispatch(changeFeaturePage());
                    dispatch(changeIframeUrl('close'));
                    if (featurePage.favorites) {
                      dispatch(fetchFavFolderList({ type: 'listing' }));
                    }
                  }}
                >
                  <img src={close} />
                </div>
              </div>
            </div>
          ) : (
            <></>
          )}
          {children}
        </StyledWrapper>
      </Modal>
      {isMinimized && (
        <MinimizedComponent
          setIsMinimized={setIsMinimized}
          handleUrlCleanup={handleUrlCleanup}
        />
      )}
    </>
  );
};

export default MainExtScreen;
