const RenderHeader = (params) => {
  const dispatch = useDispatch();
  const { clientSortOrder, clientActiveSortColumn, sidePanTags } = useSelector(
    (state) => state.utilities,
  );
  const headerName = params.colDef?.headerName;
  const headerFieldName = params.colDef?.field;
  const headerQueryName = COLUMN_NAMES_MAP?.[headerFieldName]?.backendName;

  const handleTagsSort = (fieldName) => {
    // Client Side Sorting
    const queryName = COLUMN_NAMES_MAP[fieldName]['backendName'];
    let sortOrder = 'desc';
    dispatch(setClientActiveSortColumn(queryName));
    if (queryName !== clientActiveSortColumn) {
      if (isDataString(fieldName)) {
        dispatch(setClientSortOrder('asc'));
        sortOrder = 'asc';
      } else {
        dispatch(setClientSortOrder('desc'));
        sortOrder = 'desc';
      }
    } else {
      if (clientSortOrder === 'asc') {
        dispatch(toggleClientSortOrder('desc'));
        sortOrder = 'desc';
      } else {
        dispatch(toggleClientSortOrder('asc'));
        sortOrder = 'asc';
      }
    }

    const sortedTags = clientSideSort(sidePanTags, fieldName, sortOrder);
    dispatch(updateSidePaneTagsData(sortedTags));
  };

  return (
    <span style={{ display: 'flex', alignItems: 'center' }}>
      <div>
        <Tooltip
          title={
            <Typography
              fontSize="12px"
              fontWeight="500"
              lineHeight="14px"
              pl="5px"
            >
              {HeaderTooltipText(headerName)}
            </Typography>
          }
          placement="top"
          arrow
        >
          {clientActiveSortColumn === headerQueryName ? (
            <strong>{headerName}</strong>
          ) : (
            <span>{headerName}</span>
          )}
        </Tooltip>
      </div>
      {clientSortOrder === 'asc' ? (
        <button
          onClick={() => handleTagsSort(headerFieldName)}
          style={{ marginTop: '4px', border: 0, background: 'white' }}
        >
          <ArrowUpwardIcon
            sx={{
              fontSize: '12px',
              marginLeft: '4px',
              color: `${
                clientActiveSortColumn === headerQueryName
                  ? '#19191A'
                  : '#a2a3a3'
              }`,
            }}
          />
        </button>
      ) : (
        <button
          onClick={() => handleTagsSort(headerFieldName)}
          style={{ marginTop: '4px', border: 0, background: 'white' }}
        >
          <ArrowDownwardIcon
            sx={{
              fontSize: '12px',
              marginLeft: '4px',
              color: `${
                clientActiveSortColumn === headerQueryName
                  ? '#19191A'
                  : '#a2a3a3'
              }`,
            }}
          />
        </button>
      )}
    </span>
  );
};

const RenderKeyword = (params, loading, isTagsModal) => {
  const [copied, setCopied] = useState(null);
  const [tagsClicked, setTagsClicked] = useState(false);
  const Tick = chrome.runtime.getURL('svg/green-tick.svg');

  function copyToClipboard(text) {
    setCopied(null);
    setTagsClicked(true);
    navigator.clipboard.writeText(text).then(() => {});
    setCopied(text);

    amplitude.track('Tags_Copy', {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      tags_copy_type: 'one',
      keyword_name: text,
      source_type: isTagsModal ? 'expand_view' : 'listing_details',
    });

    setTimeout(() => {
      setTagsClicked(false);
      setCopied(null);
    }, 800);
  }

  return (
    <>
      {loading ? (
        <Skeleton
          variant="rectangular"
          animation="wave"
          height={15}
          width={45}
        />
      ) : (
        <>
          <div
            onClick={() => copyToClipboard(params.row?.keywords)}
            style={{ width: '100%' }}
          >
            <Tooltip
              PopperProps={{ style: { zIndex: 99999999 } }}
              placement="top"
              arrow
              title={
                <Typography
                  fontSize="12px"
                  fontWeight="500"
                  lineHeight="18px"
                  pl="5px"
                >
                  {copied === params.row?.keywords ? 'copied' : 'Click to copy'}{' '}
                  {params.row?.keywords}
                </Typography>
              }
            >
              <div style={{ display: 'flex', gap: '2px', width: '100%' }}>
                <Typography
                  color={'rgba(25, 25, 26, 1)'}
                  sx={{
                    fontSize: '12px',
                    fontWeight: '500',
                    lineHeight: '16px',
                    width: '100%',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                  }}
                >
                  {params.row?.keywords}
                </Typography>
                {copied === params.row?.keywords && tagsClicked && (
                  <img
                    src={Tick}
                    alt="green-tick-icon"
                    height={14}
                    width={14}
                  />
                )}
              </div>
            </Tooltip>
          </div>
        </>
      )}
    </>
  );
};

const RenderData = (type, params, loading) => {
  var textToRender;
  var colorVal = '';
  if (!loading) {
    textToRender =
      type === 'volume'
        ? params.row.volume?.toLocaleString('en-US')
        : type === 'competition'
          ? params.row.competition?.toLocaleString('en-US')
          : type === 'keywordScore'
            ? params.row.keywordScore !== null
              ? getNumberWithCommas(
                  Math.round(parseFloat(params.row.keywordScore)),
                )
              : 'N/A'
            : null;

    if (type === 'volume') {
      if (params.row.volume <= 500) colorVal = '#E55550';
      else if (params.row.volume > 500 && params.row.volume < 3000)
        colorVal = '#FBC023';
      else colorVal = '#449954';
    } else if (type === 'competition') {
      if (params.row.competition <= 5000) colorVal = '#449954';
      else if (params.row.competition > 5000 && params.row.competition < 25000)
        colorVal = '#FBC023';
      else colorVal = '#E55550';
    }
  }
  return (
    <>
      {loading ? (
        <Skeleton
          variant="rectangular"
          animation="wave"
          height={15}
          width={45}
        />
      ) : type === 'keywordScore' && params.row.keywordScore >= 100 ? (
        <div
          style={{
            display: 'flex',
            justifyContent: 'center',
            gap: '3px',
            alignItems: 'center',
          }}
        >
          <KeywordScoreIndicator
            text="High"
            borderColor="rgba(117, 185, 129, 1)"
            backgroundColor="rgba(117, 185, 129, 0.15)"
            fontColor="rgba(74, 166, 89, 1)"
          />
          <strong>
            {textToRender === null || textToRender === 0 ? '--' : textToRender}
          </strong>
        </div>
      ) : (
        <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span
            style={{
              height: '6.4px',
              width: '6px',
              borderRadius: '100%',
              backgroundColor: textToRender
                ?.toString()
                ?.includes('Please upgrade')
                ? ''
                : colorVal,
            }}
          ></span>
          <strong>
            {textToRender === null || textToRender === 0 ? '--' : textToRender}
          </strong>
        </span>
      )}
    </>
  );
};

const RenderTagFavorite = (
  params,
  loading,
  handleTagsFavoriteClick,
  isAuth,
) => {
  const dispatch = useDispatch();
  const row = params.row;
  const { userData, favoriteLimits } = useSelector((state) => state.user);

  const shouldShowKeywordLimitTooltip = checkKeywordLimit(
    userData,
    favoriteLimits,
  );

  const favFilled = chrome.runtime.getURL('svg/fav-filled.svg');
  const favUnfilled = chrome.runtime.getURL('svg/fav-unfilled.svg');

  const favIcon = (
    <img
      src={params.row?.isFav ? favFilled : favUnfilled}
      alt={params.row?.isFav ? 'favouritesSelected' : 'Favourites'}
      height={20}
      width={20}
    />
  );

  const handleUpgradeClick = (e) => {
    e.stopPropagation();
    if (isAuth) {
      dispatch(toggleRightPane(false));
      dispatch(changeFeaturePage(MAIN_MENU.PRICING));
      dispatch(changeIframeUrl('pricing'));
    } else {
      window.location.href = `${process.env.REACT_APP_AUTH_FRONTEND_APP}/login?redirect_to=https://etsy.com`;
    }
  };

  if (loading) {
    return (
      <Skeleton animation="wave" width={20} height={20} variant="circular" />
    );
  }

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'pointer',
      }}
      onClick={(e) => {
        if (shouldShowKeywordLimitTooltip && !params.row?.isFav) {
          handleUpgradeClick(e);
        } else {
          handleTagsFavoriteClick && handleTagsFavoriteClick(e, row);
        }
      }}
    >
      {shouldShowKeywordLimitTooltip && !params.row?.isFav ? (
        <HeaderTooltip
          PopperProps={{
            style: {
              zIndex: 99999999,
            },
          }}
          title={
            <>
              <i>Upgrade to favorite more items.</i>
              <br />
              <i>Click to upgrade</i>
            </>
          }
          placement="left"
        >
          <span
            style={{ display: 'flex', alignItems: 'center', lineHeight: 0 }}
          >
            {favIcon}
          </span>
        </HeaderTooltip>
      ) : (
        favIcon
      )}
    </div>
  );
};

