/*global chrome*/

/**
 * Cross-domain SSO handoff for OpoShop (oposhop.io).
 *
 * The everbee auth token lives in `chrome.storage.local` (extension context),
 * keyed by `REACT_APP_AUTH_COOKIE_NAME`. To carry the user's session across
 * domains, we encode the auth token into a short-lived XOR-JWT and append it
 * as a `?token=` query parameter. The OpoShop landing page is expected to
 * decode this token with the same `SECRET_KEY`, validate `exp`, set its own
 * `.oposhop.io` cookie, and strip the param via `history.replaceState` before
 * any client routing.
 *
 * NOTE: XOR with a shipped client-side secret is obfuscation, not real
 * cryptography. Swap to a backend-issued HS256 JWT before this guards
 * anything sensitive.
 *
 * Mirrors everbee-frontend/src/utils/oposhopRedirect.js and
 * everbee-sso-frontend/src/utils/redirectValidation.js so the three apps stay
 * in sync. Keep all implementations identical.
 */

const SECRET_KEY = 'oposhop-secret';

const base64UrlEncode = (str) => {
  return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
};

const encryptData = (data, secret) => {
  const dataBytes = new TextEncoder().encode(data);
  const secretBytes = new TextEncoder().encode(secret);
  const encrypted = new window.Uint8Array(dataBytes.length);

  for (let i = 0; i < dataBytes.length; i++) {
    encrypted[i] = dataBytes[i] ^ secretBytes[i % secretBytes.length];
  }

  return Array.from(encrypted);
};

const createJWT = (payload) => {
  const header = { alg: 'XOR', typ: 'JWT' };
  const payloadData = JSON.stringify({
    ...payload,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + 60 * 60,
  });
  const encodedHeader = base64UrlEncode(JSON.stringify(header));
  const encryptedPayload = encryptData(payloadData, SECRET_KEY);
  const encodedPayload = base64UrlEncode(
    String.fromCharCode(...encryptedPayload),
  );
  return `${encodedHeader}.${encodedPayload}.`;
};

/**
 * Returns the configured OpoShop app origin (e.g. `https://stag-store.oposhop.io`).
 */
export const getOposhopAppUrl = () =>
  process.env.REACT_APP_OPOSHOP_FRONTEND_APP || '';

/**
 * True when `redirectUrl` points at the allowlisted oposhop.io host.
 */
export const shouldHandleCrossDomainRedirect = (redirectUrl) => {
  if (!redirectUrl || typeof redirectUrl !== 'string') return false;
  const appUrl = process.env.REACT_APP_OPOSHOP_FRONTEND_APP;
  if (!appUrl) return false;
  try {
    const target = new URL(redirectUrl).hostname;
    return new URL(appUrl).hostname === target;
  } catch {
    return false;
  }
};

/**
 * Builds a destination URL on the OpoShop origin with the auth token
 * appended as `?token=<jwt>`. Throws if the destination is not an
 * allowlisted oposhop host or the token is missing — callers should catch
 * and fall back to the plain URL (user will hit the OpoShop login page).
 */
export const createCrossDomainRedirectUrl = (redirectUrl, token) => {
  if (!shouldHandleCrossDomainRedirect(redirectUrl) || !token) {
    throw new Error('Invalid redirect URL or missing token');
  }
  const url = new URL(redirectUrl);
  const jwtToken = createJWT({ token });
  url.searchParams.set('token', encodeURIComponent(jwtToken));
  return url.toString();
};

/**
 * Reads the everbee auth token from `chrome.storage.local`. The extension
 * stores it under the env-configured cookie name (see App.jsx / axiosConfig).
 * Returns `null` when chrome.storage is unavailable or the key is unset.
 */
export const getAuthTokenFromChromeStorage = async () => {
  if (
    typeof chrome === 'undefined' ||
    !chrome?.storage?.local ||
    !process.env.REACT_APP_AUTH_COOKIE_NAME
  ) {
    return null;
  }
  try {
    const key = process.env.REACT_APP_AUTH_COOKIE_NAME;
    const result = await chrome.storage.local.get(key);
    return result?.[key] || null;
  } catch {
    return null;
  }
};

/**
 * Async convenience that returns the OpoShop onboarding URL with the auth
 * token already embedded, or the plain URL if the token is unavailable.
 */
export const buildOposhopRedirectUrl = async (path = '?from_research=true') => {
  const base = `${getOposhopAppUrl()}${path}`;
  try {
    const token = await getAuthTokenFromChromeStorage();
    if (!token) return base;
    return createCrossDomainRedirectUrl(base, token);
  } catch (err) {
    console.error('OpoShop redirect token encoding failed:', err);
    return base;
  }
};
