/*global chrome*/
import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useGridApiRef } from '@mui/x-data-grid-pro';
import * as amplitude from '@amplitude/analytics-browser';
import { StyledWrapper } from './StyledWrapper';
import FramerMotion from '../../utils/FramerMotion/FramerMotion';
import { TagsTableColumns } from '../../utils/columns/tagsColumn';
import TagsTable from '../TagsTable/TagsTable';
import { AnimatePresence, motion } from 'framer-motion';
import {
  setClientActiveSortColumn,
  setIsNewFavFolderModal,
  toggleTagsModal,
  updateSidePaneTagsData,
  updateSidePaneTagsIsFav,
  updateSidePanTagsCheckedRows,
  clearSidePanTagsCheckedRows,
} from '../../store/slices/utilitySlice';
import {
  manageFavItemsInFolders,
  fetchFoldersContainingPL,
  toggleKeywordsWatchlistModal,
  setKeywordsDefaultFolderData,
  setKeywordFolderMgmtModalStatus,
  setCurrentKeywordRowData,
  unfavouritePLFromFav,
  setManagementModalStatus,
} from '../../store/slices/favoritesSlice';
import NewFavFolderModal from '../NewFavFolderModal';
import favKeywordPopup from '../FavUpdateToast/Keywords/FavKeywordPopup';
import { KeywordsWatchlistModal } from '../WatchlistModal';
import { updateFavoriteCount } from '../../store/slices/userSlice';
import KeywordSelectedRow from '../SelectedRowToolbar/KeywordSelectedRow';

const Tags = ({ TAGS_TABLE_DATA, loading, isAuth }) => {
  const dispatch = useDispatch();
  const apiRef = useGridApiRef();
  const [tagsCollapse, setTagsCollapse] = useState(true);
  const [tagsCopied, setTagsCopied] = useState(false);

  const {
    sidePanTags,
    isNewFavFolderModal,
    sidePanTagsCheckedRowIds,
    sidePanTagsCheckedRowsData,
  } = useSelector((state) => state.utilities);
  const {
    keywordsFolderData,
    keywordsDefaultFolderData,
    isKeywordsWatchlistModal,
    currentKeywordRowData,
  } = useSelector((state) => state.watchlist);
  const isKeywordFolderManagement = useSelector(
    (state) => state.watchlist.folderManagementModalStatus.keyword,
  );

  const defaultFolderDetails = keywordsDefaultFolderData.map((folder) => ({
    name: folder.name,
    id: folder.id,
  }));

  const chevronDown = chrome.runtime.getURL('svg/chevron-down.svg');
  const copyIcon = chrome.runtime.getURL('svg/copy-icon.svg');
  const maximizeIcon = chrome.runtime.getURL('svg/expand-big.svg');
  const Tick = chrome.runtime.getURL('svg/green-tick.svg');

  const copyAllTags = () => {
    if (loading) return;
    setTagsCopied(true);

    amplitude.track('Tags_Copy', {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      tags_copy_type: 'all',
      keyword_name: TAGS_TABLE_DATA.map((item) => item.keywords),
      source_type: 'listing_details',
    });

    navigator.clipboard.writeText(
      TAGS_TABLE_DATA.map((item) => item.keywords).join(', '),
    );

    setTimeout(() => {
      setTagsCopied(false);
    }, 800);
  };

  const handleExpandClick = () => {
    dispatch(toggleTagsModal(true));

    amplitude.track('Tags_Expand_Click', {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
    });
  };

  const animationOptions = {
    initialOptions: {
      opacity: 0,
    },
    animateOptions: {
      opacity: 1,
    },
    exitOptions: {
      opacity: 0,
    },
  };

  const trackFavoritesEvent = (eventName, additionalProps = {}) => {
    amplitude.track(eventName, {
      product_type: 'extension',
      feature_type: 'etsy',
      etsy_type:
        window.location.pathname === '/'
          ? 'home_page'
          : window.location.href.includes('/shop/')
            ? 'shop_page'
            : window.location.href.includes('/listing/')
              ? 'listing_page'
              : window.location.href.includes('/search?q=')
                ? 'search_results'
                : 'other_page',
      source_type: 'listing_details',
      item_type: 'keyword',
      ...additionalProps,
    });
  };

  const handleTagsFavoriteClick = async (e, row) => {
    e.stopPropagation();
    dispatch(setCurrentKeywordRowData(row));

    if (row.isFav) {
      // Unfavorite logic
      const response = await dispatch(
        fetchFoldersContainingPL({
          itemIdsArray: [row.keywordId],
          type: 'keyword_analytic',
          idType: 'database',
        }),
      ).unwrap();

      const folderIdsFromResponse =
        response?.data?.items?.flatMap((item) => item.folder_ids) || [];

      const folderDetails = keywordsFolderData
        .filter((folder) => folderIdsFromResponse.includes(folder.id))
        .map((folder) => ({
          name: folder.name,
          id: folder.id,
        }));

      await dispatch(
        unfavouritePLFromFav({
          itemId: row.keywordId,
          type: 'keyword_analytic',
          idType: 'database',
        }),
      ).unwrap();

      // Update the isFav status in the tags data
      dispatch(
        updateSidePaneTagsIsFav({
          keywordId: row.keywordId,
          isFavBool: false,
        }),
      );

      setTimeout(() => {
        favKeywordPopup(row, folderDetails, 'undo');
      }, 300);

      dispatch(updateFavoriteCount({ type: 'keywordCount', amount: -1 }));

      trackFavoritesEvent('Favorites_Remove_Click');
    } else {
      // Favorite logic
      const defaultFolderIds = keywordsDefaultFolderData.map(
        (folder) => folder.id,
      );

      if (keywordsFolderData.length === 0) {
        trackFavoritesEvent('Add_To_Favorites_Click', {
          is_first_favorites_action_of_day: true,
        });
        dispatch(setIsNewFavFolderModal(true));
      } else if (isKeywordFolderManagement || defaultFolderIds.length === 0) {
        dispatch(toggleKeywordsWatchlistModal(true));
        if (isKeywordFolderManagement) {
          trackFavoritesEvent('Add_To_Favorites_Click', {
            is_first_favorites_action_of_day: true,
          });
          dispatch(setManagementModalStatus({ itemType: 'keyword_analytic' }));
          dispatch(setKeywordFolderMgmtModalStatus(false));
        }
      } else {
        trackFavoritesEvent('Add_To_Favorites_Click', {
          target_folders_count: defaultFolderIds.length,
          is_first_favorites_action_of_day: false,
        });

        await dispatch(
          manageFavItemsInFolders({
            itemIdsArray: [row.keywordId],
            type: 'keyword_analytic',
            folderIdsArray: defaultFolderIds,
            idType: 'database',
          }),
        ).unwrap();

        setTimeout(() => {
          favKeywordPopup(row, defaultFolderDetails, 'add');
        }, 300);

        // Update the isFav status in the tags data
        dispatch(
          updateSidePaneTagsIsFav({
            keywordId: row.keywordId,
            isFavBool: true,
          }),
        );

        dispatch(updateFavoriteCount({ type: 'keywordCount', amount: 1 }));
      }
    }
  };

  useEffect(() => {
    dispatch(setClientActiveSortColumn('score'));
  }, [dispatch]);

  useEffect(() => {
    if (!tagsCollapse) {
      dispatch(clearSidePanTagsCheckedRows());
    }
  }, [tagsCollapse, dispatch]);

  useEffect(() => {
    return () => {
      dispatch(clearSidePanTagsCheckedRows());
    };
  }, [dispatch]);

  const handleRowSelectionChange = (model) => {
    const rowIds = Array.isArray(model) ? model : [...model];
    const rowsData = (TAGS_TABLE_DATA || []).filter((row) =>
      rowIds.includes(row.id),
    );
    dispatch(updateSidePanTagsCheckedRows({ rowIds, rowsData }));
  };

  const handleAfterToolbarAction = () => {
    dispatch(clearSidePanTagsCheckedRows());
  };

  const handleWatchlistBulkConfirmSuccess = (row, folderDetailsArray) => {
    favKeywordPopup(row, folderDetailsArray, 'add');
    handleAfterToolbarAction();
  };

  return (
    <StyledWrapper $tagsCollapse={tagsCollapse}>
      <div className="MoreDetailsHeadingWrapper">
        <div className="tags-wrapper">
          <h5 className="Heading main-heading">Tags</h5>
          <img
            className="down-arrow"
            src={chevronDown}
            alt="down arrow"
            onClick={() => setTagsCollapse((prev) => !prev)}
          />
        </div>
        {tagsCollapse && (
          <>
            <div className="action-buttons" style={{ visibility: sidePanTagsCheckedRowIds.length > 0 ? 'hidden' : 'visible' }}>
              {tagsCopied ? (
                <AnimatePresence>
                  <motion.div
                    variants={animationOptions}
                    initial="initialOptions"
                    animate="animateOptions"
                    exit="exitOptions"
                    transition={{ duration: 0.3 }}
                  >
                    <img
                      src={Tick}
                      alt="green-tick-icon"
                      height={15}
                      width={15}
                    />
                  </motion.div>
                </AnimatePresence>
              ) : (
                <img
                  className="btn-copy"
                  src={copyIcon}
                  alt="Copy button"
                  onClick={() => copyAllTags()}
                />
              )}
              <img
                className="down-arrow"
                src={maximizeIcon}
                alt="btn-expand"
                onClick={handleExpandClick}
              />
            </div>
            {sidePanTagsCheckedRowIds.length > 0 && (
              <KeywordSelectedRow
                noOfCheckedRows={sidePanTagsCheckedRowIds.length}
                sourceProp="sp-ta"
                sourceContext="listing_details"
                onAfterAction={handleAfterToolbarAction}
                inline={true}
                inlineTop="65%"
              />
            )}
          </>
        )}
      </div>
      {tagsCollapse && (
        <div className="tags-table-container">
          <FramerMotion delay={0.3}>
            <TagsTable
              apiRef={apiRef}
              tableData={TAGS_TABLE_DATA}
              tableColumns={TagsTableColumns(
                loading,
                /* isTagsModal */ false,
                handleTagsFavoriteClick,
                isAuth,
              )}
              loading={loading}
              checkboxSelection={true}
              onRowSelectionModelChange={handleRowSelectionChange}
              rowSelectionModel={sidePanTagsCheckedRowIds}
            />
          </FramerMotion>
        </div>
      )}

      {isNewFavFolderModal && currentKeywordRowData && (
        <NewFavFolderModal
          row={currentKeywordRowData}
          context="tags"
          onConfirmSuccess={sidePanTagsCheckedRowIds.length > 0 ? handleAfterToolbarAction : undefined}
        />
      )}

      {isKeywordsWatchlistModal && (
        <KeywordsWatchlistModal
          row={currentKeywordRowData}
          context="tags"
          bulkRowsData={sidePanTagsCheckedRowIds.length > 0 ? sidePanTagsCheckedRowsData : undefined}
          onConfirmSuccess={sidePanTagsCheckedRowIds.length > 0 ? handleWatchlistBulkConfirmSuccess : undefined}
        />
      )}
    </StyledWrapper>
  );
};

export default Tags;
