import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';
import { useState, useEffect } from 'react';
import {
  manageFavItemsInFolders,
  toggleListingsWatchlistModal,
} from '../../../store/slices/favoritesSlice';
import favPopup from './FavPopup';
import {
  setIsListingFav,
  updateExtSearchDataIsfav,
} from '../../../store/slices/utilitySlice';
import { Skeleton } from '@mui/material';

const StyledFavUpdateWrapper = styled.div`
  display: flex;
  width: 400px;
  padding: 12px;
  align-items: center;
  gap: 12px;
  border-radius: 8px;
  background: ${({ theme }) => theme.colors.background};
  box-shadow:
    0 0 24px 0 rgba(0, 0, 0, 0.15),
    0 0 12px 0 rgba(0, 0, 0, 0.12),
    0 0 0 1px rgba(0, 0, 0, 0.08);

  .image-container {
    flex-shrink: 0;
    width: 48px;
    height: 48px;
    border-radius: 8px;
    overflow: hidden;

    .productImage {
      width: 100%;
      height: 100%;
      opacity: 0;
      transition: opacity 0.8s ease-in-out;

      &.loaded {
        opacity: 1;
      }
    }
  }

  .message {
    flex: 1;
    color: ${({ theme }) => theme.colors.neutral.gray900};
    font-size: 16px;
    font-weight: 500;
    line-height: 24px;

    span {
      font-weight: 700;
    }
  }

  .cta {
    flex-shrink: 0;
    color: ${({ theme }) => theme.colors.brand.blue900};
    margin: 4px 0;
    cursor: pointer;
    font-size: 12px;
    font-weight: 500;
    line-height: 16px;
    text-decoration-line: underline;
    text-decoration-style: solid;
    text-decoration-skip-ink: auto;
    text-decoration-thickness: auto;
    text-underline-offset: auto;
    text-underline-position: from-font;
  }
`;

const FavUpdateToast = ({
  row,
  folderDetailsArray,
  action,
  context,
  onClose,
}) => {
  const closeBtn = chrome.runtime.getURL('svg/close-button.svg');

  const dispatch = useDispatch();
  const [imageLoaded, setImageLoaded] = useState(false);
  const folderNamesArray = folderDetailsArray.map((folder) => folder.name);
  const folderIdsArray = folderDetailsArray.map((folder) => folder.id);
  const imageUrl =
    context === 'singleListing' ||
    context === 'ImageAndDetails' ||
    context === 'HeadingAndIcons'
      ? row.image
      : context === 'onPageSingleListing'
        ? row.productPhoto
        : '';

  const handleImageLoad = () => {
    setImageLoaded(true);
  };

  const handleCTAClick = () => {
    if (action === 'add') {
      setTimeout(() => {
        dispatch(toggleListingsWatchlistModal(true));
      }, 300);
      onClose();
    } else if (action === 'undo') {
      dispatch(
        manageFavItemsInFolders({
          itemIdsArray: [row.listingId],
          type: 'listing',
          folderIdsArray: folderIdsArray,
        }),
      ).then((response) => {
        if (response?.payload) {
          if (context === 'singleListing') {
            dispatch(setIsListingFav(true));
          } else if (context === 'onPageSingleListing') {
            dispatch(
              updateExtSearchDataIsfav({
                listingId: row.listingId,
                isFavBool: true,
              }),
            );
          } else if (
            context === 'ImageAndDetails' ||
            context === 'HeadingAndIcons'
          ) {
            dispatch(setIsListingFav(true));
            dispatch(
              updateExtSearchDataIsfav({
                listingId: row.listingId,
                isFavBool: true,
              }),
            );
          }
          setTimeout(() => {
            favPopup(row, folderDetailsArray, 'add', context);
          }, 300);
        }
      });

      onClose();
    }
  };

  const getDisplayTitle = () => {
    if (!Array.isArray(folderNamesArray)) {
      return folderNamesArray; // If it's not an array, return as is
    }

    if (folderNamesArray.length === 1) {
      return folderNamesArray[0];
    }

    if (folderNamesArray.length > 1) {
      const additionalCount = folderNamesArray.length - 1;
      const folderText = additionalCount === 1 ? 'folder' : 'folders';
      return `${folderNamesArray[0]} +${additionalCount} ${folderText}`;
    }

    return ''; // Empty array case
  };

  return (
    <StyledFavUpdateWrapper>
      <div className="image-container">
        {!imageLoaded && (
          <Skeleton variant="rectangular" width="100%" height="100%" />
        )}
        <img
          src={imageUrl}
          alt="ListingIcon"
          className={`productImage ${imageLoaded ? 'loaded' : ''}`}
          onLoad={handleImageLoad}
        />
      </div>
      <div className="message">
        {action === 'add' ? 'Saved to ' : 'Removed from '}{' '}
        <span>{getDisplayTitle()}</span>
      </div>
      <div className="cta" onClick={handleCTAClick}>
        {action === 'add' ? 'Change' : 'Undo'}
      </div>
    </StyledFavUpdateWrapper>
  );
};

export default FavUpdateToast;
