'use client';

import React from 'react';
import { useSelector } from 'react-redux';
import StorePromoBanner from '../StorePromoBanner/StorePromoBanner';
import OhoneyPromoBanner from '../OhoneyPromoBanner/OhoneyPromoBanner';

/**
 * Single entry point for the cross-sell promo banners (RESEARCH-3192).
 *
 * The backend decides which product campaign is live via feature flags and
 * reports it as `active_banner_product` on /users/show: `'ohoney'`, `'oposhop'`
 * or `null` when both flags are off. Only one banner ever renders, and each
 * product tracks its dismissals under its own `ui_flags` key.
 *
 * The match is strict: anything other than those two values — `null`, or
 * `undefined` before /users/show has resolved — renders no banner.
 */
const PromoBanner = ({ variant = 'default', touchpoint }) => {
  const activeBannerProduct = useSelector(
    (state) => state.user.userData?.active_banner_product,
  );

  if (activeBannerProduct === 'ohoney') {
    return <OhoneyPromoBanner variant={variant} touchpoint={touchpoint} />;
  }

  if (activeBannerProduct === 'oposhop') {
    return <StorePromoBanner variant={variant} touchpoint={touchpoint} />;
  }

  return null;
};

export default PromoBanner;
