import {
  FindAllByAttributeValue,
  FindByAttributeValue,
} from './getElementThroughAttribute';

export const AnalyzeButton = (
  UrlLink,
  handleShopClick,
  handleClick,
  everBeeLogo,
  pendingAmplitudeTrackRef,
  getEtsyPageType,
) => {
  if (UrlLink.includes('/listing/')) {
    // adding analytics icon
    const titleEl = FindByAttributeValue('data-buy-box-listing-title', 'true');

    // Safety checks
    if (!titleEl) return;

    const checkElementIsPresent = document.querySelector(
      '#everbee-analytics-btn',
    );
    if (checkElementIsPresent === null) {
      const listingContainer = document.querySelector(
        '.image-carousel-container',
      )?.parentElement;

      const listingId = listingContainer?.getAttribute(
        'data-palette-listing-id',
      );
      if (!listingId) return;

      // Create wrapper
      const wrapper = document.createElement('div');
      wrapper.className = 'everbee-analytics-wrapper';

      // Create button
      const button = document.createElement('button');
      button.id = 'everbee-analytics-btn';
      button.setAttribute('data-listing-id1', listingId);
      button.innerHTML = `
        <img width="25"
            src="${everBeeLogo}"
            alt="Everbee logo" />
        <span>Analyze listing</span>
      `;

      // Insert AFTER h1
      titleEl.insertAdjacentElement('afterend', wrapper);
      wrapper.appendChild(button);
      const analyticsBtn = document.getElementById('everbee-analytics-btn');
      if (analyticsBtn) {
        analyticsBtn?.addEventListener('click', (e) => {
          let lid = analyticsBtn.getAttribute('data-listing-id1');
          pendingAmplitudeTrackRef.current = {
            source_type: 'etsy_listing_page',
            etsy_type: getEtsyPageType(),
          };
          handleClick(e, lid);
        });
      }
    }
  } else if (UrlLink.includes('/shop/')) {
    let followButtonContainer = FindByAttributeValue(
      'class',
      'wt-display-flex-xs wt-align-content-center wt-flex-gap-xs-1 wt-mb-xs-1 wt-mb-lg-0',
    );
    const checkElementIsPresent = document.querySelector(
      '#everbee-shop-analytics-btn',
    );
    if (followButtonContainer?.length <= 0) {
      // Empty
    } else if (
      checkElementIsPresent === null &&
      followButtonContainer != undefined
    ) {
      followButtonContainer.innerHTML += `<button  id="everbee-shop-analytics-btn"><img width="20px" src=${everBeeLogo} alt="logo" />Analyze shop</button>`;
      const analyticsBtn = document.getElementById(
        'everbee-shop-analytics-btn',
      );
      if (analyticsBtn) {
        analyticsBtn?.addEventListener('click', (e) => {
          handleShopClick(e);
        });
      }
    }
  }
};
