import { toast } from 'react-toastify';

/**
 * position POSSIBLE VALUES -
 * top-center
 * top-left
 * bottom-left
 * bottom-center
 * bottom-right
 */

/**
 * toastType POSSIBLE VALUES -
 * success
 * error
 * warn
 * info
 * default
 */

const Toast = (
  message = 'Default Message Here',
  toastType = 'default',
  position = 'bottom-right',
) => {
  const closeIcon = chrome.runtime.getURL('svg/close-button.svg');
  const successIcon = chrome.runtime.getURL('svg/success.svg');
  const infoIcon = chrome.runtime.getURL('svg/info-circle-toast.svg');
  const warningIcon = chrome.runtime.getURL('svg/warning-triangle.svg');
  const errorIcon = chrome.runtime.getURL('svg/error-circle.svg');
  let toastPosition;
  switch (position) {
    case 'top-center':
      toastPosition = 'top-center';
      break;
    case 'top-left':
      toastPosition = 'top-left';
      break;

    case 'bottom-left':
      toastPosition = 'bottom-left';
      break;

    case 'bottom-center':
      toastPosition = 'bottom-center';
      break;

    case 'bottom-right':
      toastPosition = 'bottom-right';
      break;
  }

  switch (toastType) {
    case 'success':
      toast.success(
        <div>
          <strong>Success!</strong>
          <p>{message}</p>
        </div>,
        {
          position: toastPosition,
          icon: <img alt="Success" src={successIcon} />,
          closeButton: ({ closeToast }) => (
            <img alt="Close Toast" src={closeIcon} onClick={closeToast} />
          ),
        },
      );
      break;
    case 'error':
      toast.error(
        <div>
          <strong>Error!</strong>
          <p>{message}</p>
        </div>,
        {
          position: toastPosition,
          icon: <img alt="Error" src={errorIcon} />,
          // closeButton: <img alt="Close Toast" src={closeIcon} />,
          closeButton: ({ closeToast }) => (
            <img alt="Close Toast" src={closeIcon} onClick={closeToast} />
          ),
        },
      );
      break;
    case 'warn':
      toast.warn(
        <div>
          <strong>Warning!</strong>
          <p>{message}</p>
        </div>,
        {
          position: toastPosition,
          icon: <img alt="Warning" src={warningIcon} />,
          closeButton: ({ closeToast }) => (
            <img alt="Close Toast" src={closeIcon} onClick={closeToast} />
          ),
        },
      );
      break;
    case 'info':
      toast.info(
        <div>
          <strong>Info!</strong>
          <p>{message}</p>
        </div>,
        {
          position: toastPosition,
          icon: <img alt="Info" src={infoIcon} />,
          closeButton: ({ closeToast }) => (
            <img alt="Close Toast" src={closeIcon} onClick={closeToast} />
          ),
        },
      );
      break;
    case 'default':
      toast(message, {
        position: toastPosition,
        icon: <img alt="Success" src={successIcon} />,
        closeButton: ({ closeToast }) => (
          <img alt="Close Toast" src={closeIcon} onClick={closeToast} />
        ),
      });
  }
};

export default Toast;
