import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import {
  getAllFoldersPL,
  createNewFolderPL,
  manageFavItemsInFoldersAPI,
  getFoldersContainingPL,
  unfavouritePLFromFavAPI,
  getManagementModalStatusAPI,
  setManagementModalStatusAPI,
} from '../../services/favorites';
import Toast from '@components/StyledToastContainer/toast';

const initialState = {
  listingsFolderData: [],
  listingsDefaultFolderData: [],
  keywordsFolderData: [],
  keywordsDefaultFolderData: [],
  shopsFolderData: [],
  shopsDefaultFolderData: [],
  currentKeywordRowData: null,
  loading: false,
  error: null,
  folderManagementModalStatus: {
    listing: false,
    shop: false,
    keyword: false,
  },
  isListingsWatchlistModal: false,
  isKeywordsWatchlistModal: false,
  isShopsWatchlistModal: false,
};

export const fetchFavFolderList = createAsyncThunk(
  'watchlist/fetchPLFolders',
  async ({ type }, thunkAPI) => {
    try {
      const response = await getAllFoldersPL(type);
      return { data: response.data, type };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const createNewFavFolder = createAsyncThunk(
  'watchlist/createNewFolder',
  async ({ folderName, type }, thunkAPI) => {
    try {
      const response = await createNewFolderPL(folderName, type);
      return { data: response.data, newFolderName: folderName };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const manageFavItemsInFolders = createAsyncThunk(
  'watchlist/addListingToFolder',
  async ({ itemIdsArray, type, folderIdsArray, idType }, thunkAPI) => {
    try {
      const response = await manageFavItemsInFoldersAPI(
        itemIdsArray,
        type,
        folderIdsArray,
        idType,
      );
      return {
        data: response.data,
      };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const unfavouritePLFromFav = createAsyncThunk(
  'watchlist/unfavouritePLFromFav',
  async ({ itemId, type, idType }, thunkAPI) => {
    try {
      const response = await unfavouritePLFromFavAPI(itemId, type, idType);
      return { data: response.data };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const fetchManagementModalStatus = createAsyncThunk(
  'watchlist/fetchManagementModalStatus',
  async (_, thunkAPI) => {
    try {
      const response = await getManagementModalStatusAPI();
      return { data: response.data };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const setManagementModalStatus = createAsyncThunk(
  'watchlist/setManagementModalStatus',
  async ({ itemType }, thunkAPI) => {
    try {
      const response = await setManagementModalStatusAPI(itemType);
      return { data: response.data };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const fetchFoldersContainingPL = createAsyncThunk(
  'watchlist/fetchFoldersContainingPL',
  async ({ itemIdsArray, type, idType }, thunkAPI) => {
    try {
      const response = await getFoldersContainingPL(itemIdsArray, type, idType);
      return { data: response.data };
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response.data);
    }
  },
);

export const watchlistSlice = createSlice({
  name: 'watchlist',
  initialState,
  reducers: {
    setListingsFolderData: (state, { payload }) => {
      state.listingsFolderData = payload;
    },
    setKeywordsFolderData: (state, { payload }) => {
      state.keywordsFolderData = payload;
    },
    setShopsFolderData: (state, { payload }) => {
      state.shopsFolderData = payload;
    },
    setListingsDefaultFolderData: (state, { payload }) => {
      state.listingsDefaultFolderData = payload;
    },
    setKeywordsDefaultFolderData: (state, { payload }) => {
      state.keywordsDefaultFolderData = payload;
    },
    setShopsDefaultFolderData: (state, { payload }) => {
      state.shopsDefaultFolderData = payload;
    },
    toggleListingsWatchlistModal: (state, { payload }) => {
      state.isListingsWatchlistModal = payload;
    },
    toggleKeywordsWatchlistModal: (state, { payload }) => {
      state.isKeywordsWatchlistModal = payload;
    },
    toggleShopsWatchlistModal: (state, { payload }) => {
      state.isShopsWatchlistModal = payload;
    },
    setCurrentKeywordRowData: (state, { payload }) => {
      state.currentKeywordRowData = payload;
    },
    setListingFolderMgmtModalStatus: (state, { payload }) => {
      state.folderManagementModalStatus.listing = payload;
    },
    setKeywordFolderMgmtModalStatus: (state, { payload }) => {
      state.folderManagementModalStatus.keyword = payload;
    },
    setShopFolderMgmtModalStatus: (state, { payload }) => {
      state.folderManagementModalStatus.shop = payload;
    },
  },
  extraReducers: (builder) => {
    builder.addCase(fetchFoldersContainingPL.pending, (state) => {
      // state.loading = true;
    });
    builder.addCase(
      fetchFoldersContainingPL.fulfilled,
      (state, { payload }) => {
        state.loading = false;
      },
    );
    builder.addCase(fetchFoldersContainingPL.rejected, (state, { payload }) => {
      state.loading = false;
      state.error = payload;
    });
    builder.addCase(fetchFavFolderList.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(fetchFavFolderList.fulfilled, (state, { payload }) => {
      if (payload.type === 'listing') {
        state.listingsFolderData = [...payload.data.folders];
        state.listingsDefaultFolderData = payload.data.folders.filter(
          (folder) => folder.is_default === true,
        );
      } else if (payload.type === 'keyword_analytic') {
        state.keywordsFolderData = [...payload.data.folders];
        state.keywordsDefaultFolderData = payload.data.folders.filter(
          (folder) => folder.is_default === true,
        );
      } else if (payload.type === 'shop') {
        state.shopsFolderData = [...payload.data.folders];
        state.shopsDefaultFolderData = payload.data.folders.filter(
          (folder) => folder.is_default === true,
        );
      }
      state.loading = false;
    });
    builder.addCase(fetchFavFolderList.rejected, (state, { payload }) => {
      state.loading = false;
      state.error = payload;
    });
    builder.addCase(createNewFavFolder.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(createNewFavFolder.fulfilled, (state, { payload }) => {
      if (payload.type === 'listing') {
        state.listingsFolderData = [
          state.listingsFolderData[0],
          {
            name: payload.data.folder.name,
            count: 0,
            id: payload.data.folder.id,
          },
          ...state.listingsFolderData.slice(1),
        ];
      } else if (payload.type === 'keyword_analytic') {
        state.keywordsFolderData = [
          state.keywordsFolderData[0],
          {
            name: payload.data.folder.name,
            count: 0,
            id: payload.data.folder.id,
          },
          ...state.keywordsFolderData.slice(1),
        ];
      } else if (payload.type === 'shop') {
        state.shopsFolderData = [
          state.shopsFolderData[0],
          {
            name: payload.data.folder.name,
            count: 0,
            id: payload.data.folder.id,
          },
          ...state.shopsFolderData.slice(1),
        ];
      }
      if (payload.showToast) {
        Toast('Folder created successfully.', 'success');
      }
      state.loading = false;
    });
    builder.addCase(createNewFavFolder.rejected, (state, { payload }) => {
      state.loading = false;
      state.error = payload;
      Toast(payload?.data?.message || 'Failed to create folder', 'error');
    });
    builder.addCase(manageFavItemsInFolders.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(manageFavItemsInFolders.fulfilled, (state, { payload }) => {
      state.loading = false;
    });
    builder.addCase(manageFavItemsInFolders.rejected, (state, { payload }) => {
      state.loading = false;
      state.error = payload;
    });
    builder.addCase(unfavouritePLFromFav.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(unfavouritePLFromFav.fulfilled, (state, { payload }) => {
      state.loading = false;
    });
    builder.addCase(unfavouritePLFromFav.rejected, (state, { payload }) => {
      state.loading = false;
      state.error = payload;
    });
    builder.addCase(fetchManagementModalStatus.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(
      fetchManagementModalStatus.fulfilled,
      (state, { payload }) => {
        Object.assign(state.folderManagementModalStatus, {
          listing: payload?.data?.show_manage_listing_modal,
          keyword: payload?.data?.show_manage_keyword_modal,
          shop: payload?.data?.show_manage_shop_modal,
        });

        state.loading = false;
      },
    );
    builder.addCase(
      fetchManagementModalStatus.rejected,
      (state, { payload }) => {
        state.loading = false;
        state.error = payload;
      },
    );

    builder.addCase(setManagementModalStatus.pending, (state) => {
      state.loading = true;
    });
    builder.addCase(
      setManagementModalStatus.fulfilled,
      (state, { payload }) => {
        state.loading = false;
      },
    );
    builder.addCase(setManagementModalStatus.rejected, (state, { payload }) => {
      state.loading = false;
      state.error = payload;
    });
  },
});

export const {
  setListingsFolderData,
  setKeywordsFolderData,
  setShopsFolderData,
  setListingsDefaultFolderData,
  setKeywordsDefaultFolderData,
  setShopsDefaultFolderData,
  toggleListingsWatchlistModal,
  toggleKeywordsWatchlistModal,
  toggleShopsWatchlistModal,
  setCurrentKeywordRowData,
  setListingFolderMgmtModalStatus,
  setKeywordFolderMgmtModalStatus,
  setShopFolderMgmtModalStatus,
} = watchlistSlice.actions;

export default watchlistSlice.reducer;
