/*global chrome*/
import React, { useState, useEffect, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import * as amplitude from '@amplitude/analytics-browser';
import {
  changeActiveDiscountUnit,
  changeEtsyAdUnit,
} from '../../../store/slices/utilitySlice';
import RightSidePaneTooltip from '@components/CustomToolTip/RightSidePaneTooltip';
// import debounce from '../../../utils/debounce';
import StyledWrapper from './StyledWrapper';
import HeaderTooltip from '../../CustomToolTip/HeaderTooltip';

const InputContainer = ({
  etsyCalState,
  setEtsyCalState,
  displayText,
  inputBehaviour,
  withPercent = false,
  selectOptions = [],
  name = null,
  value,
  formRef,
}) => {
  const arrowDown = chrome.runtime.getURL('svg/arrow-down.svg');
  const infoCircle = chrome.runtime.getURL('svg/info-circle.svg');

  const [isSelectActive, setIsSelectActive] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const activeDiscountUnit = useSelector(
    (state) => state.utilities.activeDiscountUnit,
  );
  const activeEtsyAdUnit = useSelector(
    (state) => state.utilities.activeEtsyAdUnit,
  );

  const dispatch = useDispatch();
  const ref = useRef();

  const handleFocus = () => {
    setIsFocused(true);
  };

  const handleBlur = () => {
    setIsFocused(false);
  };

  const handleOptionClick = (item) => {
    if (displayText === 'Advertising') {
      setEtsyCalState({ ...etsyCalState, advertising: item });
    } else if (displayText === 'Payment Method') {
      setEtsyCalState({ ...etsyCalState, paymentMethod: item });
    } else if (displayText === 'Offsite Ads') {
      setEtsyCalState({ ...etsyCalState, offSiteAdCost: item });
    }
  };

  const handleInputChange = (e) => {
    amplitude.track('Calculator - extension');
    if (e.target.name === 'discounts') {
      setEtsyCalState({
        ...etsyCalState,
        [e.target.name]: Number(-1 * e.target.value),
      });
    } else {
      setEtsyCalState({
        ...etsyCalState,
        [e.target.name]: Number(e.target.value),
      });
    }
  };

  const dispatchActionForUnit = (name, unit) => {
    if (name === 'discounts') {
      dispatch(changeActiveDiscountUnit(unit));
    } else if (name === 'etsyAds') {
      dispatch(changeEtsyAdUnit(unit));
    }
  };

  const handleSelectClick = () => {
    setIsSelectActive((prev) => !prev);
    setTimeout(() => {
      formRef.current.scrollIntoView({ behavior: 'smooth' });
    }, 0);
  };

  const getTooltipText = (title) => {
    switch (title) {
      case 'Sales Price':
        return 'Listed price of the item';
      case 'Shipping Price':
        return 'Shipping cost that is paid by  your customers';
      case 'Discounts':
        return 'Discount offered on the item';
      case 'Cost of Item':
        return 'Your costs for selling the item (Default is 40% of list price for physical products)';
      case 'Material Cost of Item 1':
        return 'Your item’s raw materials cost';
      case 'Material Cost of Item 2':
        return 'Your item’s raw materials cost';
      case 'Labor Cost of Item':
        return 'Your labor cost to build item';
      case 'Packaging Cost of Order':
        return 'Your cost to package item to be ready for shipment';
      case 'Shipping Cost for Order':
        return 'Your cost to ship this order. (Default is $4.5 for physical products)';
      case 'Advertising':
        return 'Your advertising costs';
      case 'Payment Method':
        return 'Your payment processing fees depending on the selected payment method';
      case 'Etsy Ads-Est. ACoS':
        return 'Etsy Ads-Est. ACoS';
      case 'Offsite Ads':
        return 'Offsite Ads';
      default:
        return displayText;
    }
  };

  // const debouncedHandleInputChange = debounce(handleInputChange, 500);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (ref.current && !ref.current.contains(event.target)) {
        setIsSelectActive(false);
      }
    };
    document.addEventListener('click', handleClickOutside, true);
    return () => {
      document.removeEventListener('click', handleClickOutside, true);
    };
  }, []);

  return (
    <StyledWrapper
      $inputName={name}
      $withPercent={withPercent}
      $activeDiscountUnit={activeDiscountUnit}
      $activeEtsyAdUnit={activeEtsyAdUnit}
    >
      <div className="input-name">
        {displayText}
        <RightSidePaneTooltip
          PopperProps={{
            style: {
              zIndex: 9999999,
            },
          }}
          title={getTooltipText(displayText)}
          placement="top"
          arrow
        >
          <img src={infoCircle} alt="Info Tooltip" />{' '}
        </RightSidePaneTooltip>
      </div>
      {inputBehaviour === 'number' ? (
        <div className="input-container">
          <div
            className="logo-dollar"
            onClick={() => dispatchActionForUnit(name, 'dollar')}
          >
            $
          </div>
          {withPercent && (
            <div
              className="logo-percent"
              onClick={() => dispatchActionForUnit(name, 'percent')}
            >
              %
            </div>
          )}
          <input
            className="input-box"
            type="number"
            placeholder={isFocused ? '' : '0'}
            name={name}
            value={
              value === 0 || value === undefined
                ? ''
                : value < 0
                  ? -1 * value
                  : value
            }
            onChange={handleInputChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
          />
        </div>
      ) : null}

      {inputBehaviour === 'select' ? (
        <div
          className="input-container-select"
          onClick={handleSelectClick}
          ref={ref}
        >
          <div className="select">
            {displayText === 'Advertising' && (
              <span>{etsyCalState.advertising}</span>
            )}
            {displayText === 'Payment Method' && (
              <span>{etsyCalState.paymentMethod}</span>
            )}
            {displayText === 'Offsite Ads' && (
              <span>{etsyCalState.offSiteAdCost}</span>
            )}
            <img src={arrowDown} alt="arrow down"></img>
          </div>
          {isSelectActive && (
            <div className="option-list">
              {selectOptions.map((item) => (
                <div
                  key={item}
                  className="options"
                  onClick={() => handleOptionClick(item)}
                >
                  {item}
                </div>
              ))}
            </div>
          )}
        </div>
      ) : null}
    </StyledWrapper>
  );
};

export default InputContainer;
